  }
  static SchemaConverter C = new SchemaConverter();
  static MessageType msg(Type t) { return Types.buildMessage().addField(t).named("root"); }
  static Schema one(Field f) { return new Schema(List.of(f)); }
  public static void main(String[] a) {
    tryIt("fromArrow time64 millis", () -> C.fromArrow(one(Field.nullable("t", new ArrowType.Time(TimeUnit.MILLISECOND, 64)))).getParquetSchema());
    tryIt("fromArrow ts micros empty tz", () -> C.fromArrow(one(Field.nullable("t", new ArrowType.Timestamp(TimeUnit.MICROSECOND, "")))).getParquetSchema());
    tryIt("fromArrow ts micros UTC", () -> C.fromArrow(one(Field.nullable("t", new ArrowType.Timestamp(TimeUnit.MICROSECOND, "UTC")))).getParquetSchema());
    tryIt("fromArrow largeUtf8", () -> C.fromArrow(one(Field.nullable("s", new ArrowType.LargeUtf8()))).getParquetSchema());
    tryIt("fromArrow utf8view", () -> C.fromArrow(one(Field.nullable("s", new ArrowType.Utf8View()))).getParquetSchema());
    tryIt("fromArrow largeBinary", () -> C.fromArrow(one(Field.nullable("s", new ArrowType.LargeBinary()))).getParquetSchema());
    tryIt("fromArrow binaryView", () -> C.fromArrow(one(Field.nullable("s", new ArrowType.BinaryView()))).getParquetSchema());
