    tryIt("fromArrow fixedSizeList", () -> C.fromArrow(one(new Field("l", FieldType.nullable(new ArrowType.FixedSizeList(2)), List.of(Field.nullable("e", new ArrowType.Int(32,true)))))).getParquetSchema());
    tryIt("fromArrow listView", () -> C.fromArrow(one(new Field("l", FieldType.nullable(new ArrowType.ListView()), List.of(Field.nullable("e", new ArrowType.Int(32,true)))))).getParquetSchema());
    tryIt("fromArrow largeListView", () -> C.fromArrow(one(new Field("l", FieldType.nullable(new ArrowType.LargeListView()), List.of(Field.nullable("e", new ArrowType.Int(32,true)))))).getParquetSchema());
    tryIt("fromArrow struct non-nullable", () -> C.fromArrow(one(new Field("s", FieldType.notNullable(new ArrowType.Struct()), List.of(Field.notNullable("c", new ArrowType.Int(32,true)))))).getParquetSchema());
    tryIt("fromArrow list nonnullable elem", () -> C.fromArrow(one(new Field("l", FieldType.notNullable(new ArrowType.List()), List.of(Field.notNullable("e", new ArrowType.Int(32,true)))))).getParquetSchema());
    tryIt("roundtrip struct/list/map", () -> {
      Schema s = new Schema(List.of(
        new Field("s", FieldType.nullable(new ArrowType.Struct()), List.of(Field.nullable("c", new ArrowType.Int(32,true)))),
        new Field("l", FieldType.nullable(new ArrowType.List()), List.of(Field.nullable("e", new ArrowType.Int(32,true)))),
        new Field("m", FieldType.nullable(new ArrowType.Map(false)), List.of(Field.nullable("k", new ArrowType.Utf8()), Field.nullable("v", new ArrowType.Int(32,true))))));
      SchemaMapping fm = C.fromArrow(s);
      System.out.println("  parquet=" + fm.getParquetSchema());
      SchemaMapping back = C.fromParquet(fm.getParquetSchema());
      System.out.println("  arrow=" + back.getArrowSchema());
      SchemaMapping remap = C.map(s, fm.getParquetSchema());
      System.out.println("  remap=" + remap.getChildren().stream().map(x -> x.getClass().getSimpleName()).toList());
      return back.getChildren().stream().map(x -> x.getClass().getSimpleName()).toList();
    });
    tryIt("map list element type mismatch", () -> C.map(
        one(new Field("l", FieldType.nullable(new ArrowType.List()), List.of(Field.nullable("e", new ArrowType.Int(64,true))))),
        msg(Types.optionalList().element(Types.optional(PrimitiveTypeName.INT32).named("element")).named("l"))));
    tryIt("fromParquet list child name/repetition", () -> {
