      SchemaMapping sm = C.fromParquet(m);
      Field f = sm.getArrowSchema().getFields().get(0);
      return "name=" + f.getName() + " nullable=" + f.isNullable() + " childName=" + f.getChildren().get(0).getName() + " childNullable=" + f.getChildren().get(0).isNullable();
    });
    tryIt("unmodifiable children", () -> {
      SchemaMapping sm = C.fromArrow(one(Field.nullable("a", new ArrowType.Bool())));
      sm.getChildren().add(null);
      return "no throw";
    });
    tryIt("fromArrow Decimal(0 scale)", () -> C.fromArrow(one(Field.nullable("d", new ArrowType.Decimal(5, 0)))).getParquetSchema());
    tryIt("fromArrow Decimal(38,10)", () -> C.fromArrow(one(Field.nullable("d", new ArrowType.Decimal(38, 10)))).getParquetSchema());
    tryIt("map struct nested", () -> {
