      return C.fromParquet(m).getArrowSchema();
    });
    tryIt("fromParquet map key not required", () -> {
      MessageType m = msg(new GroupType(Repetition.OPTIONAL, "m", OriginalType.MAP, Types.repeatedGroup().addField(Types.optional(PrimitiveTypeName.INT32).named("k")).addField(Types.optional(PrimitiveTypeName.INT32).named("v")).named("key_value")));
      return C.fromParquet(m).getArrowSchema();
    });
    tryIt("fromParquet list of list", () -> {
      MessageType m = msg(Types.optionalList().element(Types.optionalList().element(Types.optional(PrimitiveTypeName.INT32).named("e")).named("inner")).named("outer"));
      SchemaMapping sm = C.fromParquet(m);
      return sm.getArrowSchema() + " childClass=" + sm.getChildren().get(0).getClass().getSimpleName();
    });
  }
}
