import org.apache.arrow.vector.types.pojo.*;
import org.apache.parquet.schema.*;
import org.apache.parquet.schema.PrimitiveType.PrimitiveTypeName;
import org.apache.parquet.schema.Type.Repetition;
import java.util.*;
import org.apache.parquet.arrow.schema.*;
import org.apache.parquet.arrow.schema.SchemaMapping.*;

public class Probe6 {
  static SchemaConverter C = new SchemaConverter();
  public static void main(String[] a) {
    // identity of message fields
    Schema s = new Schema(List.of(
      new Field("s", FieldType.nullable(new ArrowType.Struct()), List.of(Field.nullable("b", new ArrowType.Bool()))),
      Field.nullable("p", new ArrowType.Utf8())));
    SchemaMapping fm = C.fromArrow(s);
    System.out.println("parquet="+fm.getParquetSchema());
    for (int i=0;i<fm.getChildren().size();i++)
      System.out.println("  identity["+i+"]="+(fm.getParquetSchema().getFields().get(i) == fm.getChildren().get(i).getParquetType()));
    System.out.println("  arrowSchema same="+(fm.getArrowSchema()==s)+" childArrowField same="+(fm.getChildren().get(0).getArrowField()==s.getFields().get(0)));
    // repeated primitive mapping via map()
    Schema arrowList = new Schema(List.of(new Field("r", FieldType.nullable(new ArrowType.List()), List.of(Field.nullable("e", new ArrowType.Int(32,true))))));
    MessageType repeated = Types.buildMessage().addField(Types.repeated(PrimitiveTypeName.INT32).named("r")).named("root");
    SchemaMapping m = C.map(arrowList, repeated);
    TypeMapping tm = m.getChildren().get(0);
    System.out.println("repeated map class="+tm.getClass().getSimpleName()+" parquetSame="+(tm.getParquetType()==repeated.getFields().get(0))+" children="+tm.getChildren().size()+" childClass="+tm.getChildren().get(0).getClass().getSimpleName()+" childParquetSame="+(tm.getChildren().get(0).getParquetType()==repeated.getFields().get(0)));
    // fromParquet repeated primitive details
    SchemaMapping pm = C.fromParquet(repeated);
    Field rf = pm.getArrowSchema().getFields().get(0);
    System.out.println("fromParquet repeated: name="+rf.getName()+" nullable="+rf.isNullable()+" type="+rf.getType()+" childName="+rf.getChildren().get(0).getName()+" childNullable="+rf.getChildren().get(0).isNullable()+" class="+pm.getChildren().get(0).getClass().getSimpleName());
    // fromParquet required date
    System.out.println("required date: "+C.fromParquet(Types.buildMessage().addField(Types.required(PrimitiveTypeName.INT32).as(LogicalTypeAnnotation.dateType()).named("d")).named("root")).getArrowSchema());
    // union via map()
    Schema arrowUnion = new Schema(List.of(new Field("u", FieldType.nullable(new ArrowType.Union(org.apache.arrow.vector.types.UnionMode.Sparse, new int[]{0,1})), List.of(Field.nullable("x", new ArrowType.Int(32,true)), Field.nullable("y", new ArrowType.Utf8())))));
    MessageType unionGroup = Types.buildMessage().addField(Types.optionalGroup().addField(Types.optional(PrimitiveTypeName.INT32).named("x")).addField(Types.optional(PrimitiveTypeName.BINARY).as(LogicalTypeAnnotation.stringType()).named("y")).named("u")).named("root");
    SchemaMapping um = C.map(arrowUnion, unionGroup);
    System.out.println("union class="+um.getChildren().get(0).getClass().getSimpleName()+" n="+um.getChildren().get(0).getChildren().size());
    // fromArrow union
    System.out.println("fromArrow union parquet="+C.fromArrow(arrowUnion).getParquetSchema());
    // map() struct child count mismatch
    try {
      C.map(new Schema(List.of(new Field("s", FieldType.nullable(new ArrowType.Struct()), List.of(Field.nullable("b", new ArrowType.Bool()))))),
            Types.buildMessage().addField(Types.optionalGroup().addField(Types.optional(PrimitiveTypeName.INT32).named("x")).addField(Types.optional(PrimitiveTypeName.INT32).named("y")).named("s")).named("root"));
    } catch (Throwable t) { System.out.println("struct mismatch -> "+t); }
    // fromArrow map expected
    System.out.println("fromArrow map="+C.fromArrow(new Schema(List.of(new Field("m", FieldType.nullable(new ArrowType.Map(false)), List.of(Field.nullable("k", new ArrowType.Utf8()), Field.nullable("v", new ArrowType.Int(32,true))))))).getParquetSchema());
    // List3Levels with non-list-annotated but repeated primitive child of group
    System.out.println("map() with arrow list child Int64 vs parquet list element INT32 -> class ok");
  }
}
EOF
