package org.apache.parquet.arrow.schema;

import static org.apache.parquet.schema.LogicalTypeAnnotation.mapType;
import static org.apache.parquet.schema.LogicalTypeAnnotation.stringType;
import static org.apache.parquet.schema.PrimitiveType.PrimitiveTypeName.BINARY;
import static org.apache.parquet.schema.PrimitiveType.PrimitiveTypeName.INT32;
import static org.apache.parquet.schema.Type.Repetition.REPEATED;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.apache.parquet.schema.GroupType;
import org.apache.parquet.schema.OriginalType;
import org.apache.parquet.schema.Types;
import org.junit.jupiter.api.Test;

class Map3LevelsTest {

  private static final String INVALID_MAP = "invalid map";

  private static GroupType standardMap() {
    return Types.optionalMap()
        .key(Types.required(INT32).named("key"))
        .value(Types.optional(BINARY).as(stringType()).named("value"))
        .named("attributes");
  }

  @Test
  void exposesMapRepeatedKeyAndValueLevels() {
    GroupType map = standardMap();

    Map3Levels map3Levels = new Map3Levels(map);

    assertThat(map3Levels.getMap()).isSameAs(map);
    assertThat(map3Levels.getRepeated()).isSameAs(map.getFields().get(0));
    assertThat(map3Levels.getRepeated().getName()).isEqualTo("key_value");
    assertThat(map3Levels.getRepeated().isRepetition(REPEATED)).isTrue();
    assertThat(map3Levels.getKey()).isSameAs(map3Levels.getRepeated().getFields().get(0));
    assertThat(map3Levels.getKey().getName()).isEqualTo("key");
    assertThat(map3Levels.getKey().asPrimitiveType().getPrimitiveTypeName()).isEqualTo(INT32);
    assertThat(map3Levels.getValue()).isSameAs(map3Levels.getRepeated().getFields().get(1));
    assertThat(map3Levels.getValue().getName()).isEqualTo("value");
    assertThat(map3Levels.getValue().asPrimitiveType().getPrimitiveTypeName()).isEqualTo(BINARY);
  }

  @Test
  void acceptsMapStructuresDeclaredWithTheDeprecatedMapOriginalType() {
    GroupType map = new GroupType(
        org.apache.parquet.schema.Type.Repetition.OPTIONAL,
        "attributes",
        OriginalType.MAP,
        Types.repeatedGroup()
            .addField(Types.required(INT32).named("key"))
            .addField(Types.optional(INT32).named("value"))
            .named("key_value"));

    Map3Levels map3Levels = new Map3Levels(map);

    assertThat(map3Levels.getRepeated().getName()).isEqualTo("key_value");
    assertThat(map3Levels.getKey().getName()).isEqualTo("key");
    assertThat(map3Levels.getValue().getName()).isEqualTo("value");
  }

  @Test
  void rejectsGroupWithoutMapAnnotation() {
    GroupType group = Types.optionalGroup()
        .addField(Types.repeatedGroup()
            .addField(Types.required(INT32).named("key"))
            .addField(Types.optional(INT32).named("value"))
            .named("key_value"))
        .named("attributes");

    assertThatThrownBy(() -> new Map3Levels(group))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessageStartingWith(INVALID_MAP);
  }

