import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.ArrayList;
import java.util.List;
import org.apache.arrow.vector.types.pojo.ArrowType;
import org.apache.arrow.vector.types.pojo.Field;
import org.apache.arrow.vector.types.pojo.FieldType;
import org.apache.arrow.vector.types.pojo.Schema;
import org.apache.parquet.arrow.schema.SchemaMapping.ListTypeMapping;
import org.apache.parquet.arrow.schema.SchemaMapping.MapTypeMapping;
import org.apache.parquet.arrow.schema.SchemaMapping.PrimitiveTypeMapping;
import org.apache.parquet.arrow.schema.SchemaMapping.RepeatedTypeMapping;
import org.apache.parquet.arrow.schema.SchemaMapping.StructTypeMapping;
import org.apache.parquet.arrow.schema.SchemaMapping.TypeMapping;
import org.apache.parquet.arrow.schema.SchemaMapping.TypeMappingVisitor;
import org.apache.parquet.arrow.schema.SchemaMapping.UnionTypeMapping;
import org.apache.parquet.schema.GroupType;
import org.apache.parquet.schema.MessageType;
import org.apache.parquet.schema.PrimitiveType;
import org.apache.parquet.schema.Type;
import org.apache.parquet.schema.Types;
import org.junit.jupiter.api.Test;

class SchemaMappingTest {

  private static final Field ARROW_INT = Field.nullable("i", new ArrowType.Int(32, true));

  private static PrimitiveType parquetInt() {
    return Types.optional(INT32).as(intType(32, true)).named("i");
  }

  private static GroupType parquetList() {
    return Types.optionalList()
        .element(Types.optional(INT32).as(intType(32, true)).named("element"))
        .named("l");
  }

  private static GroupType parquetMap() {
    return Types.optionalMap()
        .key(Types.required(BINARY).as(stringType()).named("key"))
        .value(Types.optional(INT32).as(intType(32, true)).named("value"))
        .named("m");
  }

  private static Field arrowList() {
    return new Field(
        "l",
        FieldType.nullable(new ArrowType.List()),
        List.of(Field.nullable("element", new ArrowType.Int(32, true))));
  }

  private static Field arrowMap() {
    return new Field(
        "m",
        FieldType.nullable(new ArrowType.Map(false)),
        List.of(
            Field.nullable("key", new ArrowType.Utf8()), Field.nullable("value", new ArrowType.Int(32, true))));
  }

  @Test
  void exposesTheMappedSchemasAndFieldMappings() {
    Schema arrowSchema = new Schema(List.of(ARROW_INT, Field.nullable("s", new ArrowType.Utf8())));
    MessageType parquetSchema = Types.buildMessage()
        .addField(parquetInt())
        .addField(Types.optional(BINARY).as(stringType()).named("s"))
        .named("root");

    SchemaMapping mapping = new SchemaConverter().map(arrowSchema, parquetSchema);

    assertThat(mapping.getArrowSchema()).isSameAs(arrowSchema);
    assertThat(mapping.getParquetSchema()).isSameAs(parquetSchema);
    assertThat(mapping.getChildren()).hasSize(2);
    assertThat(mapping.getChildren().get(0)).isInstanceOf(PrimitiveTypeMapping.class);
    assertThat(mapping.getChildren().get(1)).isInstanceOf(PrimitiveTypeMapping.class);
  }

  @Test
  void exposesTheFieldMappingsGivenAtConstruction() {
    TypeMapping first = new PrimitiveTypeMapping(ARROW_INT, parquetInt());
    TypeMapping second =
        new PrimitiveTypeMapping(Field.nullable("s", new ArrowType.Utf8()), Types.optional(BINARY).named("s"));
    Schema arrowSchema = new Schema(List.of(ARROW_INT));
    MessageType parquetSchema = Types.buildMessage().addField(parquetInt()).named("root");

    SchemaMapping mapping = new SchemaMapping(arrowSchema, parquetSchema, new ArrayList<>(List.of(first, second)));

    assertThat(mapping.getChildren()).containsExactly(first, second);
  }

  @Test
  void fieldMappingsAreUnmodifiable() {
    SchemaMapping mapping = new SchemaConverter().fromArrow(new Schema(List.of(ARROW_INT)));
    TypeMapping extra = new PrimitiveTypeMapping(ARROW_INT, parquetInt());

    assertThatThrownBy(() -> mapping.getChildren().add(extra))
        .isInstanceOf(UnsupportedOperationException.class);
  }

  @Test
  void primitiveMappingHasNoChildren() {
    PrimitiveTypeMapping mapping = new PrimitiveTypeMapping(ARROW_INT, parquetInt());

    assertThat(mapping.getArrowField()).isSameAs(ARROW_INT);
    assertThat(mapping.getParquetType()).isEqualTo(parquetInt());
    assertThat(mapping.getChildren()).isEmpty();
  }

  @Test
  void structMappingExposesItsGroupAndFieldMappings() {
    Field arrowStruct = new Field(
        "s", FieldType.nullable(new ArrowType.Struct()), List.of(ARROW_INT));
    GroupType parquetGroup = Types.optionalGroup().addField(parquetInt()).named("s");
    TypeMapping child = new PrimitiveTypeMapping(ARROW_INT, parquetInt());

    StructTypeMapping mapping = new StructTypeMapping(arrowStruct, parquetGroup, List.of(child));

    assertThat(mapping.getArrowField()).isSameAs(arrowStruct);
    assertThat(mapping.getParquetType()).isSameAs(parquetGroup);
    assertThat(mapping.getChildren()).containsExactly(child);
  }

  @Test
  void unionMappingExposesItsGroupAndFieldMappings() {
    Field arrowUnion = new Field(
        "u",
        FieldType.nullable(new ArrowType.Union(org.apache.arrow.vector.types.UnionMode.Sparse, new int[] {0, 1})),
        List.of(ARROW_INT, Field.nullable("s", new ArrowType.Utf8())));
    GroupType parquetGroup = Types.optionalGroup()
        .addField(parquetInt())
        .addField(Types.optional(BINARY).as(stringType()).named("s"))
        .named("u");
    TypeMapping child = new PrimitiveTypeMapping(ARROW_INT, parquetInt());

    UnionTypeMapping mapping = new UnionTypeMapping(arrowUnion, parquetGroup, List.of(child));

    assertThat(mapping.getArrowField()).isSameAs(arrowUnion);
    assertThat(mapping.getParquetType()).isSameAs(parquetGroup);
    assertThat(mapping.getChildren()).containsExactly(child);
  }

  @Test
  void listMappingAcceptsAChildMappedToTheListElement() {
    GroupType parquetList = parquetList();
    List3Levels list3Levels = new List3Levels(parquetList);
    Field arrowList = arrowList();
    PrimitiveTypeMapping child =
        new PrimitiveTypeMapping(arrowList.getChildren().get(0), list3Levels.getElement().asPrimitiveType());

    ListTypeMapping mapping = new ListTypeMapping(arrowList, list3Levels, child);

    assertThat(mapping.getArrowField()).isSameAs(arrowList);
    assertThat(mapping.getParquetType()).isSameAs(parquetList);
    assertThat(mapping.getList3Levels()).isSameAs(list3Levels);
    assertThat(mapping.getChild()).isSameAs(child);
    assertThat(mapping.getChildren()).containsExactly(child);
