  @Test
  void dispatchesEachMappingKindToItsDedicatedVisitorMethod() {
    GroupType parquetList = parquetList();
    List3Levels list3Levels = new List3Levels(parquetList);
    Field arrowList = arrowList();
    ListTypeMapping listMapping =
        new ListTypeMapping(arrowList, list3Levels, new PrimitiveTypeMapping(arrowList.getChildren().get(0), list3Levels.getElement().asPrimitiveType()));
    GroupType parquetMap = parquetMap();
    Map3Levels map3Levels = new Map3Levels(parquetMap);
    Field arrowMap = arrowMap();
    MapTypeMapping mapMapping = new MapTypeMapping(
        arrowMap,
        map3Levels,
        new PrimitiveTypeMapping(arrowMap.getChildren().get(0), map3Levels.getKey().asPrimitiveType()),
        new PrimitiveTypeMapping(arrowMap.getChildren().get(1), map3Levels.getValue().asPrimitiveType()));
    Type repeatedType = Types.repeated(INT32).named("r");
    Field arrowRepeated = Field.notNullable("r", new ArrowType.List(), List.of(Field.notNullable("r", new ArrowType.Int(32, true))));
    RepeatedTypeMapping repeatedMapping = new RepeatedTypeMapping(
        arrowRepeated, repeatedType, new PrimitiveTypeMapping(arrowRepeated.getChildren().get(0), repeatedType.asPrimitiveType()));
    List<TypeMapping> mappings = List.of(
        new PrimitiveTypeMapping(ARROW_INT, parquetInt()),
        new StructTypeMapping(
            new Field("s", FieldType.nullable(new ArrowType.Struct()), List.of(ARROW_INT)),
            Types.optionalGroup().addField(parquetInt()).named("s"),
            List.of()),
        new UnionTypeMapping(
            new Field(
                "u",
                FieldType.nullable(new ArrowType.Union(org.apache.arrow.vector.types.UnionMode.Sparse, new int[] {0})),
                List.of(ARROW_INT)),
            Types.optionalGroup().addField(parquetInt()).named("u"),
            List.of()),
        listMapping,
        mapMapping,
        repeatedMapping);
    RecordingVisitor visitor = new RecordingVisitor();

    List<String> results = new ArrayList<>();
    for (TypeMapping mapping : mappings) {
      results.add(mapping.accept(visitor));
    }

    assertThat(results).containsExactly("primitive", "struct", "union", "list", "map", "repeated");
    assertThat(visitor.visits).containsExactly("primitive", "struct", "union", "list", "map", "repeated");
  }

  private static final class RecordingVisitor implements TypeMappingVisitor<String> {

    private final List<String> visits = new ArrayList<>();

    @Override
    public String visit(PrimitiveTypeMapping primitiveTypeMapping) {
      visits.add("primitive");
      return "primitive";
    }

    @Override
    public String visit(StructTypeMapping structTypeMapping) {
      visits.add("struct");
      return "struct";
    }

    @Override
    public String visit(UnionTypeMapping unionTypeMapping) {
      visits.add("union");
      return "union";
    }

    @Override
    public String visit(ListTypeMapping listTypeMapping) {
      visits.add("list");
      return "list";
    }

    @Override
    public String visit(MapTypeMapping mapTypeMapping) {
      visits.add("map");
      return "map";
    }

    @Override
    public String visit(RepeatedTypeMapping repeatedTypeMapping) {
      visits.add("repeated");
      return "repeated";
    }
  }
