        Arguments.of(new ArrowType.LargeUtf8(), Types.optional(BINARY).as(stringType()).named(FIELD_NAME)),
        Arguments.of(new ArrowType.Utf8View(), Types.optional(BINARY).as(stringType()).named(FIELD_NAME)),
        Arguments.of(new ArrowType.Binary(), Types.optional(BINARY).named(FIELD_NAME)),
        Arguments.of(new ArrowType.LargeBinary(), Types.optional(BINARY).named(FIELD_NAME)),
