class SchemaConverterFromArrowTest {

  private static final String FIELD_NAME = "f";

  private static TypeMapping onlyChild(SchemaMapping mapping) {
    assertThat(mapping.getChildren()).hasSize(1);
    return mapping.getChildren().get(0);
  }

  private static Schema schemaOf(Field... fields) {
    return new Schema(List.of(fields));
  }

  private static void assertConvertsToPrimitive(ArrowType arrowType, PrimitiveType expectedParquetType) {
    Schema arrowSchema = schemaOf(Field.nullable(FIELD_NAME, arrowType));

    SchemaMapping mapping = new SchemaConverter().fromArrow(arrowSchema);

    TypeMapping fieldMapping = onlyChild(mapping);
    assertThat(fieldMapping).isInstanceOf(PrimitiveTypeMapping.class);
    assertThat(fieldMapping.getArrowField()).isSameAs(arrowSchema.getFields().get(0));
    assertThat(fieldMapping.getParquetType()).isEqualTo(expectedParquetType);
    assertThat(fieldMapping.getChildren()).isEmpty();
    assertThat(mapping.getParquetSchema().getFields()).containsExactly(expectedParquetType);
  }

  static Stream<Arguments> primitiveArrowTypes() {
    return Stream.of(
        Arguments.of(new ArrowType.Bool(), Types.optional(BOOLEAN).named(FIELD_NAME)),
        Arguments.of(new ArrowType.Int(8, true), Types.optional(INT32).as(intType(8, true)).named(FIELD_NAME)),
        Arguments.of(new ArrowType.Int(16, false), Types.optional(INT32).as(intType(16, false)).named(FIELD_NAME)),
        Arguments.of(new ArrowType.Int(32, true), Types.optional(INT32).as(intType(32, true)).named(FIELD_NAME)),
        Arguments.of(new ArrowType.Int(64, true), Types.optional(INT64).as(intType(64, true)).named(FIELD_NAME)),
        Arguments.of(new ArrowType.Int(64, false), Types.optional(INT64).as(intType(64, false)).named(FIELD_NAME)),
        Arguments.of(
            new ArrowType.FloatingPoint(FloatingPointPrecision.HALF), Types.optional(FLOAT).named(FIELD_NAME)),
        Arguments.of(
            new ArrowType.FloatingPoint(FloatingPointPrecision.SINGLE), Types.optional(FLOAT).named(FIELD_NAME)),
        Arguments.of(
            new ArrowType.FloatingPoint(FloatingPointPrecision.DOUBLE), Types.optional(DOUBLE).named(FIELD_NAME)),
        Arguments.of(new ArrowType.Utf8(), Types.optional(BINARY).as(stringType()).named(FIELD_NAME)),
        Arguments.of(new ArrowType.LargeUtf8(), Types.optional(BINARY).as(stringType()).named(FIELD_NAME)),
        Arguments.of(new ArrowType.Utf8View(), Types.optional(BINARY).as(stringType()).named(FIELD_NAME)),
        Arguments.of(new ArrowType.Binary(), Types.optional(BINARY).named(FIELD_NAME)),
        Arguments.of(new ArrowType.LargeBinary(), Types.optional(BINARY).named(FIELD_NAME)),
        Arguments.of(new ArrowType.BinaryView(), Types.optional(BINARY).named(FIELD_NAME)),
        Arguments.of(new ArrowType.FixedSizeBinary(8), Types.optional(BINARY).named(FIELD_NAME)),
        Arguments.of(new ArrowType.Null(), Types.optional(BINARY).named(FIELD_NAME)),
        Arguments.of(
            new ArrowType.Interval(IntervalUnit.DAY_TIME),
            Types.optional(FIXED_LEN_BYTE_ARRAY)
                .length(12)
                .as(IntervalLogicalTypeAnnotation.getInstance())
                .named(FIELD_NAME)),
        Arguments.of(
            new ArrowType.Duration(TimeUnit.MILLISECOND),
            Types.optional(FIXED_LEN_BYTE_ARRAY)
                .length(12)
                .as(IntervalLogicalTypeAnnotation.getInstance())
                .named(FIELD_NAME)));
  }

  @ParameterizedTest
  @MethodSource("primitiveArrowTypes")
  void convertsPrimitiveArrowTypesToOptionalParquetPrimitives(ArrowType arrowType, PrimitiveType expectedParquetType) {
    assertConvertsToPrimitive(arrowType, expectedParquetType);
  }

  static Stream<Arguments> decimalArrowTypes() {
    return Stream.of(
        Arguments.of(9, 2, Types.optional(INT32).as(decimalType(2, 9)).named(FIELD_NAME)),
        Arguments.of(1, 0, Types.optional(INT32).as(decimalType(0, 1)).named(FIELD_NAME)),
        Arguments.of(10, 4, Types.optional(INT64).as(decimalType(4, 10)).named(FIELD_NAME)),
        Arguments.of(18, 4, Types.optional(INT64).as(decimalType(4, 18)).named(FIELD_NAME)),
        Arguments.of(19, 5, Types.optional(BINARY).as(decimalType(5, 19)).named(FIELD_NAME)),
        Arguments.of(38, 10, Types.optional(BINARY).as(decimalType(10, 38)).named(FIELD_NAME)));
  }

  @ParameterizedTest
  @MethodSource("decimalArrowTypes")
  void convertsDecimalsToTheNarrowestParquetType(int precision, int scale, PrimitiveType expectedParquetType) {
    assertConvertsToPrimitive(new ArrowType.Decimal(precision, scale), expectedParquetType);
  }

  static Stream<Arguments> temporalArrowTypes() {
    return Stream.of(
        Arguments.of(new ArrowType.Date(DateUnit.DAY), Types.optional(INT32).as(dateType()).named(FIELD_NAME)),
        Arguments.of(
            new ArrowType.Time(TimeUnit.MILLISECOND, 32),
            Types.optional(INT32).as(timeType(false, MILLIS)).named(FIELD_NAME)),
        Arguments.of(
            new ArrowType.Time(TimeUnit.MICROSECOND, 64),
            Types.optional(INT64).as(timeType(false, MICROS)).named(FIELD_NAME)),
        Arguments.of(
            new ArrowType.Time(TimeUnit.NANOSECOND, 64),
            Types.optional(INT64).as(timeType(false, NANOS)).named(FIELD_NAME)),
        Arguments.of(
            new ArrowType.Timestamp(TimeUnit.MILLISECOND, "UTC"),
            Types.optional(INT64).as(timestampType(true, MILLIS)).named(FIELD_NAME)),
        Arguments.of(
            new ArrowType.Timestamp(TimeUnit.MICROSECOND, null),
            Types.optional(INT64).as(timestampType(false, MICROS)).named(FIELD_NAME)),
        Arguments.of(
            new ArrowType.Timestamp(TimeUnit.MICROSECOND, ""),
            Types.optional(INT64).as(timestampType(false, MICROS)).named(FIELD_NAME)),
        Arguments.of(
            new ArrowType.Timestamp(TimeUnit.NANOSECOND, "UTC"),
            Types.optional(INT64).as(timestampType(true, NANOS)).named(FIELD_NAME)));
  }

  @ParameterizedTest
  @MethodSource("temporalArrowTypes")
  void convertsTemporalArrowTypesToAnnotatedParquetTypes(ArrowType arrowType, PrimitiveType expectedParquetType) {
    assertConvertsToPrimitive(arrowType, expectedParquetType);
  }

  @Test
  void rejectsIntsWithUnsupportedBitWidth() {
    Schema arrowSchema = schemaOf(Field.nullable(FIELD_NAME, new ArrowType.Int(24, true)));

    assertThatThrownBy(() -> new SchemaConverter().fromArrow(arrowSchema))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessageStartingWith("Illegal int type: ");
  }

  @Test
  void rejectsTimesWithAnUnsupportedBitWidthAndUnitCombination() {
    Schema arrowSchema = schemaOf(Field.nullable(FIELD_NAME, new ArrowType.Time(TimeUnit.MICROSECOND, 32)));

    assertThatThrownBy(() -> new SchemaConverter().fromArrow(arrowSchema))
        .isInstanceOf(UnsupportedOperationException.class)
        .hasMessage("Unsupported type Time(MICROSECOND, 32)");
  }

  @Test
  void rejectsMillisTimesOnSixtyFourBits() {
    Schema arrowSchema = schemaOf(Field.nullable(FIELD_NAME, new ArrowType.Time(TimeUnit.MILLISECOND, 64)));

    assertThatThrownBy(() -> new SchemaConverter().fromArrow(arrowSchema))
        .isInstanceOf(UnsupportedOperationException.class)
        .hasMessage("Unsupported type Time(MILLISECOND, 64)");
  }

  @Test
  void rejectsRunEndEncodedFields() {
    Field field = new Field(
        FIELD_NAME,
        FieldType.nullable(ArrowType.RunEndEncoded.INSTANCE),
        List.of(Field.nullable("run_ends", new ArrowType.Int(32, true)), Field.nullable("values", new ArrowType.Utf8())));

    assertThatThrownBy(() -> new SchemaConverter().fromArrow(schemaOf(field)))
        .isInstanceOf(UnsupportedOperationException.class)
        .hasMessage("Unsupported type RunEndEncoded");
  }

  @Test
  void convertsStructFieldsToOptionalGroups() {
    Field structField = new Field(
        "s",
        FieldType.notNullable(new ArrowType.Struct()),
        List.of(Field.notNullable("b", new ArrowType.Bool()), Field.nullable("s", new ArrowType.Utf8())));
    Schema arrowSchema = schemaOf(structField);

    SchemaMapping mapping = new SchemaConverter().fromArrow(arrowSchema);

    TypeMapping fieldMapping = onlyChild(mapping);
    assertThat(fieldMapping).isInstanceOf(StructTypeMapping.class);
    assertThat(fieldMapping.getArrowField()).isSameAs(structField);
    GroupType expectedGroup = Types.optionalGroup()
        .addField(Types.optional(BOOLEAN).named("b"))
        .addField(Types.optional(BINARY).as(stringType()).named("s"))
        .named("s");
    assertThat(fieldMapping.getParquetType()).isEqualTo(expectedGroup);
    assertThat(fieldMapping.getChildren()).hasSize(2);
    assertThat(fieldMapping.getChildren().get(0).getArrowField()).isSameAs(structField.getChildren().get(0));
    assertThat(fieldMapping.getChildren().get(1).getArrowField()).isSameAs(structField.getChildren().get(1));
    assertThat(mapping.getParquetSchema().getFields()).containsExactly(expectedGroup);
  }

  static Stream<Arguments> listArrowTypes() {
    return Stream.of(
        Arguments.of(new ArrowType.List()),
        Arguments.of(new ArrowType.LargeList()),
        Arguments.of(new ArrowType.FixedSizeList(3)),
        Arguments.of(new ArrowType.ListView()),
        Arguments.of(new ArrowType.LargeListView()));
  }

  @ParameterizedTest
  @MethodSource("listArrowTypes")
  void convertsListLikeArrowFieldsToStandardThreeLevelLists(ArrowType listType) {
    Field element = Field.notNullable("item", new ArrowType.Int(32, true));
    Field listField = new Field("l", FieldType.notNullable(listType), List.of(element));
    Schema arrowSchema = schemaOf(listField);

    SchemaMapping mapping = new SchemaConverter().fromArrow(arrowSchema);

    TypeMapping fieldMapping = onlyChild(mapping);
    assertThat(fieldMapping).isInstanceOf(ListTypeMapping.class);
    assertThat(fieldMapping.getArrowField()).isSameAs(listField);
    PrimitiveType expectedElement = Types.optional(INT32).as(intType(32, true)).named("element");
    GroupType expectedList = Types.optionalList().element(expectedElement).named("l");
    assertThat(fieldMapping.getParquetType()).isEqualTo(expectedList);
    ListTypeMapping listMapping = (ListTypeMapping) fieldMapping;
    assertThat(listMapping.getList3Levels().getList()).isSameAs(fieldMapping.getParquetType());
    assertThat(listMapping.getChild()).isSameAs(fieldMapping.getChildren().get(0));
    assertThat(listMapping.getChild().getArrowField()).isSameAs(element);
    assertThat(listMapping.getChild().getParquetType()).isSameAs(listMapping.getList3Levels().getElement());
    assertThat(listMapping.getList3Levels().getElement().isRepetition(OPTIONAL)).isTrue();
  }

  @Test
  void convertsListOfStructsToAThreeLevelListOfGroups() {
    Field element = new Field(
        "item", FieldType.nullable(new ArrowType.Struct()), List.of(Field.nullable("b", new ArrowType.Bool())));
    Field listField = new Field("l", FieldType.nullable(new ArrowType.List()), List.of(element));

    SchemaMapping mapping = new SchemaConverter().fromArrow(schemaOf(listField));

    TypeMapping fieldMapping = onlyChild(mapping);
    assertThat(fieldMapping).isInstanceOf(ListTypeMapping.class);
    TypeMapping elementMapping = fieldMapping.getChildren().get(0);
    assertThat(elementMapping).isInstanceOf(StructTypeMapping.class);
    GroupType expectedGroup = Types.optionalGroup()
        .addField(Types.optional(BOOLEAN).named("b"))
        .named("element");
    assertThat(elementMapping.getParquetType()).isEqualTo(expectedGroup);
    assertThat(fieldMapping.getParquetType())
        .isEqualTo(Types.optionalList().element(expectedGroup).named("l"));
  }

  @Test
  void convertsMapFieldsToStandardThreeLevelMaps() {
    Field key = Field.notNullable("k", new ArrowType.Utf8());
    Field value = Field.notNullable("v", new ArrowType.Int(32, true));
    Field mapField = new Field("m", FieldType.notNullable(new ArrowType.Map(false)), List.of(key, value));

    SchemaMapping mapping = new SchemaConverter().fromArrow(schemaOf(mapField));

    TypeMapping fieldMapping = onlyChild(mapping);
    assertThat(fieldMapping).isInstanceOf(MapTypeMapping.class);
    assertThat(fieldMapping.getArrowField()).isSameAs(mapField);
    PrimitiveType expectedKey = Types.optional(BINARY).as(stringType()).named("key");
    PrimitiveType expectedValue = Types.optional(INT32).as(intType(32, true)).named("value");
    GroupType expectedMap =
        Types.optionalMap().key(expectedKey).value(expectedValue).named("m");
    assertThat(fieldMapping.getParquetType()).isEqualTo(expectedMap);
    MapTypeMapping mapMapping = (MapTypeMapping) fieldMapping;
    assertThat(mapMapping.getKey().getArrowField()).isSameAs(key);
    assertThat(mapMapping.getValue().getArrowField()).isSameAs(value);
    assertThat(mapMapping.getChildren()).containsExactly(mapMapping.getKey(), mapMapping.getValue());
    assertThat(mapMapping.getKey().getParquetType()).isSameAs(mapMapping.getMap3Levels().getKey());
    assertThat(mapMapping.getValue().getParquetType()).isSameAs(mapMapping.getMap3Levels().getValue());
  }

  @Test
  void convertsUnionFieldsToOptionalGroups() {
    Field first = Field.nullable("i", new ArrowType.Int(32, true));
    Field second = Field.nullable("s", new ArrowType.Utf8());
    Field unionField = new Field(
        "u",
        FieldType.nullable(new ArrowType.Union(org.apache.arrow.vector.types.UnionMode.Dense, new int[] {0, 1})),
        List.of(first, second));

    SchemaMapping mapping = new SchemaConverter().fromArrow(schemaOf(unionField));

    TypeMapping fieldMapping = onlyChild(mapping);
    assertThat(fieldMapping).isInstanceOf(UnionTypeMapping.class);
    assertThat(fieldMapping.getParquetType())
        .isEqualTo(Types.optionalGroup()
            .addField(Types.optional(INT32).as(intType(32, true)).named("i"))
            .addField(Types.optional(BINARY).as(stringType()).named("s"))
            .named("u"));
    assertThat(fieldMapping.getChildren()).hasSize(2);
  }

