        Arguments.of(new ArrowType.FixedSizeList(2), 0));
  }

  @ParameterizedTest
  @MethodSource("fieldsWithUnsupportedChildCounts")
  void rejectsListFieldsThatDoNotHaveExactlyOneChild(ArrowType listType, int childCount) {
    List<Field> children = java.util.stream.IntStream.range(0, childCount)
        .mapToObj(i -> Field.nullable("c" + i, new ArrowType.Int(32, true)))
        .toList();
    Field listField = new Field("l", FieldType.nullable(listType), children);

    assertThatThrownBy(() -> new SchemaConverter().fromArrow(schemaOf(listField)))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessageStartingWith("list fields must have exactly one child: ");
  }

  static Stream<Arguments> mapsWithUnsupportedChildCounts() {
    return Stream.of(Arguments.of(0), Arguments.of(1), Arguments.of(3));
  }

  @ParameterizedTest
  @MethodSource("mapsWithUnsupportedChildCounts")
  void rejectsMapFieldsThatDoNotHaveExactlyTwoChildren(int childCount) {
    List<Field> children = java.util.stream.IntStream.range(0, childCount)
        .mapToObj(i -> Field.nullable("c" + i, new ArrowType.Int(32, true)))
        .toList();
    Field mapField = new Field("m", FieldType.nullable(new ArrowType.Map(false)), children);

    assertThatThrownBy(() -> new SchemaConverter().fromArrow(schemaOf(mapField)))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessageStartingWith("Map fields must have exactly two children: ");
