  @Test
  void ignoresArrowNullabilityWhenCreatingParquetTypes() {
    Schema arrowSchema = schemaOf(
        Field.notNullable("i", new ArrowType.Int(32, true)),
        new Field("s", FieldType.notNullable(new ArrowType.Struct()), List.of(Field.notNullable("b", new ArrowType.Bool()))));

    SchemaMapping mapping = new SchemaConverter().fromArrow(arrowSchema);

    assertThat(mapping.getParquetSchema().getFields()).allMatch(type -> type.isRepetition(OPTIONAL));
  }

  @Test
  void namesTheGeneratedMessageRoot() {
    SchemaMapping mapping = new SchemaConverter().fromArrow(schemaOf(Field.nullable("i", new ArrowType.Int(32, true))));

    assertThat(mapping.getParquetSchema().getName()).isEqualTo("root");
  }

  @Test
  void mapsAnEmptyArrowSchemaToAnEmptyMessage() {
    Schema arrowSchema = schemaOf();

    SchemaMapping mapping = new SchemaConverter().fromArrow(arrowSchema);

    assertThat(mapping.getArrowSchema()).isSameAs(arrowSchema);
    assertThat(mapping.getChildren()).isEmpty();
    assertThat(mapping.getParquetSchema().getName()).isEqualTo("root");
    assertThat(mapping.getParquetSchema().getFields()).isEmpty();
  }

  @Test
  void keepsTheMappingAlignedWithTheGeneratedParquetFields() {
    Field struct = new Field(
        "s", FieldType.nullable(new ArrowType.Struct()), List.of(Field.nullable("b", new ArrowType.Bool())));
    Field list = new Field(
        "l", FieldType.nullable(new ArrowType.List()), List.of(Field.nullable("i", new ArrowType.Int(32, true))));
    Field map = new Field(
        "m",
        FieldType.nullable(new ArrowType.Map(false)),
        List.of(Field.nullable("k", new ArrowType.Utf8()), Field.nullable("v", new ArrowType.Int(32, true))));
    Field primitive = Field.nullable("d", new ArrowType.FloatingPoint(FloatingPointPrecision.DOUBLE));

    SchemaMapping mapping = new SchemaConverter().fromArrow(schemaOf(struct, list, map, primitive));

    assertThat(mapping.getChildren()).hasSize(4);
    assertThat(mapping.getParquetSchema().getFields()).hasSameSizeAs(mapping.getChildren());
    for (int i = 0; i < mapping.getChildren().size(); i++) {
      assertThat(mapping.getParquetSchema().getFields().get(i))
          .isSameAs(mapping.getChildren().get(i).getParquetType());
    }
    assertThat(mapping.getParquetSchema().getFields())
        .extracting(type -> type.getName())
        .containsExactly("s", "l", "m", "d");
  }
}
