class SchemaConverterFromParquetTest {

  private static final String FIELD_NAME = "f";

  private static MessageType messageOf(org.apache.parquet.schema.Type... fields) {
    return Types.buildMessage().addFields(fields).named("root");
  }

  private static TypeMapping onlyChild(SchemaMapping mapping) {
    assertThat(mapping.getChildren()).hasSize(1);
    return mapping.getChildren().get(0);
  }

  private static void assertConvertsToArrow(PrimitiveType parquetType, ArrowType expectedArrowType) {
    SchemaMapping mapping = new SchemaConverter().fromParquet(messageOf(parquetType));

    TypeMapping fieldMapping = onlyChild(mapping);
    assertThat(fieldMapping).isInstanceOf(PrimitiveTypeMapping.class);
    assertThat(fieldMapping.getParquetType()).isSameAs(parquetType);
    Field expectedField = parquetType.isRepetition(OPTIONAL)
        ? Field.nullable(parquetType.getName(), expectedArrowType)
        : Field.notNullable(parquetType.getName(), expectedArrowType);
    assertThat(fieldMapping.getArrowField()).isEqualTo(expectedField);
    assertThat(mapping.getArrowSchema().getFields()).containsExactly(expectedField);
  }

  static Stream<Arguments> primitiveParquetTypes() {
    return Stream.of(
        Arguments.of(Types.optional(BOOLEAN).named(FIELD_NAME), new ArrowType.Bool()),
        Arguments.of(Types.required(BOOLEAN).named(FIELD_NAME), new ArrowType.Bool()),
        Arguments.of(Types.optional(INT32).named(FIELD_NAME), new ArrowType.Int(32, true)),
