        .hasMessageStartingWith("invalid list type: ");
  }

  @Test
  void failsToMapMapAnnotatedGroupsWithMismatchedStructure() {
    MessageType parquetSchema = messageOf(Types.optionalGroup()
        .as(mapType())
        .addField(Types.repeatedGroup().addField(Types.optional(INT32).named("key")).named("key_value"))
        .named("map"));

    assertThatThrownBy(() -> new SchemaConverter().fromParquet(parquetSchema))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessageStartingWith("invalid map key: ");
  }

  @Test
  void mapsAnEmptyMessageToAnEmptyArrowSchema() {
    MessageType parquetSchema = Types.buildMessage().named("root");

    SchemaMapping mapping = new SchemaConverter().fromParquet(parquetSchema);

    assertThat(mapping.getParquetSchema()).isSameAs(parquetSchema);
    assertThat(mapping.getChildren()).isEmpty();
    Schema arrowSchema = mapping.getArrowSchema();
    assertThat(arrowSchema.getFields()).isEmpty();
  }

  @Test
  void buildsTheArrowSchemaFromTheMappedFields() {
    MessageType parquetSchema = messageOf(
        Types.optional(BOOLEAN).named("b"),
        Types.optionalGroup().addField(Types.optional(INT32).named("i")).named("s"),
        Types.optionalList().element(Types.optional(INT32).named("element")).named("l"),
        Types.optionalMap()
            .key(Types.required(BINARY).as(stringType()).named("key"))
            .value(Types.optional(INT32).named("value"))
            .named("m"));

    SchemaMapping mapping = new SchemaConverter().fromParquet(parquetSchema);

    assertThat(mapping.getChildren()).hasSize(4);
    assertThat(mapping.getArrowSchema().getFields()).hasSameSizeAs(mapping.getChildren());
    for (int i = 0; i < mapping.getChildren().size(); i++) {
