          .isSameAs(mapping.getChildren().get(i).getArrowField());
    }
    assertThat(mapping.getArrowSchema().getFields())
        .extracting(Field::getName)
        .containsExactly("b", "s", "l", "m");
  }

  @Test
  void keepsListAndMapDefinitionsAvailableThroughTheMappings() {
    MessageType parquetSchema = messageOf(
        Types.optionalList()
            .element(Types.optional(INT32).named("element"))
            .named("l"),
        Types.optionalMap()
            .key(Types.required(BINARY).as(stringType()).named("key"))
            .value(Types.optional(INT32).named("value"))
            .named("m"));

    SchemaMapping mapping = new SchemaConverter().fromParquet(parquetSchema);

    List<TypeMapping> children = mapping.getChildren();
    assertThat(((ListTypeMapping) children.get(0)).getList3Levels().getElement().getName())
        .isEqualTo("element");
    assertThat(((MapTypeMapping) children.get(1)).getMap3Levels().getKey().getName())
        .isEqualTo("key");
    assertThat(((MapTypeMapping) children.get(1)).getMap3Levels().getValue().getName())
        .isEqualTo("value");
  }
