  @Test
  void mapsPrimitiveFieldsAndKeepsTheProvidedSchemas() {
    Field intField = Field.nullable("i", new ArrowType.Int(32, true));
    Field stringField = Field.nullable("s", new ArrowType.Utf8());
    Schema arrowSchema = schemaOf(intField, stringField);
    PrimitiveType parquetInt = Types.optional(INT32).as(intType(32, true)).named("i");
    PrimitiveType parquetString = Types.optional(BINARY).as(stringType()).named("s");
    MessageType parquetSchema = messageOf(parquetInt, parquetString);

