    assertThat(mapping.getChildren()).hasSize(2);
    assertThat(mapping.getChildren().get(0)).isInstanceOf(PrimitiveTypeMapping.class);
    assertThat(mapping.getChildren().get(0).getArrowField()).isSameAs(intField);
    assertThat(mapping.getChildren().get(0).getParquetType()).isSameAs(parquetInt);
    assertThat(mapping.getChildren().get(1).getParquetType()).isSameAs(parquetString);
