  @Test
  void mapsPrimitiveFieldsWithoutValidatingTypeCompatibility() {
    Field intField = Field.nullable("i", new ArrowType.Int(32, true));
    PrimitiveType parquetBinary = Types.optional(BINARY).named("i");

    SchemaMapping mapping = new SchemaConverter().map(schemaOf(intField), messageOf(parquetBinary));

    TypeMapping fieldMapping = onlyChild(mapping);
    assertThat(fieldMapping).isInstanceOf(PrimitiveTypeMapping.class);
    assertThat(fieldMapping.getParquetType()).isSameAs(parquetBinary);
