        Field.nullable("a", new ArrowType.Bool()), Field.nullable("b", new ArrowType.Bool()));
    MessageType parquetSchema = messageOf(Types.optional(BOOLEAN).named("a"));

    assertThatThrownBy(() -> new SchemaConverter().map(arrowSchema, parquetSchema))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessageStartingWith("Can not map schemas as sizes differ: ");
