    MessageType parquetSchema =
        messageOf(Types.optionalGroup().addField(Types.optional(INT32).named("i")).named("l"));

    assertThatThrownBy(() -> new SchemaConverter().map(schemaOf(listField), parquetSchema))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessageStartingWith("invalid list type: ");
  }

  @Test
  void mapsMapFieldsToStandardThreeLevelMaps() {
    Field key = Field.nullable("key", new ArrowType.Utf8());
    Field value = Field.nullable("value", new ArrowType.Int(32, true));
    Field mapField = arrowMap(key, value);
    PrimitiveType parquetKey = Types.required(BINARY).as(stringType()).named("key");
    PrimitiveType parquetValue = Types.optional(INT32).as(intType(32, true)).named("value");
    Type parquetMap = Types.optionalMap().key(parquetKey).value(parquetValue).named("m");

    SchemaMapping mapping = new SchemaConverter().map(schemaOf(mapField), messageOf(parquetMap));

    TypeMapping fieldMapping = onlyChild(mapping);
    assertThat(fieldMapping).isInstanceOf(MapTypeMapping.class);
    assertThat(fieldMapping.getParquetType()).isSameAs(parquetMap);
    MapTypeMapping mapMapping = (MapTypeMapping) fieldMapping;
    assertThat(mapMapping.getChildren()).containsExactly(mapMapping.getKey(), mapMapping.getValue());
    assertThat(mapMapping.getKey().getArrowField()).isSameAs(key);
    assertThat(mapMapping.getKey().getParquetType()).isSameAs(parquetKey);
    assertThat(mapMapping.getValue().getArrowField()).isSameAs(value);
    assertThat(mapMapping.getValue().getParquetType()).isSameAs(parquetValue);
  }

  @Test
  void rejectsMapFieldsWithoutExactlyTwoChildren() {
