        "m", FieldType.nullable(new ArrowType.Map(false)), List.of(Field.nullable("only", new ArrowType.Utf8())));
    Type parquetMap = Types.optionalMap()
        .key(Types.required(BINARY).as(stringType()).named("key"))
        .value(Types.optional(INT32).named("value"))
        .named("m");

