    Field intField = Field.nullable("i", new ArrowType.Int(32, true));
    Field stringField = Field.nullable("s", new ArrowType.Utf8());
    Schema arrowSchema = schemaOf(intField, stringField);
    PrimitiveType parquetInt = Types.optional(INT32).as(intType(32, true)).named("i");
    PrimitiveType parquetString = Types.optional(BINARY).as(stringType()).named("s");
    MessageType parquetSchema = messageOf(parquetInt, parquetString);

    SchemaMapping mapping = new SchemaConverter().map(arrowSchema, parquetSchema);

    assertThat(mapping.getArrowSchema()).isSameAs(arrowSchema);
    assertThat(mapping.getParquetSchema()).isSameAs(parquetSchema);
    assertThat(mapping.getChildren()).hasSize(2);
    assertThat(mapping.getChildren().get(0)).isInstanceOf(PrimitiveTypeMapping.class);
    assertThat(mapping.getChildren().get(0).getArrowField()).isSameAs(intField);
    assertThat(mapping.getChildren().get(0).getParquetType()).isSameAs(parquetInt);
    assertThat(mapping.getChildren().get(1).getParquetType()).isSameAs(parquetString);
  }

