        Arguments.of(new ArrowType.Utf8()),
        Arguments.of(new ArrowType.Binary()),
        Arguments.of(new ArrowType.Decimal(9, 2)),
        Arguments.of(new ArrowType.Decimal(18, 4)),
        Arguments.of(new ArrowType.Decimal(19, 5)),
        Arguments.of(new ArrowType.Date(DateUnit.DAY)),
        Arguments.of(new ArrowType.Time(TimeUnit.MILLISECOND, 32)),
        Arguments.of(new ArrowType.Time(TimeUnit.MICROSECOND, 64)),
        Arguments.of(new ArrowType.Time(TimeUnit.NANOSECOND, 64)),
        Arguments.of(new ArrowType.Timestamp(TimeUnit.MILLISECOND, "UTC")),
        Arguments.of(new ArrowType.Timestamp(TimeUnit.MICROSECOND, null)),
        Arguments.of(new ArrowType.Timestamp(TimeUnit.NANOSECOND, "UTC")));
  }

  @ParameterizedTest
  @MethodSource("roundTrippableArrowTypes")
  void roundTripsArrowPrimitiveTypesThroughAParquetSchema(ArrowType arrowType) {
    Schema arrowSchema = schemaOf(Field.nullable("f", arrowType));
    SchemaConverter converter = new SchemaConverter();

    MessageType parquetSchema = converter.fromArrow(arrowSchema).getParquetSchema();
    Schema roundTripped = converter.fromParquet(parquetSchema).getArrowSchema();

    assertThat(roundTripped.getFields()).containsExactly(Field.nullable("f", arrowType));
  }

  @Test
  void roundTripsNestedArrowTypesThroughAParquetSchema() {
    Field struct = new Field(
        "s", FieldType.nullable(new ArrowType.Struct()), List.of(Field.nullable("b", new ArrowType.Bool())));
    Field list = arrowList(Field.nullable("item", new ArrowType.Int(32, true)));
    Field listField = new Field("l", FieldType.nullable(new ArrowType.List()), list.getChildren());
    Field map = arrowMap(
        Field.nullable("k", new ArrowType.Utf8()), Field.nullable("v", new ArrowType.Int(32, true)));
    Field mapField = new Field("m", FieldType.nullable(new ArrowType.Map(false)), map.getChildren());
    Schema arrowSchema = schemaOf(struct, listField, mapField);
    SchemaConverter converter = new SchemaConverter();

    Schema roundTripped = converter
        .fromParquet(converter.fromArrow(arrowSchema).getParquetSchema())
        .getArrowSchema();

    assertThat(roundTripped.getFields())
        .extracting(Field::getName, Field::getType)
        .containsExactly(
            tuple("s", struct.getType()), tuple("l", listField.getType()), tuple("m", mapField.getType()));
  }

  @Test
  void mapsTheGeneratedParquetSchemaBackOntoTheSourceArrowSchema() {
    Field struct = new Field(
        "s", FieldType.nullable(new ArrowType.Struct()), List.of(Field.nullable("b", new ArrowType.Bool())));
    Field listField = arrowList(Field.nullable("item", new ArrowType.Int(32, true)));
    Field mapField = arrowMap(
        Field.nullable("k", new ArrowType.Utf8()), Field.nullable("v", new ArrowType.Int(32, true)));
    Schema arrowSchema = schemaOf(struct, listField, mapField);
    SchemaConverter converter = new SchemaConverter();
    MessageType generatedParsetSchema = converter.fromArrow(arrowSchema).getParquetSchema();

    SchemaMapping remapped = converter.map(arrowSchema, generatedParsetSchema);

    assertThat(remapped.getParquetSchema()).isSameAs(generatedParsetSchema);
    assertThat(remapped.getChildren()).hasSize(3);
    assertThat(remapped.getChildren().get(0)).isInstanceOf(StructTypeMapping.class);
    assertThat(remapped.getChildren().get(1)).isInstanceOf(ListTypeMapping.class);
    assertThat(remapped.getChildren().get(2)).isInstanceOf(MapTypeMapping.class);
  }
