    Field list = arrowList(Field.nullable("item", new ArrowType.Int(32, true)));
    Field listField = new Field("l", FieldType.nullable(new ArrowType.List()), list.getChildren());
    Field map = arrowMap(
        Field.nullable("k", new ArrowType.Utf8()), Field.nullable("v", new ArrowType.Int(32, true)));
    Field mapField = new Field("m", FieldType.nullable(new ArrowType.Map(false)), map.getChildren());
