    Field struct = new Field(
        "s", FieldType.nullable(new ArrowType.Struct()), List.of(Field.nullable("b", new ArrowType.Bool())));
    Field listField = arrowList(Field.nullable("item", new ArrowType.Int(32, true)));
    Field mapField = arrowMap(
        Field.nullable("k", new ArrowType.Utf8()), Field.nullable("v", new ArrowType.Int(32, true)));
    Schema arrowSchema = schemaOf(struct, listField, mapField);
    SchemaConverter converter = new SchemaConverter();
    MessageType generatedParsetSchema = converter.fromArrow(arrowSchema).getParquetSchema();

