    assertThat(remapped.getParquetSchema()).isSameAs(generatedParsetSchema);
    assertThat(remapped.getChildren()).hasSize(3);
    assertThat(remapped.getChildren().get(0)).isInstanceOf(StructTypeMapping.class);
    assertThat(remapped.getChildren().get(1)).isInstanceOf(ListTypeMapping.class);
