import org.apache.avro.Schema;
import org.apache.avro.file.*;
import org.apache.avro.generic.*;
import org.apache.parquet.cli.util.*;
import java.io.*;
import java.util.*;
import com.fasterxml.jackson.databind.*;

public class Probe3 {
  static String tryIt(String label, Callable c) {
    try { return label + " = " + c.call(); }
    catch (Throwable t) { return label + " EX " + t.getClass().getName() + ": " + t.getMessage(); }
  }
  interface Callable { Object call() throws Exception; }

  public static void main(String[] a) throws Exception {
    System.out.println(tryIt("fromAvro invalid", () -> Schemas.fromAvro(new ByteArrayInputStream("garbage".getBytes()))));
    System.out.println(tryIt("fromJSON invalid", () -> Schemas.fromJSON("x", new ByteArrayInputStream("{bad".getBytes()))));
    System.out.println(tryIt("fromJSON empty", () -> Schemas.fromJSON("x", new ByteArrayInputStream("".getBytes()))));
    System.out.println(tryIt("fromJSON nested", () -> Schemas.fromJSON("root", new ByteArrayInputStream("{\"a\":{\"b\":1},\"arr\":[1,2],\"m\":{\"x\":1}}".getBytes())).toString(true)));
    System.out.println(tryIt("fromJSON multi", () -> Schemas.fromJSON("root", new ByteArrayInputStream("{\"a\":1,\"b\":2}\n{\"a\":2,\"c\":3}".getBytes())).toString(true)));
    System.out.println(tryIt("avroCodec name", () -> Codecs.avroCodec("gzip").getName()));
    System.out.println(tryIt("avroCodec deflate name", () -> Codecs.avroCodec("deflate").getName()));
    ObjectMapper m = RawUtils.createObjectMapper();
    System.out.println(tryIt("mapped date", () -> m.writeValueAsString(java.time.LocalDate.of(2020,1,2))));
    Map<String,Object> map = new LinkedHashMap<>();
    map.put("b", "2"); map.put("a", "1");
    System.out.println(tryIt("ordered map", () -> m.writeValueAsString(map)));
    System.out.println(tryIt("empty bean", () -> m.writeValueAsString(new Object())));
    System.out.println(tryIt("pretty null", () -> RawUtils.prettifyJson("null")));
    System.out.println(tryIt("pretty scalar", () -> RawUtils.prettifyJson("\"hi\"")));
  }
}
