    try { return l + " = " + c.call(); } catch (Throwable e) { return l + " EX " + e.getClass().getName() + ": " + e.getMessage(); }
  }
  static final String SCHEMA_JSON = "{\"type\":\"record\",\"name\":\"R\",\"fields\":["
    + "{\"name\":\"id\",\"type\":\"int\"},"
    + "{\"name\":\"sub\",\"type\":{\"type\":\"record\",\"name\":\"Sub\",\"fields\":[{\"name\":\"x\",\"type\":\"int\"},{\"name\":\"y\",\"type\":[\"null\",\"string\"]}]}},"
    + "{\"name\":\"arr\",\"type\":{\"type\":\"array\",\"items\":\"int\"}},"
    + "{\"name\":\"m\",\"type\":{\"type\":\"map\",\"values\":\"int\"}},"
    + "{\"name\":\"u\",\"type\":[\"null\",{\"type\":\"record\",\"name\":\"U\",\"fields\":[{\"name\":\"z\",\"type\":\"int\"}]}]}"
    + "]}";
  public static void main(String[] a) throws Exception {
    Schema schema = new Schema.Parser().parse(SCHEMA_JSON);
    GenericRecord sub = new GenericData.Record(schema.getField("sub").schema());
    sub.put("x", 42); sub.put("y", null);
    GenericRecord rec = new GenericData.Record(schema);
    rec.put("id", 1); rec.put("sub", sub);
    rec.put("arr", Arrays.asList(10, 20, 30));
    Map<String,Object> m = new HashMap<>(); m.put(new Utf8("k"), 7); rec.put("m", m);
    rec.put("u", null);

    System.out.println(t("select id", () -> Expressions.select(schema, rec, "id")));
    System.out.println(t("select sub.x", () -> Expressions.select(schema, rec, "sub.x")));
    System.out.println(t("select sub.y null", () -> Expressions.select(schema, rec, "sub.y")));
    System.out.println(t("select arr[1]", () -> Expressions.select(schema, rec, "arr[1]")));
    System.out.println(t("select m.k utf8", () -> Expressions.select(schema, rec, "m.k")));
    System.out.println(t("select u null", () -> Expressions.select(schema, rec, "u")));
    System.out.println(t("select missing", () -> Expressions.select(schema, rec, "nope")));
    System.out.println(t("select str idx", () -> Expressions.select(schema, rec, "arr[x]")));
    System.out.println(t("select primitive child", () -> Expressions.select(schema, rec, "id.x")));
    System.out.println(t("select arr.field", () -> Expressions.select(schema, rec, "arr.x")));
    System.out.println(t("select double dot", () -> Expressions.select(schema, rec, "a..b")));
    System.out.println(t("select unclosed", () -> Expressions.select(schema, rec, "arr[0")));
    System.out.println(t("select after deref", () -> Expressions.select(schema, rec, "arr[0]x")));
    System.out.println(t("select empty path", () -> Expressions.select(schema, rec, "")));
    System.out.println(t("select idx oob", () -> Expressions.select(schema, rec, "arr[9]")));

    // json placeholder
    Schema jsonSchema = Schema.createRecord("json", null, null, false);
    jsonSchema.setFields(Collections.singletonList(new Schema.Field("value", Schema.create(Schema.Type.INT), null, null)));
    System.out.println(t("select json placeholder", () -> Expressions.select(jsonSchema, 5, "")));
    System.out.println(t("select json placeholder child", () -> Expressions.select(jsonSchema, 5, "x")));

