    // roundtrip with deflate codec
    Schema s = new Schema.Parser().parse("{\"type\":\"record\",\"name\":\"r\",\"fields\":[{\"name\":\"v\",\"type\":\"long\"}]}");
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    DataFileWriter<GenericRecord> w = new DataFileWriter<>(new GenericDatumWriter<GenericRecord>(s));
    w.setCodec(Codecs.avroCodec("gzip"));
    w.create(s, out);
    GenericRecord rec = new GenericData.Record(s); rec.put("v", 99L);
    w.append(rec); w.close();
    byte[] bytes = out.toByteArray();
    System.out.println("magic: " + new String(bytes, 0, 3));
    DataFileStream<GenericRecord> ds = new DataFileStream<>(new ByteArrayInputStream(bytes), new GenericDatumReader<GenericRecord>());
    System.out.println("codec from file: " + ds.getMetaString("avro.codec"));
    System.out.println("read value: " + ds.next().get("v"));
    ds.close();
    System.out.println("fromAvro ok: " + Schemas.fromAvro(new ByteArrayInputStream(bytes)).toString());
  }
}
