import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.IOException;
import org.junit.jupiter.api.Test;

/** Tests for the small exception types exposed by the CLI utilities. */
public class ExceptionTypesTest {

  @Test
  public void recordExceptionKeepsMessage() {
    RecordException ex = new RecordException("bad record");
    assertThat(ex).isInstanceOf(RuntimeException.class);
    assertThat(ex.getMessage()).isEqualTo("bad record");
    assertThat(ex.getCause()).isNull();
  }

  @Test
  public void recordExceptionKeepsCause() {
    IllegalStateException cause = new IllegalStateException("root");
    RecordException ex = new RecordException("bad record", cause);
    assertThat(ex.getMessage()).isEqualTo("bad record");
    assertThat(ex.getCause()).isSameAs(cause);
  }

  @Test
  public void checkDoesNotThrowWhenValid() {
    assertThatCode(() -> RecordException.check(true, "should not happen %s", "ignored"))
        .doesNotThrowAnyException();
  }

  @Test
  public void checkThrowsWithPlainMessage() {
    assertThatThrownBy(() -> RecordException.check(false, "value is invalid"))
        .isInstanceOf(RecordException.class)
        .hasMessage("value is invalid");
  }

  @Test
  public void checkFormatsArguments() {
    assertThatThrownBy(() -> RecordException.check(false, "%s of %s is not allowed", "field a", 3))
        .isInstanceOf(RecordException.class)
        .hasMessage("field a of 3 is not allowed");
  }

  @Test
  public void checkUsesStringValueOfForArguments() {
    assertThatThrownBy(() -> RecordException.check(false, "found %s", (Object) null))
        .isInstanceOf(RecordException.class)
        .hasMessage("found null");
  }

  @Test
  public void runtimeIOExceptionWrapsIOException() {
    IOException cause = new IOException("disk on fire");
    RuntimeIOException ex = new RuntimeIOException("cannot read", cause);
    assertThat(ex).isInstanceOf(RuntimeException.class);
    assertThat(ex.getMessage()).isEqualTo("cannot read");
    assertThat(ex.getCause()).isSameAs(cause);
    assertThat(ex.getCause()).isInstanceOf(IOException.class);
  }
}
