package org.apache.parquet.cli.util;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

/** Tests for {@link Formats#detectFormat(InputStream)}. */
public class FormatsTest {

  private static InputStream stream(String content) {
    return new ByteArrayInputStream(content.getBytes(StandardCharsets.UTF_8));
  }

  @ParameterizedTest
  @CsvSource({
    "PAR1, PARQUET",
    "PAR, PARQUET",
    "PAR1with more bytes, PARQUET",
    "Obj1, AVRO",
    "Obj, AVRO",
    "SEQ, SEQUENCE",
    "SEQsome data, SEQUENCE",
    "hello world, TEXT",
    "par1, TEXT",
    "json lines, TEXT"
  })
  public void detectsFormatFromLeadingBytes(String content, Formats.Format expected) throws IOException {
    assertThat(Formats.detectFormat(stream(content))).isEqualTo(expected);
  }

  @Test
  public void emptyStreamIsText() throws IOException {
    assertThat(Formats.detectFormat(new ByteArrayInputStream(new byte[0]))).isEqualTo(Formats.Format.TEXT);
  }

  @Test
  public void shortStreamIsText() throws IOException {
    assertThat(Formats.detectFormat(stream("PA"))).isEqualTo(Formats.Format.TEXT);
  }

  @Test
  public void consumesExactlyThreeBytes() throws IOException {
    InputStream in = stream("PAR1rest");
    assertThat(Formats.detectFormat(in)).isEqualTo(Formats.Format.PARQUET);
    assertThat(in.read()).isEqualTo('1');
    assertThat(new String(in.readAllBytes(), StandardCharsets.UTF_8)).isEqualTo("rest");
  }

  @Test
  public void doesNotCloseTheStream() throws IOException {
    TrackingInputStream in = new TrackingInputStream("Obj\u0001payload".getBytes(StandardCharsets.UTF_8));
    assertThat(Formats.detectFormat(in)).isEqualTo(Formats.Format.AVRO);
    assertThat(in.closed).isFalse();
  }

  private static final class TrackingInputStream extends ByteArrayInputStream {
    private boolean closed = false;

    TrackingInputStream(byte[] buf) {
      super(buf);
    }

    @Override
    public void close() throws IOException {
      closed = true;
      super.close();
    }
  }
}
EOF
