package org.apache.parquet.cli.util;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import org.apache.avro.AvroRuntimeException;
import org.apache.avro.Schema;
import org.apache.avro.file.CodecFactory;
import org.apache.avro.file.DataFileStream;
import org.apache.avro.file.DataFileWriter;
import org.apache.avro.generic.GenericData;
import org.apache.avro.generic.GenericDatumReader;
import org.apache.avro.generic.GenericDatumWriter;
import org.apache.avro.generic.GenericRecord;
import org.apache.parquet.hadoop.metadata.CompressionCodecName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

/** Tests for the Parquet/Avro codec name conversions in {@link Codecs}. */
public class CodecsTest {

  @ParameterizedTest
  @CsvSource({
    "uncompressed, UNCOMPRESSED",
    "UNCOMPRESSED, UNCOMPRESSED",
    "snappy, SNAPPY",
    "Snappy, SNAPPY",
    "gzip, GZIP",
    "GZip, GZIP",
    "lzo, LZO",
    "lz4_raw, LZ4_RAW",
    "zstd, ZSTD"
  })
  public void parquetCodecIsCaseInsensitive(String name, CompressionCodecName expected) {
    assertThat(Codecs.parquetCodec(name)).isEqualTo(expected);
  }

  @Test
  public void parquetCodecRejectsAvroOnlyCodec() {
    assertThatThrownBy(() -> Codecs.parquetCodec("deflate"))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Unknown compression codec: deflate");
  }

  @Test
  public void parquetCodecRejectsUnknownCodec() {
    assertThatThrownBy(() -> Codecs.parquetCodec("bogus"))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Unknown compression codec: bogus");
  }

  @Test
  public void avroCodecTranslatesGzipToDeflate() {
    assertThat(Codecs.avroCodec("gzip")).isEqualTo(Codecs.avroCodec("deflate"));
    assertThat(Codecs.avroCodec("GZIP")).isEqualTo(Codecs.avroCodec("deflate"));
  }

  @Test
  public void avroCodecTranslatesSnappy() {
    assertThat(Codecs.avroCodec("SNAPPY")).isEqualTo(Codecs.avroCodec("snappy"));
  }

  @Test
  public void avroCodecTranslatesUncompressedToNull() {
    assertThat(Codecs.avroCodec("uncompressed")).isEqualTo(Codecs.avroCodec("null"));
    assertThat(Codecs.avroCodec("UNCOMPRESSED")).isEqualTo(Codecs.avroCodec("null"));
  }

  @Test
  public void avroCodecTranslatesZstdToZstandard() {
    assertThat(Codecs.avroCodec("zstd")).isEqualTo(Codecs.avroCodec("zstandard"));
  }

  @Test
  public void avroCodecPassesAvroNativeNamesThrough() {
    assertThat(Codecs.avroCodec("deflate")).isEqualTo(Codecs.avroCodec("deflate"));
    assertThat(Codecs.avroCodec("bzip2")).isNotNull();
    assertThat(Codecs.avroCodec("null")).isNotNull();
  }

  @Test
  public void avroCodecRejectsCodecAvroDoesNotSupport() {
    assertThatThrownBy(() -> Codecs.avroCodec("lzo"))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Codec incompatible with Avro: lzo")
        .hasCauseInstanceOf(AvroRuntimeException.class);
  }

  @Test
  public void avroCodecRejectsUnknownCodec() {
    assertThatThrownBy(() -> Codecs.avroCodec("notacodec"))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Codec incompatible with Avro: notacodec");
  }

  @Test
  public void gzipCodecCanBeUsedToWriteAndReadAvroData() throws IOException {
    Schema schema = new Schema.Parser()
        .parse("{\"type\":\"record\",\"name\":\"r\",\"fields\":[{\"name\":\"v\",\"type\":\"long\"}]}");

    ByteArrayOutputStream out = new ByteArrayOutputStream();
    CodecFactory codec = Codecs.avroCodec("gzip");
    try (DataFileWriter<GenericRecord> writer = new DataFileWriter<>(new GenericDatumWriter<GenericRecord>(schema))) {
      writer.setCodec(codec);
      writer.create(schema, out);
      GenericRecord record = new GenericData.Record(schema);
      record.put("v", 99L);
      writer.append(record);
    }

    try (DataFileStream<GenericRecord> reader =
        new DataFileStream<>(new ByteArrayInputStream(out.toByteArray()), new GenericDatumReader<GenericRecord>())) {
      // gzip is stored as the Avro "deflate" codec
      assertThat(reader.getMetaString("avro.codec")).isEqualTo("deflate");
      assertThat(reader.next().get("v")).isEqualTo(99L);
    }
  }
}
