package org.apache.parquet.cli.util;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.InputStream;
import java.net.URL;
import java.net.URLClassLoader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Collections;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** Tests for {@link GetClassLoader}. */
public class GetClassLoaderTest {

  @TempDir
  Path tempDir;

  @Test
  public void createsClassLoaderWithGivenUrls() throws Exception {
    URL url = tempDir.toUri().toURL();

    ClassLoader loader = new GetClassLoader(Collections.singletonList(url)).run();

    assertThat(loader).isInstanceOf(URLClassLoader.class);
    assertThat(((URLClassLoader) loader).getURLs()).containsExactly(url);
  }

  @Test
  public void keepsUrlOrder() throws Exception {
    Path second = Files.createDirectory(tempDir.resolve("second"));
    URL first = tempDir.toUri().toURL();
    URL secondUrl = second.toUri().toURL();

    ClassLoader loader = new GetClassLoader(List.of(secondUrl, first)).run();

    assertThat(((URLClassLoader) loader).getURLs()).containsExactly(secondUrl, first);
  }

  @Test
  public void emptyUrlListProducesLoaderWithoutUrls() {
    ClassLoader loader = new GetClassLoader(Collections.emptyList()).run();

    assertThat(loader).isInstanceOf(URLClassLoader.class);
    assertThat(((URLClassLoader) loader).getURLs()).isEmpty();
  }

