package org.apache.parquet.cli.util;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.FileNotFoundException;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import org.apache.avro.Schema;
import org.apache.avro.file.DataFileWriter;
import org.apache.avro.generic.GenericDatumWriter;
import org.apache.avro.generic.GenericRecord;
import org.apache.hadoop.conf.Configuration;
import org.apache.hadoop.fs.FSDataOutputStream;
import org.apache.hadoop.fs.FileSystem;
import org.apache.hadoop.fs.Path;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/** Tests for {@link SeekableFSDataInputStream}. */
public class SeekableFSDataInputStreamTest {

  @TempDir
  java.nio.file.Path tempDir;

  private static final byte[] CONTENT = "0123456789abcdef".getBytes(StandardCharsets.UTF_8);

  private FileSystem fs;

  @BeforeEach
  public void setUp() throws IOException {
    Configuration conf = new Configuration();
    fs = FileSystem.getLocal(conf);
  }

  private Path writeFile(String name, byte[] content) throws IOException {
    Path path = new Path(new java.io.File(tempDir.toFile(), name).toURI());
    try (FSDataOutputStream out = fs.create(path, true)) {
      out.write(content);
    }
    return path;
  }

  @Test
  public void reportsLengthOfUnderlyingFile() throws IOException {
    Path path = writeFile("length.bin", CONTENT);

    try (SeekableFSDataInputStream in = new SeekableFSDataInputStream(fs, path)) {
      assertThat(in.length()).isEqualTo(CONTENT.length);
    }
  }

  @Test
  public void readsBytesAndTracksPosition() throws IOException {
    Path path = writeFile("read.bin", CONTENT);

    try (SeekableFSDataInputStream in = new SeekableFSDataInputStream(fs, path)) {
      assertThat(in.tell()).isZero();
      assertThat(in.read()).isEqualTo('0');
      assertThat(in.tell()).isEqualTo(1);
      assertThat(in.read()).isEqualTo('1');
      assertThat(in.tell()).isEqualTo(2);
    }
  }

  @Test
  public void seeksToAbsolutePositions() throws IOException {
    Path path = writeFile("seek.bin", CONTENT);

    try (SeekableFSDataInputStream in = new SeekableFSDataInputStream(fs, path)) {
      in.seek(4);
      assertThat(in.tell()).isEqualTo(4);
      assertThat(in.read()).isEqualTo('4');

      in.seek(0);
      assertThat(in.tell()).isZero();
      assertThat(in.read()).isEqualTo('0');

      in.seek(CONTENT.length);
      assertThat(in.read()).isEqualTo(-1);
    }
  }

  @Test
  public void readsIntoBuffer() throws IOException {
    Path path = writeFile("buffer.bin", CONTENT);

    try (SeekableFSDataInputStream in = new SeekableFSDataInputStream(fs, path)) {
      byte[] buffer = new byte[4];
      assertThat(in.read(buffer)).isEqualTo(4);
      assertThat(new String(buffer, StandardCharsets.UTF_8)).isEqualTo("0123");
      assertThat(in.tell()).isEqualTo(4);
    }
  }

  @Test
  public void readsIntoBufferOffsetAndLength() throws IOException {
    Path path = writeFile("offset.bin", CONTENT);

    try (SeekableFSDataInputStream in = new SeekableFSDataInputStream(fs, path)) {
      in.seek(2);
      byte[] buffer = new byte[8];
      int read = in.read(buffer, 2, 4);
      assertThat(read).isEqualTo(4);
      assertThat(buffer[2]).isEqualTo((byte) '2');
      assertThat(buffer[5]).isEqualTo((byte) '5');
      assertThat(buffer[0]).isZero();
      assertThat(in.tell()).isEqualTo(6);
    }
  }

  @Test
  public void closeClosesUnderlyingStream() throws IOException {
    Path path = writeFile("close.bin", CONTENT);
    SeekableFSDataInputStream in = new SeekableFSDataInputStream(fs, path);
    in.close();

    assertThatThrownBy(in::read).isInstanceOf(IOException.class);
  }

  @Test
  public void constructorFailsForMissingFile() {
    Path missing = new Path(new java.io.File(tempDir.toFile(), "missing.bin").toURI());

    assertThatThrownBy(() -> new SeekableFSDataInputStream(fs, missing))
        .isInstanceOf(FileNotFoundException.class);
  }

  @Test
  public void worksAsAnAvroInputStream() throws Exception {
    Schema schema = new Schema.Parser()
        .parse("{\"type\":\"record\",\"name\":\"r\",\"fields\":[{\"name\":\"v\",\"type\":\"int\"}]}");
    java.io.ByteArrayOutputStream bytes = new java.io.ByteArrayOutputStream();
    try (DataFileWriter<GenericRecord> writer = new DataFileWriter<>(new GenericDatumWriter<GenericRecord>(schema))) {
      writer.create(schema, bytes);
      GenericRecord record = new org.apache.avro.generic.GenericData.Record(schema);
      record.put("v", 7);
      writer.append(record);
    }
    Path path = writeFile("data.avro", bytes.toByteArray());

    try (SeekableFSDataInputStream in = new SeekableFSDataInputStream(fs, path)) {
      assertThat(Schemas.fromAvro(in)).isEqualTo(schema);
    }
  }
}
