    file.write("PAR1".getBytes(StandardCharsets.US_ASCII));
    file.write(metadata);
    file.write(metadata.length & 0xFF);
    file.write((metadata.length >>> 8) & 0xFF);
    file.write((metadata.length >>> 16) & 0xFF);
    file.write((metadata.length >>> 24) & 0xFF);
    file.write("PAR1".getBytes(StandardCharsets.US_ASCII));
    return file.toByteArray();
  }

  /** A minimal in-memory {@link SeekableInputStream} used to feed parquet bytes to RawUtils. */
  private static final class InMemorySeekableInputStream extends SeekableInputStream {
    private final byte[] data;
    private int pos = 0;

    InMemorySeekableInputStream(byte[] data) {
      this.data = data;
    }

    @Override
    public long getPos() {
      return pos;
    }

    @Override
    public void seek(long newPos) {
      this.pos = (int) newPos;
    }

    @Override
    public long length() {
      return data.length;
    }

    @Override
    public int read() {
      return pos < data.length ? data[pos++] & 0xFF : -1;
    }

    @Override
    public int read(byte[] b, int off, int len) {
      if (pos >= data.length) {
        return -1;
      }
      int count = Math.min(len, data.length - pos);
      System.arraycopy(data, pos, b, off, count);
      pos += count;
      return count;
    }

    @Override
    public void readFully(byte[] bytes) throws IOException {
      readFully(bytes, 0, bytes.length);
    }

    @Override
    public void readFully(byte[] bytes, int start, int len) throws IOException {
      if (data.length - pos < len) {
        throw new EOFException("not enough bytes");
      }
      System.arraycopy(data, pos, bytes, start, len);
      pos += len;
    }

    @Override
    public int read(ByteBuffer buf) {
      int count = Math.min(buf.remaining(), data.length - pos);
      if (count <= 0) {
        return -1;
      }
      buf.put(data, pos, count);
      pos += count;
      return count;
    }

    @Override
    public void readFully(ByteBuffer buf) throws IOException {
      int count = buf.remaining();
      if (data.length - pos < count) {
        throw new EOFException("not enough bytes");
      }
      buf.put(data, pos, count);
      pos += count;
    }

    @Override
    public List<ByteBuffer> readVectored(List<org.apache.parquet.io.SeekableInputStream.Range> ranges,
        java.util.function.IntFunction<ByteBuffer> allocate) {
      throw new UnsupportedOperationException();
    }
  }

  /** A bean without any properties, used to check FAIL_ON_EMPTY_BEANS handling. */
  public static class EmptyBean {
    // intentionally empty
  }
}
