/** Tests for {@link Schemas}. */
public class SchemasTest {

  @TempDir
  java.nio.file.Path tempDir;

  private static final String RECORD_AVSC = "{\"type\":\"record\",\"name\":\"User\",\"namespace\":\"ns\","
      + "\"fields\":[{\"name\":\"id\",\"type\":\"int\"},{\"name\":\"name\",\"type\":\"string\"}]}";

  private static InputStream utf8(String content) {
    return new ByteArrayInputStream(content.getBytes(StandardCharsets.UTF_8));
  }

  // ---------------------------------------------------------------- fromAvsc

  @Test
  public void fromAvscParsesSchema() throws IOException {
    Schema schema = Schemas.fromAvsc(utf8(RECORD_AVSC));

    assertThat(schema.getType()).isEqualTo(Schema.Type.RECORD);
    assertThat(schema.getName()).isEqualTo("User");
    assertThat(schema.getNamespace()).isEqualTo("ns");
    assertThat(schema.getField("id").schema().getType()).isEqualTo(Schema.Type.INT);
    assertThat(schema.getField("name").schema().getType()).isEqualTo(Schema.Type.STRING);
  }

  @Test
  public void fromAvscRejectsInvalidSchema() {
    assertThatThrownBy(() -> Schemas.fromAvsc(utf8("{\"type\":\"record\",\"name\":\"Bad\"}")))
        .isInstanceOf(SchemaParseException.class);
  }

  // ---------------------------------------------------------------- fromAvro

  @Test
  public void fromAvroReadsSchemaFromDataFile() throws IOException {
    Schema schema = new Schema.Parser().parse(RECORD_AVSC);
    byte[] avroFile = avroFile(schema, "id", 3, "name", "alice");

    assertThat(Schemas.fromAvro(new ByteArrayInputStream(avroFile))).isEqualTo(schema);
  }

  @Test
  public void fromAvroClosesTheInputStream() throws IOException {
    Schema schema = new Schema.Parser().parse(RECORD_AVSC);
    byte[] avroFile = avroFile(schema, "id", 3, "name", "alice");
    TrackingInputStream in = new TrackingInputStream(avroFile);

    Schemas.fromAvro(in);

    assertThat(in.closed).isTrue();
  }

  @Test
  public void fromAvroRejectsNonAvroData() {
    assertThatThrownBy(() -> Schemas.fromAvro(utf8("this is not an avro file")))
        .isInstanceOf(InvalidAvroMagicException.class)
        .hasMessage("Not an Avro data file.");
  }

  // ------------------------------------------------------------- fromParquet

  @Test
  public void fromParquetUsesAvroSchemaMetadata() throws IOException {
    Schema schema = new Schema.Parser().parse(RECORD_AVSC);
    java.io.File file = tempDir.resolve("avro.parquet").toFile();
    org.apache.hadoop.fs.Path path = new org.apache.hadoop.fs.Path(file.toURI());
    Configuration conf = new Configuration();
    GenericRecord record = new GenericData.Record(schema);
    record.put("id", 1);
    record.put("name", "bob");
    try (ParquetWriter<GenericRecord> writer = AvroParquetWriter.<GenericRecord>builder(path)
        .withConf(conf)
        .withSchema(schema)
        .build()) {
      writer.write(record);
    }

    assertThat(Schemas.fromParquet(conf, file.toURI())).isEqualTo(schema);
  }

  @Test
  public void fromParquetConvertsSchemaWhenAvroMetadataIsMissing() throws IOException {
    MessageType messageType = Types.buildMessage()
        .required(PrimitiveTypeName.INT32)
        .named("id")
        .optional(PrimitiveTypeName.BINARY)
        .as(org.apache.parquet.schema.LogicalTypeAnnotation.stringType())
        .named("name")
        .named("plain_record");
