    assertThat(schema.getType()).isEqualTo(Schema.Type.RECORD);
    assertThat(schema.getName()).isEqualTo("plain_record");
    assertThat(schema.getField("id").schema().getType()).isEqualTo(Schema.Type.INT);
    assertThat(schema.getField("name").schema().getTypes())
        .extracting(Schema::getType)
        .containsExactly(Schema.Type.NULL, Schema.Type.STRING);
  }

  @Test
  public void fromParquetUsesLegacyAvroSchemaKey() throws IOException {
    MessageType messageType =
        Types.buildMessage().required(PrimitiveTypeName.INT64).named("legacy").named("legacy_record");
    java.io.File file = tempDir.resolve("legacy.parquet").toFile();
    Configuration conf = new Configuration();
    String legacySchema = "{\"type\":\"record\",\"name\":\"Legacy\",\"fields\":[{\"name\":\"v\",\"type\":\"int\"}]}";
    writePlainParquet(file, messageType, conf, Map.of("avro.schema", legacySchema));

    Schema schema = Schemas.fromParquet(conf, file.toURI());

    assertThat(schema.getName()).isEqualTo("Legacy");
    assertThat(schema.getField("v").schema().getType()).isEqualTo(Schema.Type.INT);
