    assertThat(Schemas.nullOk(Schema.create(Schema.Type.STRING))).isFalse();
    assertThat(Schemas.nullOk(Schema.createArray(Schema.create(Schema.Type.NULL)))).isFalse();
  }

  @Test
  public void nullOkIsTrueForUnionContainingNull() {
