  @Test
  public void mergeOfEmptyIterableIsNull() {
    assertThat(Schemas.merge(Collections.<Schema>emptyList())).isNull();
    assertThat(Schemas.mergeOrUnion(Collections.<Schema>emptyList())).isNull();
  }

  @Test
  public void mergeOfSingleSchemaReturnsIt() {
    Schema schema = Schema.create(Schema.Type.INT);
    assertThat(Schemas.merge(Collections.singletonList(schema))).isSameAs(schema);
    assertThat(Schemas.mergeOrUnion(Collections.singletonList(schema))).isSameAs(schema);
  }

  @Test
  public void mergePromotesIntToLong() {
    Schema intSchema = Schema.create(Schema.Type.INT);
    Schema longSchema = Schema.create(Schema.Type.LONG);

    assertThat(Schemas.merge(intSchema, longSchema)).isEqualTo(longSchema);
    assertThat(Schemas.merge(longSchema, intSchema)).isEqualTo(longSchema);
  }

  @Test
  public void mergePromotesFloatToDouble() {
    Schema floatSchema = Schema.create(Schema.Type.FLOAT);
    Schema doubleSchema = Schema.create(Schema.Type.DOUBLE);

    assertThat(Schemas.merge(floatSchema, doubleSchema)).isEqualTo(doubleSchema);
    assertThat(Schemas.merge(doubleSchema, floatSchema)).isEqualTo(doubleSchema);
  }

  @Test
  public void mergeDoesNotPromoteIntToDouble() {
    assertThatThrownBy(() -> Schemas.merge(Schema.create(Schema.Type.INT), Schema.create(Schema.Type.DOUBLE)))
        .isInstanceOf(IllegalStateException.class)
        .hasMessageStartingWith("Cannot merge");
  }

  @Test
  public void mergeCombinesRecordsWithSameName() {
    Schema merged = Schemas.merge(record("R", "a"), record("R", "a"));

    assertThat(merged.getType()).isEqualTo(Schema.Type.RECORD);
    assertThat(merged.getName()).isEqualTo("R");
    assertThat(merged.getFields()).extracting(Schema.Field::name).containsExactly("a");
  }

  @Test
  public void mergeRejectsRecordsWithDifferentNames() {
    assertThatThrownBy(() -> Schemas.merge(record("R", "a"), record("S", "a")))
        .isInstanceOf(IllegalStateException.class)
        .hasMessageStartingWith("Cannot merge");
  }

  @Test
  public void mergeRejectsDifferentTypes() {
    Schema record = record("R", "a");
    Schema map = Schema.createMap(Schema.create(Schema.Type.INT));

    assertThatThrownBy(() -> Schemas.merge(record, map)).isInstanceOf(IllegalStateException.class);
  }

  @Test
  public void mergeCombinesEnumSymbols() {
    Schema left = Schema.createEnum("E", null, null, Arrays.asList("A", "B"));
    Schema right = Schema.createEnum("E", null, null, Arrays.asList("B", "C"));

    Schema merged = Schemas.merge(left, right);

    assertThat(merged.getType()).isEqualTo(Schema.Type.ENUM);
    assertThat(merged.getEnumSymbols()).containsExactly("A", "B", "C");
  }

  @Test
  public void mergeRejectsEnumsWithDifferentNames() {
    Schema left = Schema.createEnum("E", null, null, Arrays.asList("A"));
    Schema right = Schema.createEnum("F", null, null, Arrays.asList("A"));

    assertThatThrownBy(() -> Schemas.merge(left, right)).isInstanceOf(IllegalStateException.class);
  }

  @Test
  public void mergeMapsMergesValueTypes() {
    Schema merged = Schemas.merge(
        Schema.createMap(Schema.create(Schema.Type.INT)), Schema.createMap(Schema.create(Schema.Type.LONG)));

    assertThat(merged.getType()).isEqualTo(Schema.Type.MAP);
    assertThat(merged.getValueType().getType()).isEqualTo(Schema.Type.LONG);
  }

  @Test
  public void mergeArraysUnionsElementTypes() {
    Schema merged = Schemas.merge(
        Schema.createArray(Schema.create(Schema.Type.INT)), Schema.createArray(Schema.create(Schema.Type.STRING)));

    assertThat(merged.getType()).isEqualTo(Schema.Type.ARRAY);
    assertThat(merged.getElementType().getType()).isEqualTo(Schema.Type.UNION);
    assertThat(merged.getElementType().getTypes()).extracting(Schema::getType).containsExactly(Schema.Type.INT,
        Schema.Type.STRING);
  }

  @Test
  public void mergeUnionsMergesMatchingTypes() {
    Schema left = Schema.createUnion(Arrays.asList(Schema.create(Schema.Type.NULL), Schema.create(Schema.Type.INT)));
    Schema right = Schema.createUnion(Arrays.asList(Schema.create(Schema.Type.NULL), Schema.create(Schema.Type.LONG)));

    Schema merged = Schemas.merge(left, right);

    assertThat(merged.getType()).isEqualTo(Schema.Type.UNION);
    assertThat(merged.getTypes()).extracting(Schema::getType).containsExactly(Schema.Type.NULL, Schema.Type.LONG);
  }

  @Test
  public void mergeOrUnionUnionsIncompatibleTypes() {
    Schema merged = Schemas.mergeOrUnion(
        Arrays.asList(Schema.create(Schema.Type.INT), Schema.create(Schema.Type.STRING)));

    assertThat(merged.getType()).isEqualTo(Schema.Type.UNION);
    assertThat(merged.getTypes()).extracting(Schema::getType).containsExactly(Schema.Type.INT, Schema.Type.STRING);
  }

  @Test
  public void mergeOrUnionPrefersMergeWhenPossible() {
    Schema merged = Schemas.mergeOrUnion(
        Arrays.asList(Schema.create(Schema.Type.INT), Schema.create(Schema.Type.LONG)));

    assertThat(merged).isEqualTo(Schema.create(Schema.Type.LONG));
  }

  @Test
  public void mergeIsAssociativeOverSchemaSets() {
    List<Schema> schemas = Arrays.asList(
        record("R", "a"), record("R", "a"), Schema.createEnum("E", null, null, Arrays.asList("A")));

    Schema firstTwo = Schemas.merge(schemas.subList(0, 2));
    assertThat(Schemas.merge(Arrays.asList(firstTwo, schemas.get(2))))
        .isEqualTo(Schemas.merge(Arrays.asList(schemas.get(0), Schemas.merge(schemas.subList(1, 3)))));
  }

  // ------------------------------------------------------------------- copy

  @Test
  public void copyCreatesEquivalentField() {
    Schema.Field original = new Schema.Field(
        "a", Schema.create(Schema.Type.INT), "some doc", Schema.create(Schema.Type.NULL).getObjectProps() == null
            ? 0
            : 0);

    Schema.Field copy = Schemas.copy(original);

    assertThat(copy).isNotSameAs(original);
    assertThat(copy.name()).isEqualTo("a");
    assertThat(copy.doc()).isEqualTo("some doc");
    assertThat(copy.schema()).isEqualTo(original.schema());
    assertThat(copy.defaultVal()).isEqualTo(original.defaultVal());
  }

  private static Schema record(String name, String... fieldNames) {
    Schema schema = Schema.createRecord(name, null, null, false);
    Schema.Field[] fields = new Schema.Field[fieldNames.length];
    for (int i = 0; i < fieldNames.length; i++) {
      fields[i] = new Schema.Field(fieldNames[i], Schema.create(Schema.Type.INT), null, null);
    }
    schema.setFields(Arrays.asList(fields));
    return schema;
  }

  private static byte[] avroFile(Schema schema, Object... fieldValues) throws IOException {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    try (DataFileWriter<GenericRecord> writer = new DataFileWriter<>(new GenericDatumWriter<GenericRecord>(schema))) {
      writer.create(schema, out);
      GenericRecord record = new GenericData.Record(schema);
      for (int i = 0; i < fieldValues.length; i += 2) {
        record.put((String) fieldValues[i], fieldValues[i + 1]);
      }
      writer.append(record);
    }
    return out.toByteArray();
  }

  private static void writePlainParquet(
      java.io.File file, MessageType schema, Configuration conf, Map<String, String> extraMetadata)
      throws IOException {
    org.apache.hadoop.fs.Path path = new org.apache.hadoop.fs.Path(file.toURI());
    try (ParquetWriter<Group> writer = ExampleParquetWriter.builder(path)
        .withConf(conf)
        .withType(schema)
        .withExtraMetaData(extraMetadata)
        .build()) {
      Group group = new SimpleGroupFactory(schema).newGroup();
      if (schema.containsField("id")) {
        group.append("id", 1);
      }
      if (schema.containsField("legacy")) {
        group.append("legacy", 5L);
      }
      writer.write(group);
    }
  }

  private static final class TrackingInputStream extends FilterInputStream {
    private boolean closed = false;

    TrackingInputStream(byte[] data) {
      super(new ByteArrayInputStream(data));
    }

    @Override
    public void close() throws IOException {
      closed = true;
      super.close();
    }
  }
}
