package org.apache.parquet.column.values.bloomfilter;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.Test;

class XxHashTest {

  private final XxHash hash = new XxHash();

  @Test
  void hashesKnownXxh64VectorsWithSeedZero() {
    assertEquals(-1205034819632174695L, hash.hashBytes(new byte[0]));
    assertEquals(-3292477735350538661L, hash.hashBytes(new byte[] {'a'}));
    assertEquals(4952883123889572249L, hash.hashBytes("abc".getBytes(StandardCharsets.UTF_8)));
    assertEquals(-8306817102742376829L, hash.hashBytes("123456789".getBytes(StandardCharsets.UTF_8)));
  }

  @Test
  void hashesRemainingBytesOfByteBufferWithoutChangingItsPosition() {
    byte[] bytes = new byte[] {0, 1, 2, 3, 4, 5, 6, 7};
    ByteBuffer buffer = ByteBuffer.wrap(bytes);
    buffer.position(2);
    buffer.limit(6);

    long bufferHash = hash.hashByteBuffer(buffer);

    assertEquals(hash.hashBytes(new byte[] {2, 3, 4, 5}), bufferHash);
    assertEquals(2, buffer.position());
    assertEquals(6, buffer.limit());
  }

  @Test
  void hashesHeapAndDirectByteBuffersConsistently() {
    byte[] bytes = "direct-buffer".getBytes(StandardCharsets.UTF_8);
    ByteBuffer heapBuffer = ByteBuffer.wrap(bytes);
    ByteBuffer directBuffer = ByteBuffer.allocateDirect(bytes.length);
    directBuffer.put(bytes);
    directBuffer.flip();

    assertEquals(hash.hashBytes(bytes), hash.hashByteBuffer(heapBuffer));
    assertEquals(hash.hashBytes(bytes), hash.hashByteBuffer(directBuffer));
  }

  @Test
  void isDeterministicAndSensitiveToInput() {
    byte[] first = "a".getBytes(StandardCharsets.UTF_8);
    byte[] second = "b".getBytes(StandardCharsets.UTF_8);

    assertEquals(hash.hashBytes(first), hash.hashBytes(first.clone()));
    assertNotEquals(hash.hashBytes(first), hash.hashBytes(second));
  }

  @Test
  void emptyByteBufferHashesLikeEmptyArray() {
    assertEquals(hash.hashBytes(new byte[0]), hash.hashByteBuffer(ByteBuffer.allocate(0)));
  }
}
