package org.apache.parquet.column.values.bloomfilter;

import static org.apache.parquet.column.values.bloomfilter.BlockSplitBloomFilter.DEFAULT_FPP;
import static org.apache.parquet.column.values.bloomfilter.BlockSplitBloomFilter.HEADER_SIZE;
import static org.apache.parquet.column.values.bloomfilter.BlockSplitBloomFilter.LOWER_BOUND_BYTES;
import static org.apache.parquet.column.values.bloomfilter.BlockSplitBloomFilter.UPPER_BOUND_BYTES;
import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import org.apache.parquet.io.api.Binary;
import org.junit.jupiter.api.Test;

class BlockSplitBloomFilterTest {

  @Test
  void exposesParquetBloomFilterConstants() {
    assertEquals(32, LOWER_BOUND_BYTES);
    assertEquals(128 * 1024 * 1024, UPPER_BOUND_BYTES);
    assertEquals(16, HEADER_SIZE);
    assertEquals(0.01, DEFAULT_FPP);
  }

  @Test
  void roundsRequestedSizesToAValidPowerOfTwo() {
    int[][] expectedSizes = {
      {-100, 32},
      {-1, 32},
      {0, 32},
      {1, 32},
      {31, 32},
      {32, 32},
      {33, 64},
      {63, 64},
      {64, 64},
      {65, 128},
      {100, 128},
      {128, 128}
    };

    for (int[] entry : expectedSizes) {
      assertEquals(
          entry[1],
          new BlockSplitBloomFilter(entry[0]).getBitsetSize(),
          "requested bytes: " + entry[0]);
    }
  }

  @Test
  void appliesCustomMinimumAndMaximumBounds() {
    assertEquals(64, new BlockSplitBloomFilter(16, 64, 64, BloomFilter.HashStrategy.XXH64).getBitsetSize());
    assertEquals(128, new BlockSplitBloomFilter(96, 64, 128, BloomFilter.HashStrategy.XXH64).getBitsetSize());
    assertEquals(256, new BlockSplitBloomFilter(1000, 32, 256, BloomFilter.HashStrategy.XXH64).getBitsetSize());
  }

  @Test
  void rejectsMinimumSizeGreaterThanMaximumSize() {
    IllegalArgumentException error = assertThrows(
        IllegalArgumentException.class,
        () -> new BlockSplitBloomFilter(64, 128, 64, BloomFilter.HashStrategy.XXH64));

    assertTrue(error.getMessage().contains("minimum bytes"));
  }

  @Test
  void insertedHashesAreAlwaysFound() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(1024);

    for (int i = 0; i < 1000; i++) {
      long value = ((long) i * 0x9E3779B97F4A7C15L) ^ (i << 17);
      filter.insertHash(value);
    }

    for (int i = 0; i < 1000; i++) {
      long value = ((long) i * 0x9E3779B97F4A7C15L) ^ (i << 17);
      assertTrue(filter.findHash(value), "inserted hash " + i + " must be present");
    }
  }

  @Test
  void emptyBitsetNeverReportsMembership() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(32);
    assertFalse(filter.findHash(0L));
    assertFalse(filter.findHash(Long.MIN_VALUE));
    assertFalse(filter.findHash(Long.MAX_VALUE));
  }

  @Test
  void serializesOnlyTheBitsetAndCanBeReconstructed() throws IOException {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(256);
    long[] hashes = {11L, 22L, 33L, 44L, 55L};
    for (long hash : hashes) {
      filter.insertHash(hash);
    }

    ByteArrayOutputStream output = new ByteArrayOutputStream();
    filter.writeTo(output);
    byte[] serialized = output.toByteArray();

    assertEquals(filter.getBitsetSize(), serialized.length);
    BlockSplitBloomFilter reconstructed = new BlockSplitBloomFilter(serialized);
    assertEquals(filter, reconstructed);
    for (long hash : hashes) {
      assertTrue(reconstructed.findHash(hash));
    }
  }

  @Test
  void reconstructsFromProvidedBitsetAndRejectsNull() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(new byte[LOWER_BOUND_BYTES]);
    assertEquals(LOWER_BOUND_BYTES, filter.getBitsetSize());
    assertFalse(filter.findHash(1234L));

    assertThrows(RuntimeException.class, () -> new BlockSplitBloomFilter((byte[]) null));
  }

  @Test
  void equalityIncludesBitsetSizeAndContentsButNotObjectIdentity() {
    BlockSplitBloomFilter first = new BlockSplitBloomFilter(64);
    BlockSplitBloomFilter sameSize = new BlockSplitBloomFilter(64);
    BlockSplitBloomFilter otherSize = new BlockSplitBloomFilter(128);

    assertEquals(first, first);
    assertEquals(first, sameSize);
    assertEquals(first.hashCode(), first.hashCode());
    assertNotEquals(first, otherSize);
    assertNotEquals(first, "not a bloom filter");
    assertNotEquals(first, null);

    first.insertHash(42L);
    assertNotEquals(first, sameSize);
  }

  @Test
  void hashesPrimitiveValuesUsingTheirLittleEndianPlainEncoding() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(64);
    XxHash xxHash = new XxHash();

    int intValue = 0x01020304;
    long longValue = 0x0102030405060708L;
    float floatValue = 1.25f;
    double doubleValue = -2.5d;

    assertEquals(xxHash.hashBytes(littleEndian(intValue)), filter.hash(intValue));
    assertEquals(xxHash.hashBytes(littleEndian(longValue)), filter.hash(longValue));
    assertEquals(xxHash.hashBytes(littleEndian(floatValue)), filter.hash(floatValue));
    assertEquals(xxHash.hashBytes(littleEndian(doubleValue)), filter.hash(doubleValue));

    assertEquals(filter.hash(intValue), filter.hash((Object) intValue));
    assertEquals(filter.hash(longValue), filter.hash((Object) longValue));
    assertEquals(filter.hash(floatValue), filter.hash((Object) floatValue));
    assertEquals(filter.hash(doubleValue), filter.hash((Object) doubleValue));
  }

  @Test
  void hashesBinaryByItsBytesIncludingThroughTheObjectOverload() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(64);
    XxHash xxHash = new XxHash();
    byte[] bytes = "parquet".getBytes(StandardCharsets.UTF_8);
    Binary binary = Binary.fromConstantByteArray(bytes);

    assertEquals(xxHash.hashBytes(bytes), filter.hash(binary));
    assertEquals(xxHash.hashBytes(bytes), filter.hash((Object) binary));
  }

  @Test
  void rejectsUnsupportedObjectHashes() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(64);

    RuntimeException error = assertThrows(RuntimeException.class, () -> filter.hash((Object) "text"));

    assertEquals("Parquet Bloom filter: Not supported type", error.getMessage());
  }

  @Test
  void reportsAlgorithmHashStrategyAndCompression() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(64);

    assertSame(BloomFilter.HashStrategy.XXH64, filter.getHashStrategy());
    assertSame(BloomFilter.Algorithm.BLOCK, filter.getAlgorithm());
    assertSame(BloomFilter.Compression.UNCOMPRESSED, filter.getCompression());
    assertEquals("xxhash", filter.getHashStrategy().toString());
    assertEquals("block", filter.getAlgorithm().toString());
    assertEquals("uncompressed", filter.getCompression().toString());
  }

  @Test
  void canMergeOnlyCompatibleNonNulBloomFilters() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(64);

    assertTrue(filter.canMergeFrom(new BlockSplitBloomFilter(64)));
    assertFalse(filter.canMergeFrom(new BlockSplitBloomFilter(128)));
    assertFalse(filter.canMergeFrom(null));
  }

  @Test
  void mergeCombinesBitsetsWithBitwiseOr() throws IOException {
    byte[] leftBits = new byte[64];
    byte[] rightBits = new byte[64];
    leftBits[0] = 0x0f;
    leftBits[17] = 0x40;
    leftBits[63] = 0x01;
    rightBits[0] = 0x30;
    rightBits[17] = 0x80;
    rightBits[31] = 0x02;

    BlockSplitBloomFilter left = new BlockSplitBloomFilter(leftBits.clone());
    BlockSplitBloomFilter right = new BlockSplitBloomFilter(rightBits.clone());
    left.merge(right);

    byte[] expected = leftBits.clone();
    for (int i = 0; i < expected.length; i++) {
      expected[i] |= rightBits[i];
    }
    ByteArrayOutputStream output = new ByteArrayOutputStream();
    left.writeTo(output);
    assertArrayEquals(expected, output.toByteArray());
  }

  @Test
  void mergeRejectsIncompatibleOrNullFilters() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(64);

    assertThrows(IllegalArgumentException.class, () -> filter.merge(null));
    IllegalArgumentException mismatch = assertThrows(
        IllegalArgumentException.class, () -> filter.merge(new BlockSplitBloomFilter(128)));
    assertTrue(mismatch.getMessage().contains("same size"));
  }

  @Test
  void optimalNumOfBitsValidatesFalsePositiveProbability() {
    assertThrows(IllegalArgumentException.class, () -> BlockSplitBloomFilter.optimalNumOfBits(100, 0.0));
    assertThrows(IllegalArgumentException.class, () -> BlockSplitBloomFilter.optimalNumOfBits(100, 1.0));
    assertThrows(IllegalArgumentException.class, () -> BlockSplitBloomFilter.optimalNumOfBits(100, -0.1));
    assertThrows(IllegalArgumentException.class, () -> BlockSplitBloomFilter.optimalNumOfBits(100, 1.1));
  }

  @Test
  void optimalNumOfBitsGrowsWithCardinalityAndHandlesOverflow() {
    int small = BlockSplitBloomFilter.optimalNumOfBits(100, DEFAULT_FPP);
    int large = BlockSplitBloomFilter.optimalNumOfBits(10_000, DEFAULT_FPP);

    assertTrue(small >= LOWER_BOUND_BYTES * 8);
    assertTrue(large > small);
    assertEquals(UPPER_BOUND_BYTES * 8, BlockSplitBloomFilter.optimalNumOfBits(Long.MAX_VALUE, DEFAULT_FPP));
  }

  private static byte[] littleEndian(int value) {
    return ByteBuffer.allocate(Integer.BYTES)
        .order(ByteOrder.LITTLE_ENDIAN)
        .putInt(value)
        .array();
