  void roundsRequestedSizesToAValidPowerOfTwo() {
    int[][] expectedSizes = {
      {-100, 32},
      {-1, 32},
      {0, 32},
      {1, 32},
      {31, 32},
      {32, 32},
      {33, 64},
      {63, 64},
      {64, 64},
      {65, 128},
      {100, 128},
      {128, 128}
    };

    for (int[] entry : expectedSizes) {
      assertEquals(
          entry[1],
          new BlockSplitBloomFilter(entry[0]).getBitsetSize(),
          "requested bytes: " + entry[0]);
    }
  }

  @Test
  void appliesCustomMinimumAndMaximumBounds() {
    assertEquals(64, new BlockSplitBloomFilter(16, 64, 64, BloomFilter.HashStrategy.XXH64).getBitsetSize());
    assertEquals(128, new BlockSplitBloomFilter(96, 64, 128, BloomFilter.HashStrategy.XXH64).getBitsetSize());
    assertEquals(256, new BlockSplitBloomFilter(1000, 32, 256, BloomFilter.HashStrategy.XXH64).getBitsetSize());
  }

  @Test
  void rejectsMinimumSizeGreaterThanMaximumSize() {
    IllegalArgumentException error = assertThrows(
        IllegalArgumentException.class,
        () -> new BlockSplitBloomFilter(64, 128, 64, BloomFilter.HashStrategy.XXH64));

    assertTrue(error.getMessage().contains("minimum bytes"));
  }

  @Test
  void insertedHashesAreAlwaysFound() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(1024);

    for (int i = 0; i < 1000; i++) {
      long value = ((long) i * 0x9E3779B97F4A7C15L) ^ (i << 17);
      filter.insertHash(value);
    }

    for (int i = 0; i < 1000; i++) {
      long value = ((long) i * 0x9E3779B97F4A7C15L) ^ (i << 17);
      assertTrue(filter.findHash(value), "inserted hash " + i + " must be present");
    }
  }

