    RuntimeException error = assertThrows(RuntimeException.class, () -> filter.hash((Object) "text"));

    assertEquals("Parquet Bloom filter: Not supported type", error.getMessage());
  }

  @Test
  void reportsAlgorithmHashStrategyAndCompression() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(64);

    assertSame(BloomFilter.HashStrategy.XXH64, filter.getHashStrategy());
    assertSame(BloomFilter.Algorithm.BLOCK, filter.getAlgorithm());
    assertSame(BloomFilter.Compression.UNCOMPRESSED, filter.getCompression());
    assertEquals("xxhash", filter.getHashStrategy().toString());
    assertEquals("block", filter.getAlgorithm().toString());
    assertEquals("uncompressed", filter.getCompression().toString());
  }

  @Test
  void canMergeOnlyCompatibleNonNulBloomFilters() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(64);

    assertTrue(filter.canMergeFrom(new BlockSplitBloomFilter(64)));
    assertFalse(filter.canMergeFrom(new BlockSplitBloomFilter(128)));
    assertFalse(filter.canMergeFrom(null));
  }

  @Test
  void mergeCombinesBitsetsWithBitwiseOr() throws IOException {
    byte[] leftBits = new byte[64];
    byte[] rightBits = new byte[64];
    leftBits[0] = 0x0f;
    leftBits[17] = 0x40;
    leftBits[63] = 0x01;
    rightBits[0] = 0x30;
    rightBits[17] = 0x80;
    rightBits[31] = 0x02;

    BlockSplitBloomFilter left = new BlockSplitBloomFilter(leftBits.clone());
    BlockSplitBloomFilter right = new BlockSplitBloomFilter(rightBits.clone());
    left.merge(right);

    byte[] expected = leftBits.clone();
    for (int i = 0; i < expected.length; i++) {
      expected[i] |= rightBits[i];
    }
    ByteArrayOutputStream output = new ByteArrayOutputStream();
    left.writeTo(output);
    assertArrayEquals(expected, output.toByteArray());
  }

  @Test
  void mergeRejectsIncompatibleOrNullFilters() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(64);

    assertThrows(IllegalArgumentException.class, () -> filter.merge(null));
    IllegalArgumentException mismatch = assertThrows(
        IllegalArgumentException.class, () -> filter.merge(new BlockSplitBloomFilter(128)));
    assertTrue(mismatch.getMessage().contains("same size"));
