    assertThrows(IllegalArgumentException.class, () -> BlockSplitBloomFilter.optimalNumOfBits(100, 1.1));
  }

  @Test
  void optimalNumOfBitsGrowsWithCardinalityAndHandlesOverflow() {
    int small = BlockSplitBloomFilter.optimalNumOfBits(100, DEFAULT_FPP);
    int large = BlockSplitBloomFilter.optimalNumOfBits(10_000, DEFAULT_FPP);

    assertTrue(small >= LOWER_BOUND_BYTES * 8);
    assertTrue(large > small);
    assertEquals(UPPER_BOUND_BYTES * 8, BlockSplitBloomFilter.optimalNumOfBits(Long.MAX_VALUE, DEFAULT_FPP));
  }

  private static byte[] littleEndian(int value) {
    return ByteBuffer.allocate(Integer.BYTES)
        .order(ByteOrder.LITTLE_ENDIAN)
        .putInt(value)
        .array();
  }

