import org.apache.parquet.schema.Types;
import org.junit.jupiter.api.Test;

class BloomFilterWriterStoreTest {

  private static final ColumnDescriptor COLUMN = new ColumnDescriptor(
      new String[] {"root", "value"},
      Types.optional(PrimitiveTypeName.INT32).named("value"),
      0,
      1);

  @Test
  void writerAcceptsBloomFiltersAndDefaultCloseIsANoOp() {
    List<BloomFilter> written = new ArrayList<>();
    BloomFilterWriter writer = written::add;
    BloomFilter filter = new BlockSplitBloomFilter(32);

    writer.writeBloomFilter(filter);
    writer.writeBloomFilter(filter);
    assertDoesNotThrow(writer::close);

    assertEquals(2, written.size());
    assertSame(filter, written.get(0));
    assertSame(filter, written.get(1));
  }

  @Test
  void storeProvidesAColumnWriterThatParticipatesInTryWithResources() {
    List<BloomFilter> written = new ArrayList<>();
    BloomFilterWriter writer = written::add;
    BloomFilterWriteStore store = requestedColumn -> {
      assertEquals(COLUMN, requestedColumn);
      return writer;
    };
    BloomFilter filter = new BlockSplitBloomFilter(64);

    try (BloomFilterWriteStore closeableStore = store) {
      BloomFilterWriter columnWriter = closeableStore.getBloomFilterWriter(COLUMN);
      assertSame(writer, columnWriter);
      columnWriter.writeBloomFilter(filter);
    }

    assertEquals(1, written.size());
    assertSame(filter, written.get(0));
  }
}
