package org.apache.parquet.column.values.bloomfilter;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import org.apache.parquet.column.ColumnDescriptor;
import org.apache.parquet.io.api.Binary;
import org.apache.parquet.schema.PrimitiveType.PrimitiveTypeName;
import org.apache.parquet.schema.Types;
import org.junit.jupiter.api.Test;

class AdaptiveBlockSplitBloomFilterTest {

  private static final ColumnDescriptor COLUMN = new ColumnDescriptor(
      new String[] {"root", "id"},
      Types.optional(PrimitiveTypeName.INT64).named("id"),
      0,
      1);

  @Test
  void startsWithTheSmallestCandidateWithinTheMaximumSize() {
    AdaptiveBlockSplitBloomFilter filter = new AdaptiveBlockSplitBloomFilter(8192, 4, 0.01, COLUMN);

    assertEquals(1024, filter.getBitsetSize());
    assertEquals(1024, filter.getBitsetSize(), "querying the size must not change candidate selection");
  }

  @Test
  void emptyFilterDoesNotReportMembership() {
    AdaptiveBlockSplitBloomFilter filter = new AdaptiveBlockSplitBloomFilter(8192, 4, 0.01, COLUMN);

    assertFalse(filter.findHash(0L));
    assertFalse(filter.findHash(-1L));
    assertFalse(filter.findHash(123456789L));
  }

  @Test
  void insertedHashesAreFoundAndPromoteTheSelectedCandidateAsCardinalityGrows() {
    AdaptiveBlockSplitBloomFilter filter = new AdaptiveBlockSplitBloomFilter(8192, 4, 0.01, COLUMN);
    List<Long> hashes = new ArrayList<>();

    assertEquals(1024, filter.getBitsetSize());
    insertDistinct(filter, 1, hashes);
    assertEquals(1024, filter.getBitsetSize());

    insertDistinct(filter, 501, hashes);
    assertEquals(2048, filter.getBitsetSize());

    insertDistinct(filter, 1501, hashes);
    assertEquals(4096, filter.getBitsetSize());

    insertDistinct(filter, 3001, hashes);
    assertEquals(8192, filter.getBitsetSize());

    for (long hash : hashes) {
      assertTrue(filter.findHash(hash), "all inserted hashes must remain visible after promotions");
    }
  }

  @Test
  void serializesTheSelectedCandidateAndThenRejectsFurtherInsertions() throws IOException {
    AdaptiveBlockSplitBloomFilter filter = new AdaptiveBlockSplitBloomFilter(8192, 4, 0.01, COLUMN);
    List<Long> hashes = new ArrayList<>();
    insertDistinct(filter, 501, hashes);

    ByteArrayOutputStream output = new ByteArrayOutputStream();
    filter.writeTo(output);
    byte[] serialized = output.toByteArray();

    assertEquals(2048, serialized.length);
    assertEquals(filter.getBitsetSize(), serialized.length);
    BlockSplitBloomFilter reconstructed = new BlockSplitBloomFilter(serialized);
    for (long hash : hashes) {
      assertTrue(reconstructed.findHash(hash));
    }

    IllegalArgumentException error = assertThrows(
        IllegalArgumentException.class, () -> filter.insertHash(filter.hash(999_999L)));
    assertTrue(error.getMessage().contains("finalized"));
  }

  @Test
  void canSerializeAnEmptyFilterWithoutAColumnDescriptor() throws IOException {
    AdaptiveBlockSplitBloomFilter filter = new AdaptiveBlockSplitBloomFilter(8192, 4, 0.01, null);
    int selectedSize = filter.getBitsetSize();

    ByteArrayOutputStream output = new ByteArrayOutputStream();
    filter.writeTo(output);

    assertEquals(selectedSize, output.size());
    assertEquals(selectedSize, new BlockSplitBloomFilter(output.toByteArray()).getBitsetSize());
  }

  @Test
  void fallsBackToTheMinimumCandidateWhenTheMaximumIsTooSmallOrThereAreNoCandidates() {
    int[][] cases = {
      {-1, 2},
      {0, 2},
      {32, 2},
      {1023, 4}
    };

    for (int[] testCase : cases) {
      AdaptiveBlockSplitBloomFilter filter =
          new AdaptiveBlockSplitBloomFilter(testCase[0], testCase[1], 0.01, COLUMN);
      assertEquals(BlockSplitBloomFilter.LOWER_BOUND_BYTES, filter.getBitsetSize());
    }

    AdaptiveBlockSplitBloomFilter noCandidates =
        new AdaptiveBlockSplitBloomFilter(8192, 0, 0.01, COLUMN);
    assertEquals(BlockSplitBloomFilter.LOWER_BOUND_BYTES, noCandidates.getBitsetSize());
  }

  @Test
  void validatesFalsePositiveProbabilityWhenInitializingCandidates() {
    assertThrows(IllegalArgumentException.class, () -> new AdaptiveBlockSplitBloomFilter(8192, 1, 0.0, COLUMN));
    assertThrows(IllegalArgumentException.class, () -> new AdaptiveBlockSplitBloomFilter(8192, 1, 1.0, COLUMN));
    assertThrows(IllegalArgumentException.class, () -> new AdaptiveBlockSplitBloomFilter(8192, 1, -0.5, COLUMN));
    assertThrows(IllegalArgumentException.class, () -> new AdaptiveBlockSplitBloomFilter(8192, 1, 1.5, COLUMN));
  }

  @Test
  void hashesValuesUsingTheSelectedHashStrategy() {
    AdaptiveBlockSplitBloomFilter filter = new AdaptiveBlockSplitBloomFilter(8192, 4, 0.01, COLUMN);
    XxHash xxHash = new XxHash();

    int intValue = 0x01020304;
    long longValue = 0x0102030405060708L;
    float floatValue = 1.25f;
    double doubleValue = -2.5d;
    byte[] binaryBytes = "adaptive".getBytes(StandardCharsets.UTF_8);
    Binary binary = Binary.fromConstantByteArray(binaryBytes);

    assertEquals(xxHash.hashBytes(littleEndian(intValue)), filter.hash(intValue));
    assertEquals(xxHash.hashBytes(littleEndian(longValue)), filter.hash(longValue));
    assertEquals(xxHash.hashBytes(littleEndian(floatValue)), filter.hash(floatValue));
    assertEquals(xxHash.hashBytes(littleEndian(doubleValue)), filter.hash(doubleValue));
    assertEquals(xxHash.hashBytes(binaryBytes), filter.hash(binary));
    assertEquals(filter.hash(intValue), filter.hash((Object) intValue));
    assertEquals(filter.hash(longValue), filter.hash((Object) longValue));
    assertEquals(filter.hash(floatValue), filter.hash((Object) floatValue));
    assertEquals(filter.hash(doubleValue), filter.hash((Object) doubleValue));
    assertEquals(filter.hash(binary), filter.hash((Object) binary));
  }

  @Test
  void exposesTheUnderlyingFilterMetadata() {
    AdaptiveBlockSplitBloomFilter filter = new AdaptiveBlockSplitBloomFilter(
        8192, BloomFilter.HashStrategy.XXH64, 0.01, 4, COLUMN);

    assertSame(BloomFilter.HashStrategy.XXH64, filter.getHashStrategy());
    assertSame(BloomFilter.Algorithm.BLOCK, filter.getAlgorithm());
    assertSame(BloomFilter.Compression.UNCOMPRESSED, filter.getCompression());
  }

  @Test
  void adaptiveFiltersDoNotSupportMergeOperations() {
    AdaptiveBlockSplitBloomFilter first = new AdaptiveBlockSplitBloomFilter(8192, 2, 0.01, COLUMN);
    AdaptiveBlockSplitBloomFilter second = new AdaptiveBlockSplitBloomFilter(8192, 2, 0.01, COLUMN);

    assertThrows(UnsupportedOperationException.class, () -> first.canMergeFrom(second));
    assertThrows(UnsupportedOperationException.class, () -> first.merge(second));
  }

  private static void insertDistinct(AdaptiveBlockSplitBloomFilter filter, int targetCount, List<Long> hashes) {
    long value = 0;
    while (hashes.size() < targetCount) {
      long hash = filter.hash(value++);
      if (!filter.findHash(hash)) {
        filter.insertHash(hash);
        hashes.add(hash);
      }
    }
  }

  private static byte[] littleEndian(int value) {
    return ByteBuffer.allocate(Integer.BYTES)
        .order(ByteOrder.LITTLE_ENDIAN)
        .putInt(value)
        .array();
  }

  private static byte[] littleEndian(long value) {
    return ByteBuffer.allocate(Long.BYTES).order(ByteOrder.LITTLE_ENDIAN).putLong(value).array();
  }

  private static byte[] littleEndian(float value) {
    return ByteBuffer.allocate(Float.BYTES).order(ByteOrder.LITTLE_ENDIAN).putFloat(value).array();
  }

  private static byte[] littleEndian(double value) {
    return ByteBuffer.allocate(Double.BYTES)
        .order(ByteOrder.LITTLE_ENDIAN)
        .putDouble(value)
        .array();
  }
}
