 *
 * @param v the long value to write
 */
public void writeLong(long v) {
  if (currentSlab.remaining() < 8) {
    addSlab(8);
  }
  currentSlab.putLong(v);
  bytesUsed = Math.addExact(bytesUsed, 8);
}

