  void fallBackAllValuesToClearsTheStateWhenNoPageWasWritten() {
    PlainIntegerDictionaryValuesWriter writer = intWriter();
    writer.writeInteger(1);
    writer.writeInteger(2);

    RecordingValuesWriter plainWriter = new RecordingValuesWriter();
    writer.fallBackAllValuesTo(plainWriter);

    assertThat(plainWriter.values()).containsExactly(1, 2);
    assertThat(writer.getDictionarySize()).isZero();
    assertThat(writer.getBufferedSize()).isZero();
    assertThat(writer.getAllocatedSize()).isZero();
    assertThat(writer.shouldFallBack()).isFalse();
  }

  @Test
  void fallBackAllValuesToKeepsTheDictionaryWhenAPageWasAlreadyWritten() {
    PlainIntegerDictionaryValuesWriter writer = intWriter();
    writer.writeInteger(1);
    writer.writeInteger(2);
    writer.getBytes().toByteArray();

    RecordingValuesWriter plainWriter = new RecordingValuesWriter();
    writer.fallBackAllValuesTo(plainWriter);

