import org.apache.parquet.column.values.dictionary.PlainValuesDictionary.PlainFloatDictionary;
import org.apache.parquet.column.values.dictionary.PlainValuesDictionary.PlainIntegerDictionary;
import org.apache.parquet.column.values.dictionary.PlainValuesDictionary.PlainLongDictionary;
import org.apache.parquet.io.api.Binary;
import org.junit.jupiter.api.Test;

class DictionaryValuesWriterTest {

  private static final int MAX_DICTIONARY_BYTES = 1024;
  private static final ByteBufferAllocator ALLOCATOR = new HeapByteBufferAllocator();
  private static final Encoding DATA_PAGE_ENCODING = Encoding.RLE_DICTIONARY;
  private static final Encoding DICTIONARY_PAGE_ENCODING = Encoding.PLAIN;

  private static PlainIntegerDictionaryValuesWriter intWriter(int maxDictionaryByteSize) {
    return new PlainIntegerDictionaryValuesWriter(
        maxDictionaryByteSize, DATA_PAGE_ENCODING, DICTIONARY_PAGE_ENCODING, ALLOCATOR);
  }

  private static PlainIntegerDictionaryValuesWriter intWriter() {
    return intWriter(MAX_DICTIONARY_BYTES);
  }

  private static PlainLongDictionaryValuesWriter longWriter() {
    return new PlainLongDictionaryValuesWriter(
        MAX_DICTIONARY_BYTES, DATA_PAGE_ENCODING, DICTIONARY_PAGE_ENCODING, ALLOCATOR);
  }

  private static PlainFloatDictionaryValuesWriter floatWriter() {
    return new PlainFloatDictionaryValuesWriter(
        MAX_DICTIONARY_BYTES, DATA_PAGE_ENCODING, DICTIONARY_PAGE_ENCODING, ALLOCATOR);
  }

  private static PlainDoubleDictionaryValuesWriter doubleWriter() {
    return new PlainDoubleDictionaryValuesWriter(
        MAX_DICTIONARY_BYTES, DATA_PAGE_ENCODING, DICTIONARY_PAGE_ENCODING, ALLOCATOR);
  }

  private static PlainBinaryDictionaryValuesWriter binaryWriter() {
    return new PlainBinaryDictionaryValuesWriter(
        MAX_DICTIONARY_BYTES, DATA_PAGE_ENCODING, DICTIONARY_PAGE_ENCODING, ALLOCATOR);
  }

  private static PlainFixedLenArrayDictionaryValuesWriter fixedLenWriter(int length) {
    return new PlainFixedLenArrayDictionaryValuesWriter(
        MAX_DICTIONARY_BYTES, length, DATA_PAGE_ENCODING, DICTIONARY_PAGE_ENCODING, ALLOCATOR);
  }

  private static DictionaryValuesReader readerFor(
      PlainValuesDictionary dictionary, DictionaryValuesWriter writer) throws IOException {
    byte[] dataPage = writer.getBytes().toByteArray();
    DictionaryValuesReader reader = new DictionaryValuesReader(dictionary);
    reader.initFromPage(0, BytesInput.from(dataPage).toInputStream());
    return reader;
  }

  /** A {@link ValuesWriter} that simply records the values written to it. */
  private static final class RecordingValuesWriter extends ValuesWriter {
    private final List<Object> values = new ArrayList<>();

    List<Object> values() {
      return values;
    }

    @Override
    public long getBufferedSize() {
      return values.size();
    }

    @Override
    public BytesInput getBytes() {
      return BytesInput.empty();
    }

    @Override
    public Encoding getEncoding() {
      return Encoding.PLAIN;
    }

    @Override
    public void reset() {
      values.clear();
    }

    @Override
    public long getAllocatedSize() {
      return values.size();
    }

    @Override
    public String memUsageString(String prefix) {
      return prefix;
    }

    @Override
    public void writeInteger(int v) {
      values.add(v);
    }

    @Override
    public void writeLong(long v) {
      values.add(v);
    }

    @Override
    public void writeFloat(float v) {
      values.add(v);
    }

    @Override
    public void writeDouble(double v) {
      values.add(v);
    }

    @Override
    public void writeBytes(Binary v) {
      values.add(v.copy());
    }
  }

  @Test
  void newWriterHasAnEmptyDictionaryAndNoBufferedValues() {
    PlainIntegerDictionaryValuesWriter writer = intWriter();

    assertThat(writer.getDictionarySize()).isZero();
    assertThat(writer.getBufferedSize()).isZero();
    assertThat(writer.getAllocatedSize()).isZero();
    assertThat(writer.shouldFallBack()).isFalse();
  }

  @Test
  void writerTracksDistinctDictionaryEntriesAndBufferedValues() {
    PlainIntegerDictionaryValuesWriter writer = intWriter();

    writer.writeInteger(5);
    writer.writeInteger(5);
    writer.writeInteger(7);

    assertThat(writer.getDictionarySize()).isEqualTo(2);
    // one buffered id per written value, 4 bytes each
    assertThat(writer.getBufferedSize()).isEqualTo(3 * 4L);
    // 2 dictionary entries of 4 bytes plus the 3 buffered ids
    assertThat(writer.getAllocatedSize()).isEqualTo(3 * 4L + 2 * 4L);
  }

  @Test
  void bufferedSizeCountsFourBytesPerValueForBinaryWriters() {
    PlainBinaryDictionaryValuesWriter writer = binaryWriter();

    writer.writeBytes(Binary.fromString("a"));
    writer.writeBytes(Binary.fromString("bb"));

    assertThat(writer.getBufferedSize()).isEqualTo(2 * 4L);
    assertThat(writer.getDictionarySize()).isEqualTo(2);
    assertThat(writer.getAllocatedSize()).isEqualTo(8L + (4 + 1) + (4 + 2));
  }

  @Test
  void memUsageStringReportsDictionaryAndValueBytes() {
    PlainIntegerDictionaryValuesWriter writer = intWriter();
    writer.writeInteger(5);
    writer.writeInteger(5);
    writer.writeInteger(7);

    assertThat(writer.memUsageString("  "))
        .contains("DictionaryValuesWriter{")
        .contains("dict:8")
        .contains("values:12");
  }

  @Test
  void shouldFallBackOnlyWhenTheDictionaryByteSizeExceedsTheLimit() {
    PlainIntegerDictionaryValuesWriter writer = intWriter(2 * 4);

    writer.writeInteger(1);
    assertThat(writer.shouldFallBack()).isFalse();
    writer.writeInteger(2);
    // exactly at the limit is still acceptable
    assertThat(writer.shouldFallBack()).isFalse();
    writer.writeInteger(3);
    assertThat(writer.shouldFallBack()).isTrue();
  }

  @Test
  void repeatedValuesDoNotGrowTheDictionary() {
    PlainIntegerDictionaryValuesWriter writer = intWriter(4);

    for (int i = 0; i < 10; i++) {
      writer.writeInteger(42);
    }

    assertThat(writer.getDictionarySize()).isEqualTo(1);
    assertThat(writer.getBufferedSize()).isEqualTo(40L);
    assertThat(writer.getAllocatedSize()).isEqualTo(44L);
    assertThat(writer.shouldFallBack()).isFalse();
  }

  @Test
  void getEncodingReturnsTheConfiguredDataPageEncoding() {
    assertThat(intWriter().getEncoding()).isEqualTo(DATA_PAGE_ENCODING);
    assertThat(binaryWriter().getEncoding()).isEqualTo(DATA_PAGE_ENCODING);
    assertThat(fixedLenWriter(4).getEncoding()).isEqualTo(DATA_PAGE_ENCODING);
  }

  @Test
  void dataPageStartsWithTheBitWidthNeededForTheDictionarySize() throws IOException {
    PlainIntegerDictionaryValuesWriter writer = intWriter();
    for (int i = 0; i < 5; i++) {
      writer.writeInteger(i);
    }

    byte[] dataPage = writer.getBytes().toByteArray();

    // 5 dictionary entries require ids in [0, 4] which need 3 bits
    assertThat(dataPage[0]).isEqualTo((byte) 3);
  }

  @Test
  void integerValuesRoundTripThroughDataAndDictionaryPages() throws IOException {
    PlainIntegerDictionaryValuesWriter writer = intWriter();
    int[] values = {10, 20, 10, -30, 20, 10};
    for (int value : values) {
      writer.writeInteger(value);
    }

    byte[] dataPage = writer.getBytes().toByteArray();
    DictionaryPage dictionaryPage = writer.toDictPageAndClose();
    PlainIntegerDictionary dictionary = new PlainIntegerDictionary(dictionaryPage);

    assertThat(dictionaryPage.getDictionarySize()).isEqualTo(3);
    assertThat(dictionaryPage.getEncoding()).isEqualTo(DICTIONARY_PAGE_ENCODING);
    assertThat(dictionary.getMaxId()).isEqualTo(2);

    DictionaryValuesReader reader = new DictionaryValuesReader(dictionary);
    reader.initFromPage(values.length, BytesInput.from(dataPage).toInputStream());
    for (int value : values) {
      assertThat(reader.readInteger()).isEqualTo(value);
    }
  }

  @Test
  void longValuesRoundTripThroughDataAndDictionaryPages() throws IOException {
    PlainLongDictionaryValuesWriter writer = longWriter();
    long[] values = {Long.MIN_VALUE, 0L, 1234567890123L, 0L};
    for (long value : values) {
      writer.writeLong(value);
    }

    byte[] dataPage = writer.getBytes().toByteArray();
    DictionaryPage dictionaryPage = writer.toDictPageAndClose();
    PlainLongDictionary dictionary = new PlainLongDictionary(dictionaryPage);

    assertThat(dictionaryPage.getDictionarySize()).isEqualTo(3);

    DictionaryValuesReader reader = new DictionaryValuesReader(dictionary);
    reader.initFromPage(values.length, BytesInput.from(dataPage).toInputStream());
    for (long value : values) {
      assertThat(reader.readLong()).isEqualTo(value);
    }
  }

  @Test
  void floatValuesRoundTripThroughDataAndDictionaryPages() throws IOException {
    PlainFloatDictionaryValuesWriter writer = floatWriter();
    float[] values = {1.5f, -0.25f, 1.5f, Float.NaN};
    for (float value : values) {
      writer.writeFloat(value);
    }

    byte[] dataPage = writer.getBytes().toByteArray();
    DictionaryPage dictionaryPage = writer.toDictPageAndClose();
    PlainFloatDictionary dictionary = new PlainFloatDictionary(dictionaryPage);

    assertThat(dictionaryPage.getDictionarySize()).isEqualTo(3);

    DictionaryValuesReader reader = new DictionaryValuesReader(dictionary);
    reader.initFromPage(values.length, BytesInput.from(dataPage).toInputStream());
    assertThat(reader.readFloat()).isEqualTo(1.5f);
    assertThat(reader.readFloat()).isEqualTo(-0.25f);
    assertThat(reader.readFloat()).isEqualTo(1.5f);
    assertThat(reader.readFloat()).isNaN();
  }

  @Test
  void doubleValuesRoundTripThroughDataAndDictionaryPages() throws IOException {
    PlainDoubleDictionaryValuesWriter writer = doubleWriter();
    double[] values = {Math.PI, Double.NEGATIVE_INFINITY, Math.PI};
    for (double value : values) {
      writer.writeDouble(value);
    }

    byte[] dataPage = writer.getBytes().toByteArray();
    DictionaryPage dictionaryPage = writer.toDictPageAndClose();
    PlainDoubleDictionary dictionary = new PlainDoubleDictionary(dictionaryPage);

    assertThat(dictionaryPage.getDictionarySize()).isEqualTo(2);

    DictionaryValuesReader reader = new DictionaryValuesReader(dictionary);
    reader.initFromPage(values.length, BytesInput.from(dataPage).toInputStream());
    assertThat(reader.readDouble()).isEqualTo(Math.PI);
    assertThat(reader.readDouble()).isEqualTo(Double.NEGATIVE_INFINITY);
    assertThat(reader.readDouble()).isEqualTo(Math.PI);
  }

  @Test
  void binaryValuesRoundTripThroughDataAndDictionaryPages() throws IOException {
    PlainBinaryDictionaryValuesWriter writer = binaryWriter();
    Binary[] values = {
      Binary.fromString("alpha"), Binary.fromString(""), Binary.fromString("alpha"), Binary.fromString("beta")
    };
    for (Binary value : values) {
      writer.writeBytes(value);
    }

    byte[] dataPage = writer.getBytes().toByteArray();
    DictionaryPage dictionaryPage = writer.toDictPageAndClose();
    PlainBinaryDictionary dictionary = new PlainBinaryDictionary(dictionaryPage);

    assertThat(dictionaryPage.getDictionarySize()).isEqualTo(3);
    assertThat(dictionary.decodeToBinary(0)).isEqualTo(Binary.fromString("alpha"));
    assertThat(dictionary.decodeToBinary(1).length()).isZero();
    assertThat(dictionary.decodeToBinary(2)).isEqualTo(Binary.fromString("beta"));

    DictionaryValuesReader reader = new DictionaryValuesReader(dictionary);
    reader.initFromPage(values.length, BytesInput.from(dataPage).toInputStream());
    for (Binary value : values) {
      assertThat(reader.readBytes()).isEqualTo(value);
    }
  }

  @Test
  void fixedLengthValuesRoundTripThroughFixedLengthDictionaryPage() throws IOException {
    PlainFixedLenArrayDictionaryValuesWriter writer = fixedLenWriter(3);
    Binary[] values = {Binary.fromString("abc"), Binary.fromString("def"), Binary.fromString("abc")};
    for (Binary value : values) {
      writer.writeBytes(value);
    }

    byte[] dataPage = writer.getBytes().toByteArray();
    DictionaryPage dictionaryPage = writer.toDictPageAndClose();
    PlainBinaryDictionary dictionary = new PlainBinaryDictionary(dictionaryPage, 3);

    assertThat(dictionaryPage.getDictionarySize()).isEqualTo(2);
    assertThat(dictionary.decodeToBinary(0).toStringUsingUTF8()).isEqualTo("abc");
    assertThat(dictionary.decodeToBinary(1).toStringUsingUTF8()).isEqualTo("def");

    DictionaryValuesReader reader = new DictionaryValuesReader(dictionary);
    reader.initFromPage(values.length, BytesInput.from(dataPage).toInputStream());
    for (Binary value : values) {
      assertThat(reader.readBytes()).isEqualTo(value);
    }
  }

  @Test
  void binaryWriterCountsTheLengthPrefixInTheDictionaryByteSize() {
    PlainBinaryDictionaryValuesWriter writer = binaryWriter();

    writer.writeBytes(Binary.fromString("ab"));
    writer.writeBytes(Binary.fromString("abcd"));
    writer.writeBytes(Binary.fromString("ab"));

    assertThat(writer.getDictionarySize()).isEqualTo(2);
    assertThat(writer.getAllocatedSize()).isEqualTo(3 * 4L + (4 + 2) + (4 + 4));
  }

  @Test
  void fixedLengthWriterCountsTheConfiguredLengthPerEntry() {
    PlainFixedLenArrayDictionaryValuesWriter writer = fixedLenWriter(3);

    writer.writeBytes(Binary.fromString("abc"));
    writer.writeBytes(Binary.fromString("def"));
    writer.writeBytes(Binary.fromString("abc"));

    assertThat(writer.getDictionarySize()).isEqualTo(2);
    assertThat(writer.getAllocatedSize()).isEqualTo(3 * 4L + 2 * 3L);
  }

  @Test
  void floatWriterDistinguishesPositiveAndNegativeZero() {
    PlainFloatDictionaryValuesWriter writer = floatWriter();

    writer.writeFloat(0.0f);
    writer.writeFloat(-0.0f);
    writer.writeFloat(0.0f);

    assertThat(writer.getDictionarySize()).isEqualTo(2);

    RecordingValuesWriter plainWriter = new RecordingValuesWriter();
    writer.fallBackAllValuesTo(plainWriter);
    assertThat(plainWriter.values()).containsExactly(0.0f, -0.0f, 0.0f);
  }

  @Test
  void doubleWriterDistinguishesPositiveAndNegativeZero() {
    PlainDoubleDictionaryValuesWriter writer = doubleWriter();

    writer.writeDouble(-0.0d);
    writer.writeDouble(0.0d);

    assertThat(writer.getDictionarySize()).isEqualTo(2);

    RecordingValuesWriter plainWriter = new RecordingValuesWriter();
    writer.fallBackAllValuesTo(plainWriter);
    assertThat(plainWriter.values()).containsExactly(-0.0d, 0.0d);
  }

  @Test
  void toDictPageAndCloseReturnsNullWhenTheDictionaryWasNeverUsed() {
    PlainIntegerDictionaryValuesWriter writer = intWriter();

    assertThat(writer.toDictPageAndClose()).isNull();
  }

  @Test
  void toDictPageAndCloseOnlyContainsEntriesUsedByTheLastPage() throws IOException {
    PlainIntegerDictionaryValuesWriter writer = intWriter();
    writer.writeInteger(1);
    writer.writeInteger(2);
    writer.getBytes().toByteArray();
    // entries written after the page was produced are not part of it yet
    writer.writeInteger(3);
    writer.writeInteger(4);

    DictionaryPage dictionaryPage = writer.toDictPageAndClose();

    assertThat(dictionaryPage.getDictionarySize()).isEqualTo(2);
    PlainIntegerDictionary dictionary = new PlainIntegerDictionary(dictionaryPage);
    assertThat(dictionary.getMaxId()).isEqualTo(1);
    assertThat(dictionary.decodeToInt(0)).isEqualTo(1);
    assertThat(dictionary.decodeToInt(1)).isEqualTo(2);
  }

  @Test
  void resetDictionaryClearsTheDictionaryButKeepsBufferedValues() {
    PlainIntegerDictionaryValuesWriter writer = intWriter();
    writer.writeInteger(1);
    writer.writeInteger(2);
    writer.writeInteger(1);

    writer.resetDictionary();

    assertThat(writer.getDictionarySize()).isZero();
    assertThat(writer.getBufferedSize()).isEqualTo(3 * 4L);
    assertThat(writer.getAllocatedSize()).isEqualTo(3 * 4L);
    assertThat(writer.shouldFallBack()).isFalse();
    assertThat(writer.toDictPageAndClose()).isNull();
  }

  @Test
  void resetDictionaryStartsAFreshDictionaryForTheNextPage() throws IOException {
    PlainIntegerDictionaryValuesWriter writer = intWriter();
    writer.writeInteger(1);
    writer.writeInteger(2);
    writer.getBytes().toByteArray();

    writer.reset();
    writer.resetDictionary();
    writer.writeInteger(7);
    writer.writeInteger(8);
    byte[] dataPage = writer.getBytes().toByteArray();
    DictionaryPage dictionaryPage = writer.toDictPageAndClose();

    assertThat(dictionaryPage.getDictionarySize()).isEqualTo(2);
    PlainIntegerDictionary dictionary = new PlainIntegerDictionary(dictionaryPage);
    assertThat(dictionary.decodeToInt(0)).isEqualTo(7);
    assertThat(dictionary.decodeToInt(1)).isEqualTo(8);

    DictionaryValuesReader reader = new DictionaryValuesReader(dictionary);
    reader.initFromPage(2, BytesInput.from(dataPage).toInputStream());
    assertThat(reader.readInteger()).isEqualTo(7);
    assertThat(reader.readInteger()).isEqualTo(8);
  }

  @Test
  void resetClearsBufferedValuesButKeepsTheDictionary() {
    PlainIntegerDictionaryValuesWriter writer = intWriter();
    writer.writeInteger(1);
    writer.writeInteger(2);
    writer.writeInteger(1);

    writer.reset();

    assertThat(writer.getBufferedSize()).isZero();
    assertThat(writer.getDictionarySize()).isEqualTo(2);
    assertThat(writer.getAllocatedSize()).isEqualTo(2 * 4L);
  }

  @Test
  void fallBackAllValuesToWritesValuesInTheirOriginalOrder() {
    PlainIntegerDictionaryValuesWriter writer = intWriter();
    int[] values = {1, 2, 1, 3, 2, 1};
    for (int value : values) {
      writer.writeInteger(value);
    }

    RecordingValuesWriter plainWriter = new RecordingValuesWriter();
    writer.fallBackAllValuesTo(plainWriter);

    assertThat(plainWriter.values()).containsExactly(1, 2, 1, 3, 2, 1);
  }

  @Test
  void fallBackAllValuesToClearsTheStateWhenNoPageWasWritten() {
    PlainIntegerDictionaryValuesWriter writer = intWriter();
    writer.writeInteger(1);
    writer.writeInteger(2);

    RecordingValuesWriter plainWriter = new RecordingValuesWriter();
    writer.fallBackAllValuesTo(plainWriter);

    assertThat(plainWriter.values()).containsExactly(1, 2);
    assertThat(writer.getDictionarySize()).isZero();
    assertThat(writer.getBufferedSize()).isZero();
    assertThat(writer.getAllocatedSize()).isZero();
    assertThat(writer.shouldFallBack()).isFalse();
  }

  @Test
  void fallBackAllValuesToKeepsTheDictionaryWhenAPageWasAlreadyWritten() {
    PlainIntegerDictionaryValuesWriter writer = intWriter();
    writer.writeInteger(1);
    writer.writeInteger(2);
    writer.getBytes().toByteArray();

    RecordingValuesWriter plainWriter = new RecordingValuesWriter();
    writer.fallBackAllValuesTo(plainWriter);

    assertThat(plainWriter.values()).containsExactly(1, 2);
    assertThat(writer.getDictionarySize()).isEqualTo(2);
    assertThat(writer.getBufferedSize()).isEqualTo(2 * 4L);
    assertThat(writer.getAllocatedSize()).isEqualTo(2 * 4L + 2 * 4L);
  }

  @Test
  void fallBackForLongValuesReencodesTheOriginalValues() {
    PlainLongDictionaryValuesWriter writer = longWriter();
    long[] values = {Long.MAX_VALUE, -1L, Long.MAX_VALUE, 0L};
    for (long value : values) {
      writer.writeLong(value);
    }

    RecordingValuesWriter plainWriter = new RecordingValuesWriter();
    writer.fallBackAllValuesTo(plainWriter);

    assertThat(plainWriter.values()).containsExactly(Long.MAX_VALUE, -1L, Long.MAX_VALUE, 0L);
  }

  @Test
  void fallBackForDoubleValuesReencodesTheOriginalValues() {
    PlainDoubleDictionaryValuesWriter writer = doubleWriter();
    double[] values = {Math.E, -1.5d, Math.E};
    for (double value : values) {
      writer.writeDouble(value);
    }

    RecordingValuesWriter plainWriter = new RecordingValuesWriter();
    writer.fallBackAllValuesTo(plainWriter);

    assertThat(plainWriter.values()).containsExactly(Math.E, -1.5d, Math.E);
  }

  @Test
  void fallBackForBinaryValuesReencodesTheOriginalValues() {
    PlainBinaryDictionaryValuesWriter writer = binaryWriter();
    Binary[] values = {Binary.fromString("a"), Binary.fromString("bb"), Binary.fromString("a")};
    for (Binary value : values) {
      writer.writeBytes(value);
    }

    RecordingValuesWriter plainWriter = new RecordingValuesWriter();
    writer.fallBackAllValuesTo(plainWriter);

    assertThat(plainWriter.values())
        .containsExactly(Binary.fromString("a"), Binary.fromString("bb"), Binary.fromString("a"));
  }

  @Test
  void fallBackForFixedLengthValuesReencodesTheOriginalValues() {
    PlainFixedLenArrayDictionaryValuesWriter writer = fixedLenWriter(2);
    Binary[] values = {Binary.fromString("ab"), Binary.fromString("cd"), Binary.fromString("ab")};
    for (Binary value : values) {
      writer.writeBytes(value);
    }

    RecordingValuesWriter plainWriter = new RecordingValuesWriter();
    writer.fallBackAllValuesTo(plainWriter);

    assertThat(plainWriter.values())
        .containsExactly(Binary.fromString("ab"), Binary.fromString("cd"), Binary.fromString("ab"));
  }

  @Test
  void isCompressionSatisfyingIncludesTheDictionarySize() {
    PlainIntegerDictionaryValuesWriter writer = intWriter();

    assertThat(writer.isCompressionSatisfying(100, 99)).isTrue();
    assertThat(writer.isCompressionSatisfying(100, 100)).isFalse();

    writer.writeInteger(1);

    // the single 4 byte dictionary entry is added to the encoded size
    assertThat(writer.isCompressionSatisfying(100, 95)).isTrue();
    assertThat(writer.isCompressionSatisfying(100, 96)).isFalse();
  }
}
