@SuppressWarnings("deprecation")
class DictionaryValuesReaderTest {

  /** A dictionary that is never consulted, used for tests that only look at the encoded ids. */
  private static final class OpaqueDictionary extends Dictionary {
    OpaqueDictionary() {
      super(Encoding.PLAIN);
    }

    @Override
    public int getMaxId() {
      return 0;
    }
  }

  private static BytesInput encodeIds(int bitWidth, int... ids) throws IOException {
    RunLengthBitPackingHybridEncoder encoder =
        new RunLengthBitPackingHybridEncoder(bitWidth, 64, 1024, new HeapByteBufferAllocator());
    try {
      for (int id : ids) {
        encoder.writeInt(id);
      }
      BytesInput page = BytesInput.concat(BytesInput.from(new byte[] {(byte) bitWidth}), encoder.toBytes());
      // materialize the page while the encoder still owns its buffer
      return BytesInput.from(page.toByteArray());
    } finally {
      encoder.close();
    }
  }

  private static DictionaryValuesReader readerFor(Dictionary dictionary, BytesInput page) throws IOException {
    DictionaryValuesReader reader = new DictionaryValuesReader(dictionary);
    reader.initFromPage(0, page.toInputStream());
    return reader;
  }

  private static DictionaryValuesReader emptyPageReader(Dictionary dictionary) throws IOException {
    DictionaryValuesReader reader = new DictionaryValuesReader(dictionary);
    reader.initFromPage(0, ByteBufferInputStream.wrap(ByteBuffer.allocate(0)));
    return reader;
  }

  private static PlainIntegerDictionary intDictionary(int... values) throws IOException {
    ByteBuffer buffer = ByteBuffer.allocate(values.length * 4).order(ByteOrder.LITTLE_ENDIAN);
    for (int value : values) {
      buffer.putInt(value);
    }
    return new PlainIntegerDictionary(
        new DictionaryPage(BytesInput.from(buffer.array()), values.length, Encoding.PLAIN));
  }

  private static PlainLongDictionary longDictionary(long... values) throws IOException {
    ByteBuffer buffer = ByteBuffer.allocate(values.length * 8).order(ByteOrder.LITTLE_ENDIAN);
    for (long value : values) {
      buffer.putLong(value);
    }
    return new PlainLongDictionary(
        new DictionaryPage(BytesInput.from(buffer.array()), values.length, Encoding.PLAIN));
  }

  private static PlainFloatDictionary floatDictionary(float... values) throws IOException {
    ByteBuffer buffer = ByteBuffer.allocate(values.length * 4).order(ByteOrder.LITTLE_ENDIAN);
    for (float value : values) {
      buffer.putInt(Float.floatToRawIntBits(value));
    }
    return new PlainFloatDictionary(
        new DictionaryPage(BytesInput.from(buffer.array()), values.length, Encoding.PLAIN));
  }

  private static PlainDoubleDictionary doubleDictionary(double... values) throws IOException {
    ByteBuffer buffer = ByteBuffer.allocate(values.length * 8).order(ByteOrder.LITTLE_ENDIAN);
    for (double value : values) {
      buffer.putLong(Double.doubleToRawLongBits(value));
    }
    return new PlainDoubleDictionary(
        new DictionaryPage(BytesInput.from(buffer.array()), values.length, Encoding.PLAIN));
  }

  private static PlainBinaryDictionary binaryDictionary(String... values) throws IOException {
    int size = 4 * values.length;
    for (String value : values) {
      size += value.getBytes(StandardCharsets.UTF_8).length;
    }
    ByteBuffer buffer = ByteBuffer.allocate(size).order(ByteOrder.LITTLE_ENDIAN);
    for (String value : values) {
      byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
      buffer.putInt(bytes.length);
      buffer.put(bytes);
    }
    return new PlainBinaryDictionary(
        new DictionaryPage(BytesInput.from(buffer.array()), values.length, Encoding.PLAIN));
  }

