  /** Records the order in which resources are closed and fails on demand. */
  private static class RecordingResource implements AutoCloseable {
    private final String id;
    private final List<String> closeOrder;
    private final Throwable failure;

    RecordingResource(String id, List<String> closeOrder, Throwable failure) {
      this.id = id;
      this.closeOrder = closeOrder;
      this.failure = failure;
    }

    RecordingResource(String id, List<String> closeOrder) {
      this(id, closeOrder, null);
    }

    @Override
    public void close() throws Exception {
      closeOrder.add(id);
      if (failure instanceof Error) {
        throw (Error) failure;
      } else if (failure != null) {
        throw (Exception) failure;
      }
    }
  }

  @Test
  public void closeIterableClosesEveryResourceInIterationOrder() throws Throwable {
    List<String> closed = new ArrayList<>();
    AutoCloseables.close(Arrays.asList(
        new RecordingResource("a", closed), new RecordingResource("b", closed), new RecordingResource("c", closed)));

    assertThat(closed).containsExactly("a", "b", "c");
  }

