  public void closeVarargsSkipsNullsAndWithNoArgumentsDoesNothing() throws Throwable {
    List<String> closed = new ArrayList<>();
    AutoCloseables.close((AutoCloseable) null, new RecordingResource("only", closed), null);

    assertThat(closed).containsExactly("only");
    assertThatCode(AutoCloseables::close).doesNotThrowAnyException();
  }

