  public void closeContinuesAfterFailureAndRethrowsFirstFailure() {
    List<String> closed = new ArrayList<>();
    IllegalArgumentException first = new IllegalArgumentException("first failure");
    IllegalStateException second = new IllegalStateException("second failure");

    assertThatThrownBy(() -> AutoCloseables.close(
            new RecordingResource("a", closed, first),
            new RecordingResource("b", closed),
            new RecordingResource("c", closed, second)))
        .isSameAs(first);

    assertThat(closed).containsExactly("a", "b", "c");
