package org.apache.parquet.util;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.apache.parquet.ParquetRuntimeException;
import org.apache.parquet.util.AutoCloseables.ParquetCloseResourceException;
import org.junit.jupiter.api.Test;

public class AutoCloseablesTest {

  /** Records the order in which resources are closed and fails on demand. */
  private static class RecordingResource implements AutoCloseable {
    private final String id;
    private final List<String> closeOrder;
    private final Throwable failure;

    RecordingResource(String id, List<String> closeOrder, Throwable failure) {
      this.id = id;
      this.closeOrder = closeOrder;
      this.failure = failure;
    }

    RecordingResource(String id, List<String> closeOrder) {
      this(id, closeOrder, null);
    }

    @Override
    public void close() throws Exception {
      closeOrder.add(id);
      if (failure instanceof Error) {
        throw (Error) failure;
      } else if (failure != null) {
        throw (Exception) failure;
      }
    }
  }

  @Test
  public void closeIterableClosesEveryResourceInIterationOrder() throws Throwable {
    List<String> closed = new ArrayList<>();
    AutoCloseables.close(Arrays.asList(
        new RecordingResource("a", closed), new RecordingResource("b", closed), new RecordingResource("c", closed)));

    assertThat(closed).containsExactly("a", "b", "c");
  }

  @Test
  public void closeIterableSkipsNullResources() throws Throwable {
    List<String> closed = new ArrayList<>();
    AutoCloseables.close(Arrays.asList(
        new RecordingResource("a", closed), null, new RecordingResource("b", closed)));

    assertThat(closed).containsExactly("a", "b");
  }

  @Test
  public void closeIterableWithNoResourcesDoesNothing() throws Throwable {
    assertThatCode(() -> AutoCloseables.close(Collections.<AutoCloseable>emptyList()))
        .doesNotThrowAnyException();
  }

  @Test
  public void closeVarargsClosesEveryResource() throws Throwable {
    List<String> closed = new ArrayList<>();
    AutoCloseables.close(new RecordingResource("first", closed), new RecordingResource("second", closed));

    assertThat(closed).containsExactly("first", "second");
  }

  @Test
  public void closeVarargsSkipsNullsAndWithNoArgumentsDoesNothing() throws Throwable {
    List<String> closed = new ArrayList<>();
    AutoCloseables.close((AutoCloseable) null, new RecordingResource("only", closed), null);

    assertThat(closed).containsExactly("only");
    assertThatCode(AutoCloseables::close).doesNotThrowAnyException();
  }

  @Test
  public void closeContinuesAfterFailureAndRethrowsFirstFailure() {
    List<String> closed = new ArrayList<>();
    IllegalArgumentException first = new IllegalArgumentException("first failure");
    IllegalStateException second = new IllegalStateException("second failure");

    assertThatThrownBy(() -> AutoCloseables.close(
            new RecordingResource("a", closed, first),
            new RecordingResource("b", closed),
            new RecordingResource("c", closed, second)))
        .isSameAs(first);

    assertThat(closed).containsExactly("a", "b", "c");
    assertThat(first.getSuppressed()).containsExactly(second);
  }

  @Test
  public void closeVarargsCollectsAllFailuresAsSuppressed() {
    List<String> closed = new ArrayList<>();
    RuntimeException first = new RuntimeException("1");
    RuntimeException second = new RuntimeException("2");
    RuntimeException third = new RuntimeException("3");

    assertThatThrownBy(() -> AutoCloseables.close(
            new RecordingResource("a", closed, first),
            new RecordingResource("b", closed, second),
            new RecordingResource("c", closed, third)))
        .isSameAs(first);

    assertThat(closed).containsExactly("a", "b", "c");
    assertThat(first.getSuppressed()).containsExactly(second, third);
  }

  @Test
  public void closePropagatesErrorsAndStillClosesRemainingResources() {
    List<String> closed = new ArrayList<>();
    AssertionError error = new AssertionError("boom");
    IllegalStateException later = new IllegalStateException("later");

    assertThatThrownBy(() -> AutoCloseables.close(
            new RecordingResource("a", closed, error), new RecordingResource("b", closed, later)))
        .isSameAs(error);

    assertThat(closed).containsExactly("a", "b");
    assertThat(error.getSuppressed()).containsExactly(later);
  }

  @Test
  public void uncheckedCloseIterableWrapsFailureIntoParquetCloseResourceException() {
    List<String> closed = new ArrayList<>();
    IllegalStateException failure = new IllegalStateException("cannot close");
    List<AutoCloseable> resources = Arrays.asList(
        new RecordingResource("a", closed, failure), new RecordingResource("b", closed));

    assertThatThrownBy(() -> AutoCloseables.uncheckedClose(resources))
        .isInstanceOf(ParquetCloseResourceException.class)
        .isInstanceOf(ParquetRuntimeException.class)
        .hasMessage("Unable to close resource")
        .hasCause(failure);

    assertThat(closed).containsExactly("a", "b");
  }

  @Test
  public void uncheckedCloseKeepsSuppressedExceptionsOnTheWrappedCause() {
    List<String> closed = new ArrayList<>();
    RuntimeException first = new RuntimeException("first");
    RuntimeException second = new RuntimeException("second");

    assertThatThrownBy(() -> AutoCloseables.uncheckedClose(
            Arrays.asList(new RecordingResource("a", closed, first), new RecordingResource("b", closed, second))))
        .isInstanceOf(ParquetCloseResourceException.class)
        .hasCause(first);

    assertThat(first.getSuppressed()).containsExactly(second);
    assertThat(closed).containsExactly("a", "b");
  }

  @Test
  public void uncheckedCloseVarargsWrapsFailure() {
    List<String> closed = new ArrayList<>();
    IllegalArgumentException failure = new IllegalArgumentException("bad close");

    assertThatThrownBy(() ->
            AutoCloseables.uncheckedClose(new RecordingResource("a", closed, failure), null))
        .isInstanceOf(ParquetCloseResourceException.class)
        .hasCause(failure);

    assertThat(closed).containsExactly("a");
  }

  @Test
  public void uncheckedCloseDoesNotThrowWhenEverythingClosesCleanly() {
    List<String> closed = new ArrayList<>();

    assertThatCode(() -> {
          AutoCloseables.uncheckedClose(Arrays.<AutoCloseable>asList(new RecordingResource("a", closed)));
          AutoCloseables.uncheckedClose(new RecordingResource("b", closed), null);
        })
        .doesNotThrowAnyException();

    assertThat(closed).containsExactly("a", "b");
  }
}
