import org.apache.parquet.util.DynMethods.UnboundMethod;
import org.junit.jupiter.api.Test;

public class DynMethodsTest {

  public static class Calculator {
    private final int base;

    public Calculator(int base) {
      this.base = base;
    }

    public int getBase() {
      return base;
    }

    public int add(int a, int b) {
      return base + a + b;
    }

    public String echo(String value) {
      return "echo:" + value;
    }

    public static int twice(int value) {
      return 2 * value;
    }

    public static int sum(int... values) {
      int total = 0;
      for (int value : values) {
        total += value;
      }
      return total;
    }

    public String checkedFailure() throws IOException {
      throw new IOException("checked boom");
    }

    public String runtimeFailure() {
      throw new IllegalStateException("runtime boom");
    }

    public String errorFailure() {
      throw new AssertionError("error boom");
    }

    private String secret() {
      return "hidden";
    }
  }

  public static class SubCalculator extends Calculator {
    public SubCalculator(int base) {
      super(base);
    }
  }

  public static class FirstValue {
    public String who() {
      return "first";
    }
  }

  public static class SecondValue {
    public String who() {
      return "second";
    }
  }

  private final Calculator calculator = new Calculator(10);

  @Test
  public void buildFindsPublicInstanceMethodAndInvokesIt() {
    BoundMethod method = new DynMethods.Builder("add")
        .impl(Calculator.class, int.class, int.class)
        .build(calculator);

    assertThat(method.<Integer>invoke(1, 2)).isEqualTo(13);
  }

  @Test
  public void buildCheckedFindsMethodAndCanBeBoundAfterwards() throws Exception {
    UnboundMethod method = new DynMethods.Builder("echo")
        .impl(Calculator.class, String.class)
        .buildChecked();

    assertThat(method.<String>invokeChecked(calculator, "hi")).isEqualTo("echo:hi");
    assertThat(method.bind(calculator).<String>invoke("yo")).isEqualTo("echo:yo");
  }

  @Test
  public void buildCheckedThrowsNoSuchMethodExceptionWhenNothingMatches() {
    assertThatThrownBy(() -> new DynMethods.Builder("missing")
            .impl(Calculator.class, int.class)
            .buildChecked())
        .isInstanceOf(NoSuchMethodException.class)
        .hasMessage("Cannot find method: missing");
  }

  @Test
  public void buildThrowsRuntimeExceptionWhenNothingMatches() {
    assertThatThrownBy(() -> new DynMethods.Builder("missing").build())
        .isInstanceOf(RuntimeException.class)
        .hasMessage("Cannot find method: missing");
  }

  @Test
  public void explicitMethodNameOverridesTheBuilderName() {
    UnboundMethod method = new DynMethods.Builder("unusedName")
        .impl(Calculator.class, "add", int.class, int.class)
        .build();

    assertThat(method.<Integer>invoke(calculator, 5, 5)).isEqualTo(20);
    assertThat(method.toString())
        .startsWith("DynMethods.UnboundMethod(name=unusedName method=")
        .contains("add(int, int)");
  }

  @Test
  public void implResolvesClassByNameUsingTheConfiguredLoader() {
    UnboundMethod method = new DynMethods.Builder("echo")
        .loader(getClass().getClassLoader())
        .impl(Calculator.class.getName(), String.class)
        .build();

    assertThat(method.<String>invoke(calculator, "named")).isEqualTo("echo:named");
  }

  @Test
  public void implIgnoresUnknownClassNamesAndReportsFailureOnBuild() {
    DynMethods.Builder builder = new DynMethods.Builder("echo")
        .loader(getClass().getClassLoader())
        .impl("org.apache.parquet.util.DoesNotExist", String.class);

    assertThatThrownBy(builder::build).isInstanceOf(RuntimeException.class);
  }

  @Test
  public void loaderReturnsTheSameBuilderForChaining() {
    DynMethods.Builder builder = new DynMethods.Builder("echo");

    assertThat(builder.loader(getClass().getClassLoader())).isSameAs(builder);
  }

  @Test
  public void firstMatchingImplementationWins() {
    UnboundMethod firstWins = new DynMethods.Builder("who")
        .impl(FirstValue.class)
        .impl(SecondValue.class)
        .build();
    UnboundMethod secondWins = new DynMethods.Builder("who")
        .impl(SecondValue.class)
        .impl(FirstValue.class)
        .build();

    assertThat(firstWins.<String>invoke(new FirstValue())).isEqualTo("first");
    assertThat(secondWins.<String>invoke(new SecondValue())).isEqualTo("second");
  }

  @Test
  public void implementationsThatDoNotMatchAreSkipped() {
    UnboundMethod method = new DynMethods.Builder("who")
        .impl(Calculator.class)
        .impl(FirstValue.class)
        .build();

    assertThat(method.<String>invoke(new FirstValue())).isEqualTo("first");
  }

  @Test
  public void orNoopProvidesAZeroArgumentNoopMethod() {
    UnboundMethod noop = new DynMethods.Builder("missing")
        .impl(Calculator.class, int.class)
        .orNoop()
        .build();

    assertThat(noop.isNoop()).isTrue();
    assertThat(noop.isStatic()).isTrue();
    assertThat(noop.toString()).isEqualTo("DynMethods.UnboundMethod(NOOP)");
    assertThat(noop.<Object>invoke(null, "ignored", 3)).isNull();
    assertThat(noop.bind(calculator).<Object>invoke()).isNull();
    assertThat(noop.asStatic().<Object>invoke()).isNull();
  }

  @Test
  public void orNoopDoesNotReplaceAnAlreadyFoundImplementation() {
    UnboundMethod method = new DynMethods.Builder("twice")
        .impl(Calculator.class, int.class)
        .orNoop()
        .build();

    assertThat(method.isNoop()).isFalse();
    assertThat(method.<Integer>invoke(null, 4)).isEqualTo(8);
  }

  @Test
  public void implIsIgnoredOnceNoopHasBeenInstalled() {
    UnboundMethod method = new DynMethods.Builder("twice")
        .orNoop()
        .impl(Calculator.class, int.class)
        .build();

    assertThat(method.isNoop()).isTrue();
    assertThat(method.<Object>invoke(null, 4)).isNull();
  }

  @Test
  public void isStaticReflectsTheUnderlyingMethod() {
    UnboundMethod instanceMethod =
        new DynMethods.Builder("add").impl(Calculator.class, int.class, int.class).build();
    UnboundMethod staticMethod =
        new DynMethods.Builder("twice").impl(Calculator.class, int.class).build();

    assertThat(instanceMethod.isStatic()).isFalse();
    assertThat(staticMethod.isStatic()).isTrue();
  }

  @Test
  public void bindingAStaticMethodIsRejected() {
    UnboundMethod staticMethod =
        new DynMethods.Builder("twice").impl(Calculator.class, int.class).build();

    assertThatThrownBy(() -> staticMethod.bind(calculator))
        .isInstanceOf(IllegalStateException.class)
        .hasMessageContaining("Cannot bind static method");
  }

  @Test
  public void bindingToAnIncompatibleReceiverIsRejected() {
    UnboundMethod method =
        new DynMethods.Builder("add").impl(Calculator.class, int.class, int.class).build();

    assertThatThrownBy(() -> method.bind("not a calculator"))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessageContaining("Cannot bind");
  }

  @Test
  public void bindingToASubclassInstanceIsAllowed() {
    SubCalculator subCalculator = new SubCalculator(1);
    UnboundMethod method =
        new DynMethods.Builder("add").impl(Calculator.class, int.class, int.class).build();

    assertThat(method.bind(subCalculator).<Integer>invoke(2, 3)).isEqualTo(6);
  }

  @Test
  public void asStaticRejectsInstanceMethods() {
    UnboundMethod method =
        new DynMethods.Builder("add").impl(Calculator.class, int.class, int.class).build();

    assertThatThrownBy(method::asStatic)
        .isInstanceOf(IllegalStateException.class)
        .hasMessageContaining("Method is not static");
  }

  @Test
  public void buildStaticInvokesStaticMethod() {
    StaticMethod twice =
        new DynMethods.Builder("twice").impl(Calculator.class, int.class).buildStatic();

    assertThat(twice.<Integer>invoke(21)).isEqualTo(42);
  }

  @Test
  public void buildStaticCheckedInvokesStaticMethod() throws Exception {
    StaticMethod echo = new DynMethods.Builder("echo")
        .impl(Calculator.class, String.class)
        .buildStaticChecked();

    assertThat(echo.<String>invokeChecked(calculator, "via static")).isEqualTo("echo:via static");
  }

  @Test
  public void invokeCheckedPropagatesCheckedExceptions() {
    UnboundMethod method =
        new DynMethods.Builder("checkedFailure").impl(Calculator.class).build();

    assertThatThrownBy(() -> method.invokeChecked(calculator))
        .isInstanceOf(IOException.class)
        .hasMessage("checked boom");
  }

  @Test
  public void invokeCheckedPropagatesRuntimeExceptions() {
    UnboundMethod method =
        new DynMethods.Builder("runtimeFailure").impl(Calculator.class).build();

    assertThatThrownBy(() -> method.invokeChecked(calculator))
        .isInstanceOf(IllegalStateException.class)
        .hasMessage("runtime boom");
  }

  @Test
  public void invokeCheckedWrapsErrorsInRuntimeException() {
    UnboundMethod method =
        new DynMethods.Builder("errorFailure").impl(Calculator.class).build();

    assertThatThrownBy(() -> method.invokeChecked(calculator))
        .isInstanceOf(RuntimeException.class)
        .hasCauseInstanceOf(AssertionError.class);
  }

  @Test
  public void invokeWrapsCheckedExceptionsInRuntimeException() {
    UnboundMethod method =
        new DynMethods.Builder("checkedFailure").impl(Calculator.class).build();

    assertThatThrownBy(() -> method.invoke(calculator))
        .isInstanceOf(RuntimeException.class)
        .hasCauseInstanceOf(IOException.class);
  }

  @Test
  public void invokeRethrowsRuntimeExceptionsUnchanged() {
    UnboundMethod method =
        new DynMethods.Builder("runtimeFailure").impl(Calculator.class).build();

    assertThatThrownBy(() -> method.invoke(calculator))
        .isInstanceOf(IllegalStateException.class)
        .hasMessage("runtime boom");
  }

  @Test
  public void invokeWrapsErrorsInRuntimeException() {
    UnboundMethod method =
        new DynMethods.Builder("errorFailure").impl(Calculator.class).build();

    assertThatThrownBy(() -> method.invoke(calculator))
        .isInstanceOf(RuntimeException.class)
        .hasCauseInstanceOf(AssertionError.class);
  }

  @Test
  public void invokeTrimsSuperfluousArgumentsForFixedArityMethods() {
    UnboundMethod method =
        new DynMethods.Builder("echo").impl(Calculator.class, String.class).build();

    assertThat(method.<String>invoke(calculator, "first", "second", "third"))
        .isEqualTo("echo:first");
  }

  @Test
  public void invokePassesAllArgumentsToVarArgsMethods() {
    UnboundMethod method =
        new DynMethods.Builder("sum").impl(Calculator.class, int[].class).build();

    assertThat(method.<Integer>invoke(null, 1, 2, 3, 4)).isEqualTo(10);
    assertThat(method.<Integer>invoke(null)).isEqualTo(0);
  }

  @Test
  public void hiddenImplFindsPrivateMethods() {
    BoundMethod method = new DynMethods.Builder("secret")
        .hiddenImpl(Calculator.class)
        .build(calculator);

    assertThat(method.<String>invoke()).isEqualTo("hidden");
  }

  @Test
  public void hiddenImplSkipsClassesWithoutTheMethod() {
    BoundMethod method = new DynMethods.Builder("secret")
        .hiddenImpl(String.class)
        .hiddenImpl(Calculator.class)
        .build(calculator);

    assertThat(method.<String>invoke()).isEqualTo("hidden");
  }

  @Test
  public void hiddenImplByClassNameUsesTheConfiguredLoader() {
    BoundMethod method = new DynMethods.Builder("secret")
        .loader(getClass().getClassLoader())
        .hiddenImpl(Calculator.class.getName())
        .build(calculator);

    assertThat(method.<String>invoke()).isEqualTo("hidden");
  }

  @Test
  public void hiddenImplWithExplicitMethodNameFindsAPublicMethodToo() {
    BoundMethod method = new DynMethods.Builder("ignored")
        .hiddenImpl(Calculator.class, "echo", String.class)
        .build(calculator);

    assertThat(method.<String>invoke("x")).isEqualTo("echo:x");
  }

  @Test
  public void ctorImplInvokesConstructorThroughUnboundMethod() {
    UnboundMethod method =
        new DynMethods.Builder("ignored").ctorImpl(Calculator.class, int.class).build();
