    assertThat(method.isStatic()).isTrue();
  }

  @Test
  public void ctorImplByClassNameInvokesConstructor() {
    UnboundMethod method = new DynMethods.Builder("ignored")
        .ctorImpl(Calculator.class.getName(), int.class)
        .build();
    Calculator created = method.invoke(null, 3);

    assertThat(created.getBase()).isEqualTo(3);
  }

  @Test
  public void ctorImplRequiresANullTarget() {
    UnboundMethod method =
        new DynMethods.Builder("ignored").ctorImpl(Calculator.class, int.class).build();

