  @Test
  public void ctorImplCannotBeBound() {
    UnboundMethod method =
        new DynMethods.Builder("ignored").ctorImpl(Calculator.class, int.class).build();

    assertThatThrownBy(() -> method.bind(calculator))
        .isInstanceOf(IllegalStateException.class)
        .hasMessageContaining("Cannot bind constructors");
  }

  @Test
  public void ctorImplFallsBackWhenTheConstructorDoesNotExist() {
    UnboundMethod method = new DynMethods.Builder("ignored")
        .ctorImpl(Calculator.class, double.class)
        .ctorImpl(Calculator.class, int.class)
        .build();
    Calculator created = method.invoke(null, 11);

    assertThat(created.getBase()).isEqualTo(11);
  }
}
