package org.apache.parquet.util;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.IOException;
import org.apache.parquet.util.DynConstructors.Ctor;
import org.apache.parquet.util.DynMethods.StaticMethod;
import org.junit.jupiter.api.Test;

public class DynConstructorsTest {

  public static class Point {
    private final int x;
    private final String label;

    public Point(int x) {
      this(x, "default");
    }

    public Point(int x, String label) {
      this.x = x;
      this.label = label;
    }

    private Point(String label) {
      this(-1, label);
    }

    public int getX() {
      return x;
    }

    public String getLabel() {
      return label;
    }
  }

  public static class CheckedFailure {
    public CheckedFailure() throws IOException {
      throw new IOException("ctor checked boom");
    }
  }

  public static class RuntimeFailure {
    public RuntimeFailure() {
      throw new IllegalStateException("ctor runtime boom");
    }
  }

  public static class ErrorFailure {
    public ErrorFailure() {
      throw new AssertionError("ctor error boom");
    }
  }

  @Test
  public void buildCheckedFindsConstructorAndCreatesInstances() throws Exception {
    Ctor<Point> ctor = new DynConstructors.Builder(Point.class)
        .impl(Point.class, int.class)
        .buildChecked();

    Point point = ctor.newInstanceChecked(5);

    assertThat(point.getX()).isEqualTo(5);
    assertThat(ctor.getConstructedClass()).isSameAs(Point.class);
    assertThat(ctor.isStatic()).isTrue();
  }

  @Test
  public void implByClassNameFindsConstructor() {
    Ctor<Point> ctor = new DynConstructors.Builder(Point.class)
        .loader(getClass().getClassLoader())
        .impl(Point.class.getName(), int.class, String.class)
        .build();

    Point point = ctor.newInstance(2, "two");

    assertThat(point.getX()).isEqualTo(2);
    assertThat(point.getLabel()).isEqualTo("two");
  }

  @Test
  public void builderWithoutBaseClassBuildsFromExplicitImpl() throws Exception {
    Ctor<Point> ctor = new DynConstructors.Builder()
        .impl(Point.class, int.class, String.class)
        .buildChecked();

    assertThat(ctor.newInstance("label", "ignored").getLabel()).isEqualTo("two");
  }

  @Test
  public void buildCheckedWithoutMatchThrowsNoSuchMethodExceptionWithCandidateDetails() {
    assertThatThrownBy(() -> new DynConstructors.Builder(Point.class)
            .impl(Point.class, double.class)
            .buildChecked())
        .isInstanceOf(NoSuchMethodException.class)
        .hasMessageContaining("Cannot find constructor for")
        .hasMessageContaining("Missing")
        .hasMessageContaining("Point(double)")
        .hasMessageContaining(NoSuchMethodException.class.getName());
  }

  @Test
  public void buildWithoutMatchThrowsRuntimeException() {
    assertThatThrownBy(() -> new DynConstructors.Builder(Point.class).build())
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("Cannot find constructor for")
        .hasMessageContaining("Point");
  }

  @Test
  public void buildWithoutMatchListsEveryFailedCandidate() {
    assertThatThrownBy(() -> new DynConstructors.Builder(Point.class)
            .impl(Point.class, double.class)
            .impl(Point.class, boolean.class)
            .build())
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("Point(double)")
        .hasMessageContaining("Point(boolean)");
  }

  @Test
  public void implIgnoresUnknownClassNames() {
    assertThatThrownBy(() -> new DynConstructors.Builder(Point.class)
            .loader(getClass().getClassLoader())
            .impl("org.apache.parquet.util.DoesNotExist", int.class)
            .build())
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("Cannot find constructor for");
  }

