    assertThatThrownBy(ctor::newInstanceChecked)
        .isInstanceOf(RuntimeException.class)
        .hasCauseInstanceOf(AssertionError.class);
  }

  @Test
  public void newInstanceWrapsCheckedExceptionsInRuntimeException() {
    Ctor<CheckedFailure> ctor =
        new DynConstructors.Builder(CheckedFailure.class).impl(CheckedFailure.class).build();

    assertThatThrownBy(ctor::newInstance)
        .isInstanceOf(RuntimeException.class)
        .hasCauseInstanceOf(IOException.class);
  }

  @Test
  public void newInstanceRethrowsRuntimeExceptions() {
    Ctor<RuntimeFailure> ctor =
        new DynConstructors.Builder(RuntimeFailure.class).impl(RuntimeFailure.class).build();

    assertThatThrownBy(ctor::newInstance)
        .isInstanceOf(IllegalStateException.class)
        .hasMessage("ctor runtime boom");
  }

  @Test
  public void newInstanceWrapsErrorsInRuntimeException() {
    Ctor<ErrorFailure> ctor =
        new DynConstructors.Builder(ErrorFailure.class).impl(ErrorFailure.class).build();

    assertThatThrownBy(ctor::newInstance)
        .isInstanceOf(RuntimeException.class)
        .hasCauseInstanceOf(AssertionError.class);
  }

  @Test
  public void invokeRequiresANullTarget() {
    Ctor<Point> ctor =
        new DynConstructors.Builder(Point.class).impl(Point.class, int.class).build();
    Point point = ctor.<Point>invoke(null, 9);

    assertThat(point.getX()).isEqualTo(9);
    assertThatThrownBy(() -> ctor.invoke(point, 1))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Invalid call to constructor: target must be null");
    assertThatThrownBy(() -> ctor.invokeChecked(point, 1))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Invalid call to constructor: target must be null");
  }

  @Test
  public void constructorsCannotBeBound() {
    Ctor<Point> ctor =
        new DynConstructors.Builder(Point.class).impl(Point.class, int.class).build();

    assertThatThrownBy(() -> ctor.bind(new Point(0)))
        .isInstanceOf(IllegalStateException.class)
        .hasMessage("Cannot bind constructors");
  }

  @Test
  public void ctorCanBeUsedAsAStaticMethod() {
    StaticMethod staticMethod = new DynConstructors.Builder(Point.class)
        .impl(Point.class, int.class)
        .build()
        .asStatic();

    Point point = staticMethod.invoke(4);

    assertThat(point.getX()).isEqualTo(4);
  }

  @Test
  public void toStringDescribesTheConstructorAndClass() {
    Ctor<Point> ctor =
        new DynConstructors.Builder(Point.class).impl(Point.class, int.class).build();

    assertThat(ctor.toString())
        .startsWith("Ctor(constructor=")
        .contains("Point(int)")
        .contains("class=class org.apache.parquet.util.DynConstructorsTest$Point");
  }

  @Test
  public void hiddenImplFindsPrivateConstructors() {
    Ctor<Point> ctor = new DynConstructors.Builder(Point.class)
        .hiddenImpl(Point.class, String.class)
        .build();

    Point point = ctor.newInstance("hidden");

    assertThat(point.getLabel()).isEqualTo("hidden");
    assertThat(point.getX()).isEqualTo(-1);
  }

  @Test
  public void hiddenImplByClassNameUsesTheConfiguredLoader() {
    Ctor<Point> ctor = new DynConstructors.Builder(Point.class)
        .loader(getClass().getClassLoader())
        .hiddenImpl(Point.class.getName(), String.class)
        .build();

    assertThat(ctor.newInstance("byName").getLabel()).isEqualTo("byName");
  }

  @Test
  public void hiddenImplFallsBackWhenTheConstructorIsMissing() {
    Ctor<Point> ctor = new DynConstructors.Builder(Point.class)
        .hiddenImpl(Point.class, double.class)
        .hiddenImpl(Point.class, String.class)
        .build();

    assertThat(ctor.newInstance("fallback").getLabel()).isEqualTo("fallback");
  }

  @Test
  public void implementationsAreIgnoredOnceOneHasBeenFound() {
    Ctor<Point> ctor = new DynConstructors.Builder(Point.class)
        .impl(Point.class, int.class, String.class)
        .impl(Point.class, int.class)
        .hiddenImpl(Point.class, String.class)
        .build();

    assertThat(ctor.newInstance(7, "seven").getLabel()).isEqualTo("seven");
  }
}
