package org.apache.parquet.util;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.IOException;
import org.apache.parquet.util.DynConstructors.Ctor;
import org.apache.parquet.util.DynMethods.StaticMethod;
import org.junit.jupiter.api.Test;

public class DynConstructorsTest {

  public static class Point {
    private final int x;
    private final String label;

    public Point(int x) {
      this(x, "default");
    }

    public Point(int x, String label) {
      this.x = x;
      this.label = label;
    }

    private Point(String label) {
      this(-1, label);
    }

    public int getX() {
      return x;
    }

    public String getLabel() {
      return label;
    }
  }

  public static class CheckedFailure {
    public CheckedFailure() throws IOException {
      throw new IOException("ctor checked boom");
    }
  }

  public static class RuntimeFailure {
    public RuntimeFailure() {
      throw new IllegalStateException("ctor runtime boom");
    }
  }

  public static class ErrorFailure {
    public ErrorFailure() {
      throw new AssertionError("ctor error boom");
    }
  }

  @Test
  public void buildCheckedFindsConstructorAndCreatesInstances() throws Exception {
    Ctor<Point> ctor = new DynConstructors.Builder(Point.class)
        .impl(Point.class, int.class)
        .buildChecked();

    Point point = ctor.newInstanceChecked(5);

    assertThat(point.getX()).isEqualTo(5);
    assertThat(ctor.getConstructedClass()).isSameAs(Point.class);
    assertThat(ctor.isStatic()).isTrue();
  }

  @Test
  public void implByClassNameFindsConstructor() {
    Ctor<Point> ctor = new DynConstructors.Builder(Point.class)
        .loader(getClass().getClassLoader())
        .impl(Point.class.getName(), int.class, String.class)
        .build();

    Point point = ctor.newInstance(2, "two");

    assertThat(point.getX()).isEqualTo(2);
    assertThat(point.getLabel()).isEqualTo("two");
  }

  @Test
  public void builderWithoutBaseClassBuildsFromExplicitImpl() throws Exception {
    Ctor<Point> ctor = new DynConstructors.Builder()
        .impl(Point.class, int.class, String.class)
        .buildChecked();

    assertThat(ctor.newInstance("label", "ignored").getLabel()).isEqualTo("two");
  }

  @Test
  public void buildCheckedWithoutMatchThrowsNoSuchMethodExceptionWithCandidateDetails() {
    assertThatThrownBy(() -> new DynConstructors.Builder(Point.class)
            .impl(Point.class, double.class)
            .buildChecked())
        .isInstanceOf(NoSuchMethodException.class)
        .hasMessageContaining("Cannot find constructor for")
        .hasMessageContaining("Missing")
        .hasMessageContaining("Point(double)")
        .hasMessageContaining(NoSuchMethodException.class.getName());
  }

  @Test
  public void buildWithoutMatchThrowsRuntimeException() {
    assertThatThrownBy(() -> new DynConstructors.Builder(Point.class).build())
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("Cannot find constructor for")
        .hasMessageContaining("Point");
  }

  @Test
  public void buildWithoutMatchListsEveryFailedCandidate() {
    assertThatThrownBy(() -> new DynConstructors.Builder(Point.class)
            .impl(Point.class, double.class)
            .impl(Point.class, boolean.class)
            .build())
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("Point(double)")
        .hasMessageContaining("Point(boolean)");
  }

  @Test
  public void implIgnoresUnknownClassNames() {
    assertThatThrownBy(() -> new DynConstructors.Builder(Point.class)
            .loader(getClass().getClassLoader())
            .impl("org.apache.parquet.util.DoesNotExist", int.class)
            .build())
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("Cannot find constructor for");
  }

  @Test
  public void firstMatchingConstructorWins() {
    Ctor<Point> twoArgFirst = new DynConstructors.Builder(Point.class)
        .impl(Point.class, int.class, String.class)
        .impl(Point.class, int.class)
        .build();

    assertThat(twoArgFirst.newInstance(1, "one").getLabel()).isEqualTo("one");
    assertThatThrownBy(() -> twoArgFirst.newInstance(1)).isInstanceOf(IllegalArgumentException.class);
  }

  @Test
  public void newInstanceCheckedPropagatesCheckedExceptions() {
    Ctor<CheckedFailure> ctor =
        new DynConstructors.Builder(CheckedFailure.class).impl(CheckedFailure.class).build();

    assertThatThrownBy(ctor::newInstanceChecked)
        .isInstanceOf(IOException.class)
        .hasMessage("ctor checked boom");
  }

  @Test
  public void newInstanceCheckedPropagatesRuntimeExceptions() {
    Ctor<RuntimeFailure> ctor =
        new DynConstructors.Builder(RuntimeFailure.class).impl(RuntimeFailure.class).build();

    assertThatThrownBy(ctor::newInstanceChecked)
        .isInstanceOf(IllegalStateException.class)
        .hasMessage("ctor runtime boom");
  }

  @Test
  public void newInstanceCheckedWrapsErrorsInRuntimeException() {
    Ctor<ErrorFailure> ctor =
        new DynConstructors.Builder(ErrorFailure.class).impl(ErrorFailure.class).build();

    assertThatThrownBy(ctor::newInstanceChecked)
        .isInstanceOf(RuntimeException.class)
        .hasCauseInstanceOf(AssertionError.class);
  }

  @Test
  public void newInstanceWrapsCheckedExceptionsInRuntimeException() {
    Ctor<CheckedFailure> ctor =
        new DynConstructors.Builder(CheckedFailure.class).impl(CheckedFailure.class).build();

    assertThatThrownBy(ctor::newInstance)
        .isInstanceOf(RuntimeException.class)
        .hasCauseInstanceOf(IOException.class);
  }

  @Test
  public void newInstanceRethrowsRuntimeExceptions() {
    Ctor<RuntimeFailure> ctor =
        new DynConstructors.Builder(RuntimeFailure.class).impl(RuntimeFailure.class).build();

    assertThatThrownBy(ctor::newInstance)
        .isInstanceOf(IllegalStateException.class)
        .hasMessage("ctor runtime boom");
  }

  @Test
  public void newInstanceWrapsErrorsInRuntimeException() {
    Ctor<ErrorFailure> ctor =
        new DynConstructors.Builder(ErrorFailure.class).impl(ErrorFailure.class).build();

    assertThatThrownBy(ctor::newInstance)
        .isInstanceOf(RuntimeException.class)
        .hasCauseInstanceOf(AssertionError.class);
  }

  @Test
  public void invokeRequiresANullTarget() {
    Ctor<Point> ctor =
        new DynConstructors.Builder(Point.class).impl(Point.class, int.class).build();
    Point point = ctor.<Point>invoke(null, 9);

    assertThat(point.getX()).isEqualTo(9);
    assertThatThrownBy(() -> ctor.invoke(point, 1))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Invalid call to constructor: target must be null");
    assertThatThrownBy(() -> ctor.invokeChecked(point, 1))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("Invalid call to constructor: target must be null");
  }

  @Test
  public void constructorsCannotBeBound() {
    Ctor<Point> ctor =
        new DynConstructors.Builder(Point.class).impl(Point.class, int.class).build();

    assertThatThrownBy(() -> ctor.bind(new Point(0)))
        .isInstanceOf(IllegalStateException.class)
        .hasMessage("Cannot bind constructors");
  }

  @Test
  public void ctorCanBeUsedAsAStaticMethod() {
    StaticMethod staticMethod = new DynConstructors.Builder(Point.class)
        .impl(Point.class, int.class)
        .build()
        .asStatic();

    Point point = staticMethod.invoke(4);

    assertThat(point.getX()).isEqualTo(4);
  }

  @Test
  public void toStringDescribesTheConstructorAndClass() {
    Ctor<Point> ctor =
        new DynConstructors.Builder(Point.class).impl(Point.class, int.class).build();

    assertThat(ctor.toString())
        .startsWith("Ctor(constructor=")
        .contains("Point(int)")
        .contains("class=class org.apache.parquet.util.DynConstructorsTest$Point");
  }

  @Test
  public void hiddenImplFindsPrivateConstructors() {
    Ctor<Point> ctor = new DynConstructors.Builder(Point.class)
        .hiddenImpl(Point.class, String.class)
        .build();

    Point point = ctor.newInstance("hidden");

    assertThat(point.getLabel()).isEqualTo("hidden");
    assertThat(point.getX()).isEqualTo(-1);
  }

  @Test
  public void hiddenImplByClassNameUsesTheConfiguredLoader() {
    Ctor<Point> ctor = new DynConstructors.Builder(Point.class)
        .loader(getClass().getClassLoader())
        .hiddenImpl(Point.class.getName(), String.class)
        .build();

    assertThat(ctor.newInstance("byName").getLabel()).isEqualTo("byName");
  }

  @Test
  public void hiddenImplFallsBackWhenTheConstructorIsMissing() {
    Ctor<Point> ctor = new DynConstructors.Builder(Point.class)
        .hiddenImpl(Point.class, double.class)
        .hiddenImpl(Point.class, String.class)
        .build();

    assertThat(ctor.newInstance("fallback").getLabel()).isEqualTo("fallback");
  }

  @Test
  public void implementationsAreIgnoredOnceOneHasBeenFound() {
    Ctor<Point> ctor = new DynConstructors.Builder(Point.class)
        .impl(Point.class, int.class, String.class)
        .impl(Point.class, int.class)
        .hiddenImpl(Point.class, String.class)
        .build();

    assertThat(ctor.newInstance(7, "seven").getLabel()).isEqualTo("seven");
  }
}
