import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.Test;

class BinaryTest {

  @Test
  void emptyConstantHasNoBytesAndCopiesToItself() {
    assertEquals(0, Binary.EMPTY.length());
    assertArrayEquals(new byte[0], Binary.EMPTY.getBytes());
    assertArrayEquals(new byte[0], Binary.EMPTY.getBytesUnsafe());
    assertFalse(Binary.EMPTY.isBackingBytesReused());
    assertEquals("Binary{0 constant bytes, []}", Binary.EMPTY.toString());
    assertSame(Binary.EMPTY, Binary.EMPTY.copy());
  }

  @Test
  void arrayFactoriesExposeBackingReuseAndDefensiveCopies() {
    byte[] bytes = {1, 2, 3};

    Binary constant = Binary.fromConstantByteArray(bytes);
    Binary reused = Binary.fromReusedByteArray(bytes);

    assertFalse(constant.isBackingBytesReused());
    assertTrue(reused.isBackingBytesReused());
    assertEquals(3, constant.length());
    assertArrayEquals(bytes, constant.getBytes());
    assertSame(bytes, constant.getBytesUnsafe());
    assertSame(bytes, reused.getBytesUnsafe());

    byte[] defensiveCopy = constant.getBytes();
    defensiveCopy[0] = 99;
    assertArrayEquals(new byte[] {1, 2, 3}, constant.getBytes());
  }

  @Test
  void sliceUsesRelativeOffsetsAndPreservesReusePolicy() {
    byte[] source = {10, 11, 12, 13, 14};

    Binary constantSlice = Binary.fromConstantByteArray(source, 1, 3);
    assertFalse(constantSlice.isBackingBytesReused());
    assertEquals(3, constantSlice.length());
    assertArrayEquals(new byte[] {11, 12, 13}, constantSlice.getBytes());

    Binary nestedConstantSlice = constantSlice.slice(1, 2);
    assertFalse(nestedConstantSlice.isBackingBytesReused());
    assertArrayEquals(new byte[] {12, 13}, nestedConstantSlice.getBytes());

    Binary reusedSlice = Binary.fromReusedByteArray(source, 1, 2);
    assertTrue(reusedSlice.isBackingBytesReused());
    Binary nestedReusedSlice = reusedSlice.slice(1, 1);
    assertTrue(nestedReusedSlice.isBackingBytesReused());
    assertArrayEquals(new byte[] {12}, nestedReusedSlice.getBytes());

    source[2] = 42;
    assertArrayEquals(new byte[] {42}, nestedReusedSlice.getBytes());
  }

  @Test
  void reusedBinaryCanBeCopiedIntoAnImmutableSnapshot() {
    byte[] source = {4, 5, 6};
    Binary reused = Binary.fromReusedByteArray(source);

    Binary copy = reused.copy();

    assertNotSame(reused, copy);
    assertFalse(copy.isBackingBytesReused());
    assertArrayEquals(new byte[] {4, 5, 6}, copy.getBytes());
    source[0] = 99;
    assertArrayEquals(new byte[] {4, 5, 6}, copy.getBytes());
  }

