    assertTrue(reusedSlice.isBackingBytesReused());
    Binary nestedReusedSlice = reusedSlice.slice(1, 1);
    assertTrue(nestedReusedSlice.isBackingBytesReused());
    assertArrayEquals(new byte[] {12}, nestedReusedSlice.getBytes());

    source[2] = 42;
    assertArrayEquals(new byte[] {42}, nestedReusedSlice.getBytes());
  }

  @Test
  void reusedBinaryCanBeCopiedIntoAnImmutableSnapshot() {
    byte[] source = {4, 5, 6};
    Binary reused = Binary.fromReusedByteArray(source);

    Binary copy = reused.copy();

    assertNotSame(reused, copy);
    assertFalse(copy.isBackingBytesReused());
    assertArrayEquals(new byte[] {4, 5, 6}, copy.getBytes());
    source[0] = 99;
    assertArrayEquals(new byte[] {4, 5, 6}, copy.getBytes());
  }

  @Test
  void constantArrayBinaryReturnsItselfWhenCopied() {
    Binary constant = Binary.fromConstantByteArray(new byte[] {7, 8});
    Binary string = Binary.fromString("constant");

    assertSame(constant, constant.copy());
    assertSame(string, string.copy());
  }

  @Test
  void equalityAndHashCodeIgnoreRepresentationAndUseBinaryContent() {
    ByteBuffer direct = ByteBuffer.allocateDirect(3);
    direct.put(new byte[] {1, 2, 3}).flip();

    Binary fromArray = Binary.fromConstantByteArray(new byte[] {1, 2, 3});
    Binary fromOffset = Binary.fromConstantByteArray(new byte[] {9, 1, 2, 3, 9}, 1, 3);
    Binary fromHeapBuffer = Binary.fromConstantByteBuffer(ByteBuffer.wrap(new byte[] {1, 2, 3}));
    Binary fromDirectBuffer = Binary.fromConstantByteBuffer(direct);

    for (Binary left : new Binary[] {fromArray, fromOffset, fromHeapBuffer, fromDirectBuffer}) {
      for (Binary right : new Binary[] {fromArray, fromOffset, fromHeapBuffer, fromDirectBuffer}) {
        assertEquals(left, right);
        assertEquals(left.hashCode(), right.hashCode());
      }
    }

    assertFalse(fromArray.equals(Binary.fromConstantByteArray(new byte[] {1, 2, 3, 4})));
    assertFalse(fromArray.equals(Binary.fromConstantByteArray(new byte[] {1, 2, 4})));
    assertFalse(fromArray.equals("not a binary"));
    assertFalse(fromArray.equals(null));
  }

  @Test
  void unsignedLexicographicOrderingHandlesHighBitBytes() {
    Binary highBit = Binary.fromConstantByteArray(new byte[] {(byte) 0x80});
    Binary lower = Binary.fromConstantByteArray(new byte[] {0x7F});

    assertTrue(lower.compareTo(highBit) < 0);
    assertTrue(highBit.compareTo(lower) > 0);
    assertEquals(0, Binary.lexicographicCompare(lower, lower));
    assertTrue(Binary.lexicographicCompare(lower, highBit) < 0);
    assertTrue(Binary.lexicographicCompare(highBit, lower) > 0);
  }

  @Test
  void lexicographicOrderingUsesPrefixLengthAsTieBreaker() {
    Binary prefix = Binary.fromConstantByteArray(new byte[] {1, 2});
    Binary longer = Binary.fromConstantByteArray(new byte[] {1, 2, 0});
    Binary different = Binary.fromConstantByteArray(new byte[] {1, 3});

    assertTrue(prefix.compareTo(longer) < 0);
    assertTrue(longer.compareTo(prefix) > 0);
    assertTrue(prefix.compareTo(different) < 0);
    assertEquals(0, prefix.compareTo(Binary.fromConstantByteArray(new byte[] {1, 2})));
  }

  @Test
  void byteBufferSourcePositionIsCapturedWithoutBeingMutated() {
    ByteBuffer source = ByteBuffer.wrap(new byte[] {0, 1, 2, 3, 4});
    source.position(1);
    source.limit(4);

    Binary binary = Binary.fromConstantByteBuffer(source);

    assertEquals(3, binary.length());
    assertEquals(1, source.position());
    assertEquals(4, source.limit());
    assertArrayEquals(new byte[] {1, 2, 3}, binary.getBytes());
    assertEquals(1, source.position());
    assertEquals(4, source.limit());
  }

  @Test
  void explicitByteBufferOffsetsSelectTheExpectedRange() {
    ByteBuffer source = ByteBuffer.wrap(new byte[] {9, 8, 7, 6, 5});
    Binary binary = Binary.fromConstantByteBuffer(source, 1, 3);

    assertEquals(3, binary.length());
    assertArrayEquals(new byte[] {8, 7, 6}, binary.getBytes());
    assertArrayEquals(new byte[] {8, 7, 6}, Binary.fromConstantByteBuffer(source, 1, 3)
        .toByteBuffer()
        .remaining() == 3
            ? new byte[] {8, 7, 6}
            : new byte[] {});
  }

  @Test
  void toByteBufferReturnsExactlyTheBinaryContent() {
    Binary slice = Binary.fromConstantByteArray(new byte[] {0, 1, 2, 3}, 1, 2);
    ByteBuffer buffer = slice.toByteBuffer();
    byte[] actual = new byte[buffer.remaining()];
    buffer.get(actual);

    assertEquals(2, actual.length);
    assertArrayEquals(new byte[] {1, 2}, actual);
  }

  @Test
  void directByteBufferContentIsAvailableWithoutChangingSourcePosition() {
    ByteBuffer source = ByteBuffer.allocateDirect(4);
    source.put(new byte[] {10, 20, 30, 40}).flip();
    source.position(1);

    Binary binary = Binary.fromConstantByteBuffer(source);
    byte[] bytes = binary.getBytes();
    ByteBuffer view = binary.toByteBuffer();
    byte[] viewed = new byte[view.remaining()];
    view.get(viewed);

    assertArrayEquals(new byte[] {20, 30, 40}, bytes);
    assertArrayEquals(new byte[] {20, 30, 40}, viewed);
    assertEquals(1, source.position());
  }

  @Test
  void littleEndianTwoByteAccessorRejectsOtherLengths() {
    Binary binary = Binary.fromConstantByteArray(new byte[] {0x34, 0x12});
    assertEquals((short) 0x1234, binary.get2BytesLittleEndian());

    assertThrows(IllegalArgumentException.class, Binary.EMPTY::get2BytesLittleEndian);
    assertThrows(
        IllegalArgumentException.class,
        () -> Binary.fromConstantByteArray(new byte[] {1}).get2BytesLittleEndian());
    assertThrows(
        IllegalArgumentException.class,
        () -> Binary.fromConstantByteArray(new byte[] {1, 2, 3}).get2BytesLittleEndian());
  }

  @Test
  void littleEndianTwoByteAccessorWorksForByteBufferBackedBinary() {
    Binary binary = Binary.fromConstantByteBuffer(ByteBuffer.wrap(new byte[] {9, 0x78, 0x56, 9}, 1, 2));
    assertEquals((short) 0x5678, binary.get2BytesLittleEndian());
  }

  @Test
  void utf8DecodingWorksForArrayAndBufferBackedValues() {
    byte[] utf8 = "héllo".getBytes(StandardCharsets.UTF_8);

    assertEquals("héllo", Binary.fromConstantByteArray(utf8).toStringUsingUTF8());
    assertEquals("héllo", Binary.fromConstantByteBuffer(ByteBuffer.wrap(utf8)).toStringUsingUTF8());
  }
}
