package org.apache.parquet.io.api;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.jupiter.api.Test;

class RecordConsumerTest {

  @Test
  void supportsTheDocumentedNestedRecordWorkflow() {
    RecordingRecordConsumer consumer = new RecordingRecordConsumer();

    consumer.startMessage();
    consumer.startField("A", 0);
    consumer.addInteger(1);
    consumer.addInteger(2);
    consumer.endField("A", 0);
    consumer.startField("B", 1);
    consumer.startGroup();
    consumer.startField("C", 0);
    consumer.addInteger(3);
    consumer.endField("C", 0);
    consumer.endGroup();
    consumer.endField("B", 1);
    consumer.endMessage();

    assertEquals(
        Arrays.asList(
            "startMessage",
            "startField:A@0",
            "integer:1",
            "integer:2",
            "endField:A@0",
            "startField:B@1",
            "startGroup",
            "startField:C@0",
            "integer:3",
            "endField:C@0",
            "endGroup",
            "endField:B@1",
            "endMessage"),
        consumer.events);
  }

  @Test
  void dispatchesEachValueTypeToItsCallback() {
    RecordingRecordConsumer consumer = new RecordingRecordConsumer();
    consumer.startField("values", 3);
    consumer.addLong(9L);
    consumer.addBoolean(true);
    consumer.addBinary(Binary.fromString("abc"));
    consumer.addFloat(1.25f);
    consumer.addDouble(2.5d);
    consumer.endField("values", 3);

    assertEquals(
        Arrays.asList(
            "startField:values@3",
            "long:9",
            "boolean:true",
            "binary:abc",
            "float:1.25",
            "double:2.5",
            "endField:values@3"),
        consumer.events);
  }

  @Test
  void flushIsANoOpByDefault() {
    RecordingRecordConsumer consumer = new RecordingRecordConsumer();

    consumer.flush();

    assertTrue(consumer.events.isEmpty());
  }

  private static final class RecordingRecordConsumer extends RecordConsumer {
    private final List<String> events = new ArrayList<>();

    @Override
    public void startMessage() {
      events.add("startMessage");
    }

    @Override
    public void endMessage() {
      events.add("endMessage");
    }

    @Override
    public void startField(String field, int index) {
      events.add("startField:" + field + "@" + index);
    }

    @Override
    public void endField(String field, int index) {
      events.add("endField:" + field + "@" + index);
    }

    @Override
    public void startGroup() {
      events.add("startGroup");
    }

    @Override
    public void endGroup() {
      events.add("endGroup");
    }

    @Override
    public void addInteger(int value) {
      events.add("integer:" + value);
    }

    @Override
    public void addLong(long value) {
      events.add("long:" + value);
    }

    @Override
    public void addBoolean(boolean value) {
      events.add("boolean:" + value);
    }

    @Override
    public void addBinary(Binary value) {
      events.add("binary:" + value.toStringUsingUTF8());
    }

    @Override
    public void addFloat(float value) {
      events.add("float:" + value);
    }

    @Override
    public void addDouble(double value) {
      events.add("double:" + value);
    }
  }
}
