package org.apache.parquet.io.api;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.apache.parquet.io.ParquetDecodingException;
import org.junit.jupiter.api.Test;

class RecordMaterializerTest {

  @Test
  void exposesCurrentRecordAndRootConverter() {
    SimpleMaterializer materializer = new SimpleMaterializer();

    assertSame(materializer.root, materializer.getRootConverter());
    assertTrue(materializer.getRootConverter().asGroupConverter() == materializer.root);
    assertEquals("materialized record", materializer.getCurrentRecord());
    assertEquals(1, materializer.materializationCalls);
  }

  @Test
  void skippingDoesNotMaterializeTheCurrentRecordByDefault() {
    SimpleMaterializer materializer = new SimpleMaterializer();

    materializer.skipCurrentRecord();

    assertEquals(0, materializer.materializationCalls);
  }

  @Test
  void recordMaterializationExceptionSupportsItsConstructors() {
    RecordMaterializer.RecordMaterializationException empty =
        new RecordMaterializer.RecordMaterializationException();
    assertNull(empty.getMessage());
    assertNull(empty.getCause());

    RecordMaterializer.RecordMaterializationException withMessage =
        new RecordMaterializer.RecordMaterializationException("cannot materialize");
    assertEquals("cannot materialize", withMessage.getMessage());
    assertNull(withMessage.getCause());

    IllegalStateException cause = new IllegalStateException("bad value");
    RecordMaterializer.RecordMaterializationException withCause =
        new RecordMaterializer.RecordMaterializationException(cause);
    assertSame(cause, withCause.getCause());

    RecordMaterializer.RecordMaterializationException withMessageAndCause =
        new RecordMaterializer.RecordMaterializationException("cannot materialize", cause);
    assertEquals("cannot materialize", withMessageAndCause.getMessage());
    assertSame(cause, withMessageAndCause.getCause());
  }

  @Test
  void recordMaterializationExceptionIsAParquetDecodingException() {
    RecordMaterializer.RecordMaterializationException exception =
        new RecordMaterializer.RecordMaterializationException("skip me");

    assertInstanceOf(ParquetDecodingException.class, exception);
  }

  private static final class SimpleMaterializer extends RecordMaterializer<String> {
    private final GroupConverter root = new GroupConverter() {
      @Override
      public Converter getConverter(int fieldIndex) {
        throw new IllegalArgumentException("No field " + fieldIndex);
      }

      @Override
      public void start() {}

      @Override
      public void end() {}
    };
    private int materializationCalls;

    @Override
    public String getCurrentRecord() {
      materializationCalls++;
      return "materialized record";
    }

    @Override
    public GroupConverter getRootConverter() {
      return root;
    }
  }
}
