  @Test
  void baseConverterRejectsBothSpecializedViewsWithClassNames() {
    Converter converter = new BareConverter();

    assertFalse(converter.isPrimitive());
    ClassCastException primitiveFailure =
        assertThrows(ClassCastException.class, converter::asPrimitiveConverter);
    ClassCastException groupFailure = assertThrows(ClassCastException.class, converter::asGroupConverter);

    assertTrue(primitiveFailure.getMessage().contains("Expected instance of primitive converter"));
    assertTrue(primitiveFailure.getMessage().contains(BareConverter.class.getName()));
    assertTrue(groupFailure.getMessage().contains("Expected instance of group converter"));
    assertTrue(groupFailure.getMessage().contains(BareConverter.class.getName()));
  }

  @Test
  void primitiveConverterAdvertisesOnlyThePrimitiveView() {
    PrimitiveConverter converter = new StubPrimitiveConverter();

    assertTrue(converter.isPrimitive());
    assertSame(converter, converter.asPrimitiveConverter());
    assertThrows(ClassCastException.class, converter::asGroupConverter);
  }

  @Test
  void groupConverterAdvertisesOnlyTheGroupView() {
    GroupConverter converter = new StubGroupConverter(new Converter[0]);

    assertFalse(converter.isPrimitive());
    assertSame(converter, converter.asGroupConverter());
    assertThrows(ClassCastException.class, converter::asPrimitiveConverter);
  }

  @Test
  void groupConverterDelegatesFieldLookupAndLifecycleCallbacks() {
    StubPrimitiveConverter first = new StubPrimitiveConverter();
    StubGroupConverter nested = new StubGroupConverter(new Converter[0]);
    StubGroupConverter root = new StubGroupConverter(new Converter[] {first, nested});

    assertSame(first, root.getConverter(0));
    assertSame(nested, root.getConverter(1));

    root.start();
    root.end();

    assertEquals(1, root.startCalls);
    assertEquals(1, root.endCalls);
  }

  @Test
  void primitiveDefaultsReportUnsupportedDictionaryAndValueCallbacks() {
    StubPrimitiveConverter converter = new StubPrimitiveConverter();
    String className = converter.getClass().getName();

    assertFalse(converter.hasDictionarySupport());

    assertUnsupported(className, () -> converter.setDictionary(null));
    assertUnsupported(className, () -> converter.addValueFromDictionary(0));
    assertUnsupported(className, () -> converter.addBinary(Binary.EMPTY));
    assertUnsupported(className, () -> converter.addBoolean(true));
    assertUnsupported(className, () -> converter.addDouble(1.0));
    assertUnsupported(className, () -> converter.addFloat(1.0f));
    assertUnsupported(className, () -> converter.addInt(1));
    assertUnsupported(className, () -> converter.addLong(1L));
  }

  private static void assertUnsupported(String expectedClassName, Runnable callback) {
    UnsupportedOperationException exception =
        assertThrows(UnsupportedOperationException.class, callback::run);
    assertEquals(expectedClassName, exception.getMessage());
  }

  private static final class BareConverter extends Converter {
    @Override
    public boolean isPrimitive() {
      return false;
    }
  }

  private static final class StubPrimitiveConverter extends PrimitiveConverter {}

  private static final class StubGroupConverter extends GroupConverter {
    private final Converter[] converters;
    private int startCalls;
    private int endCalls;

    private StubGroupConverter(Converter[] converters) {
      this.converters = converters;
    }

    @Override
    public Converter getConverter(int fieldIndex) {
      return converters[fieldIndex];
    }

    @Override
    public void start() {
      startCalls++;
    }

    @Override
    public void end() {
      endCalls++;
    }
  }
}
