package org.apache.parquet.io.api;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.Test;

class BinaryTest {

  @Test
  void emptyConstantHasNoBytesAndCopiesToItself() {
    assertThat(Binary.EMPTY.length()).isZero();
    assertThat(Binary.EMPTY.getBytes()).isEmpty();
    assertThat(Binary.EMPTY.getBytesUnsafe()).isEmpty();
    assertThat(Binary.EMPTY.isBackingBytesReused()).isFalse();
    assertThat(Binary.EMPTY).asString().isEqualTo("Binary{0 constant bytes, []}");
    assertThat(Binary.EMPTY.copy()).isSameAs(Binary.EMPTY);
  }

  @Test
  void arrayFactoriesExposeBackingReuseAndDefensiveCopies() {
    byte[] bytes = {1, 2, 3};

    Binary constant = Binary.fromConstantByteArray(bytes);
    Binary reused = Binary.fromReusedByteArray(bytes);

    assertThat(constant.isBackingBytesReused()).isFalse();
    assertThat(reused.isBackingBytesReused()).isTrue();
    assertThat(constant.length()).isEqualTo(3);
    assertThat(constant.getBytes()).containsExactly(1, 2, 3);
    assertThat(constant.getBytesUnsafe()).isSameAs(bytes);
    assertThat(reused.getBytesUnsafe()).isSameAs(bytes);

    byte[] defensiveCopy = constant.getBytes();
    defensiveCopy[0] = 99;
    assertThat(constant.getBytes()).containsExactly(1, 2, 3);
  }

  @Test
  void sliceUsesRelativeOffsetsAndPreservesReusePolicy() {
    byte[] source = {10, 11, 12, 13, 14};

    Binary constantSlice = Binary.fromConstantByteArray(source, 1, 3);
    assertThat(constantSlice.isBackingBytesReused()).isFalse();
    assertThat(constantSlice.length()).isEqualTo(3);
    assertThat(constantSlice.getBytes()).containsExactly(11, 12, 13);

    Binary nestedConstantSlice = constantSlice.slice(1, 2);
    assertThat(nestedConstantSlice.isBackingBytesReused()).isFalse();
    assertThat(nestedConstantSlice.getBytes()).containsExactly(12, 13);

    Binary reusedSlice = Binary.fromReusedByteArray(source, 1, 2);
    assertThat(reusedSlice.isBackingBytesReused()).isTrue();
    Binary nestedReusedSlice = reusedSlice.slice(1, 1);
    assertThat(nestedReusedSlice.isBackingBytesReused()).isTrue();
    assertThat(nestedReusedSlice.getBytes()).containsExactly(12);

    source[2] = 42;
    assertThat(nestedReusedSlice.getBytes()).containsExactly(42);
  }

  @Test
  void reusedBinaryCanBeCopiedIntoAnImmutableSnapshot() {
    byte[] source = {4, 5, 6};
    Binary reused = Binary.fromReusedByteArray(source);

    Binary copy = reused.copy();

    assertThat(copy).isNotSameAs(reused);
    assertThat(copy.isBackingBytesReused()).isFalse();
    assertThat(copy.getBytes()).containsExactly(4, 5, 6);
    source[0] = 99;
    assertThat(copy.getBytes()).containsExactly(4, 5, 6);
  }

  @Test
  void constantArrayBinaryReturnsItselfWhenCopied() {
    Binary constant = Binary.fromConstantByteArray(new byte[] {7, 8});
    Binary string = Binary.fromString("constant");

    assertThat(constant.copy()).isSameAs(constant);
    assertThat(string.copy()).isSameAs(string);
  }

  @Test
  void equalityAndHashCodeIgnoreRepresentationAndUseBinaryContent() {
    ByteBuffer direct = ByteBuffer.allocateDirect(3);
    direct.put(new byte[] {1, 2, 3}).flip();

    Binary fromArray = Binary.fromConstantByteArray(new byte[] {1, 2, 3});
    Binary fromOffset = Binary.fromConstantByteArray(new byte[] {9, 1, 2, 3, 9}, 1, 3);
    Binary fromHeapBuffer = Binary.fromConstantByteBuffer(ByteBuffer.wrap(new byte[] {1, 2, 3}));
    Binary fromDirectBuffer = Binary.fromConstantByteBuffer(direct);

    for (Binary left : new Binary[] {fromArray, fromOffset, fromHeapBuffer, fromDirectBuffer}) {
      for (Binary right : new Binary[] {fromArray, fromOffset, fromHeapBuffer, fromDirectBuffer}) {
        assertThat(left).isEqualTo(right).hasSameHashCodeAs(right);
      }
    }

    assertThat(fromArray).isNotEqualTo(Binary.fromConstantByteArray(new byte[] {1, 2, 3, 4}));
    assertThat(fromArray).isNotEqualTo(Binary.fromConstantByteArray(new byte[] {1, 2, 4}));
    assertThat(fromArray).isNotEqualTo("not a binary");
    assertThat(fromArray).isNotEqualTo((Object) null);
  }

