    assertThat(highBit).isGreaterThan(lower);
    assertThat(Binary.lexicographicCompare(lower, lower)).isZero();
    assertThat(Binary.lexicographicCompare(lower, highBit)).isNegative();
    assertThat(Binary.lexicographicCompare(highBit, lower)).isPositive();
  }

  @Test
