    Binary longer = Binary.fromConstantByteArray(new byte[] {1, 2, 0});
    Binary different = Binary.fromConstantByteArray(new byte[] {1, 3});

    assertThat(prefix).isLessThan(longer);
    assertThat(longer).isGreaterThan(prefix);
    assertThat(prefix).isLessThan(different);
    assertThat(prefix).isEqualByComparingTo(Binary.fromConstantByteArray(new byte[] {1, 2}));
  }

  @Test
