        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("length must be 2");
    assertThatThrownBy(() -> Binary.fromConstantByteArray(new byte[] {1, 2, 3})
            .get2BytesLittleEndian())
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessage("length must be 2");
  }

  @Test
