    Binary whole = Binary.fromByteArray(source);
    Binary range = Binary.fromByteArray(source, 1, 2);

    assertThat(whole.isBackingBytesReused()).isTrue();
    assertThat(range.isBackingBytesReused()).isTrue();
    assertThat(whole.getBytes()).containsExactly(0, 1, 2, 3);
    assertThat(range.getBytes()).containsExactly(1, 2);

    source[1] = 42;
    assertThat(whole.getBytes()).containsExactly(0, 42, 2, 3);
    assertThat(range.getBytes()).containsExactly(42, 2);
  }

  @Test
  @SuppressWarnings("deprecation")
  void deprecatedByteBufferFactoryRetainsItsHistoricalReuseBehavior() {
    ByteBuffer source = ByteBuffer.wrap(new byte[] {1, 2, 3});
