    assertThat(binary.isBackingBytesReused()).isTrue();
    assertThat(binary.getBytes()).containsExactly(1, 2, 3);
    source.put(0, (byte) 9);
    assertThat(binary.getBytes()).containsExactly(9, 2, 3);
  }

  @Test
  void reusedByteBufferReflectsChangesToItsHeapBackingStore() {
    ByteBuffer source = ByteBuffer.wrap(new byte[] {4, 5, 6});
    Binary binary = Binary.fromReusedByteBuffer(source);

    assertThat(binary.isBackingBytesReused()).isTrue();
    source.put(1, (byte) 50);
    assertThat(binary.getBytes()).containsExactly(4, 50, 6);
  }

  @Test
  void explicitReusedByteBufferRangeUsesAbsoluteOffsets() {
    ByteBuffer source = ByteBuffer.wrap(new byte[] {7, 8, 9, 10});
    Binary binary = Binary.fromReusedByteBuffer(source, 1, 2);

    assertThat(binary.isBackingBytesReused()).isTrue();
    assertThat(binary.getBytes()).containsExactly(8, 9);
    source.put(1, (byte) 80);
    assertThat(binary.getBytes()).containsExactly(80, 9);
  }

  @Test
  void byteBufferBackedBinaryCanBeSliced() {
    ByteBuffer direct = ByteBuffer.allocateDirect(5);
    direct.put(new byte[] {9, 1, 2, 3, 9}).flip();
    Binary binary = Binary.fromConstantByteBuffer(direct, 1, 3);

    Binary slice = binary.slice(1, 2);

    assertThat(slice.length()).isEqualTo(2);
    assertThat(slice.getBytes()).containsExactly(2, 3);
  }

  @Test
  void comparisonWorksAcrossArrayAndBufferRepresentations() {
    Binary array = Binary.fromConstantByteArray(new byte[] {0x7F});
    ByteBuffer direct = ByteBuffer.allocateDirect(1);
    direct.put((byte) 0x80).flip();
    Binary buffer = Binary.fromConstantByteBuffer(direct);

    assertThat(Binary.lexicographicCompare(array, buffer)).isNegative();
    assertThat(Binary.lexicographicCompare(buffer, array)).isPositive();
    assertThat(array).isLessThan(buffer);
    assertThat(buffer).isGreaterThan(array);
  }
