package org.apache.parquet.io.api;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataOutput;
import java.io.DataOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.nio.ByteBuffer;
import java.nio.charset.CharacterCodingException;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.List;
import org.apache.parquet.io.ParquetEncodingException;
import org.junit.jupiter.api.Test;

class BinaryEncodingAndIoTest {

  @Test
  void stringAndCharSequenceFactoriesEncodeStrictUtf8() {
    String value = "héllo \uD83D\uDE00";
    byte[] expected = value.getBytes(StandardCharsets.UTF_8);

    Binary fromString = Binary.fromString(value);
    Binary fromCharSequence = Binary.fromCharSequence(new StringBuilder(value));

    for (Binary binary : Arrays.asList(fromString, fromCharSequence)) {
      assertThat(binary.isBackingBytesReused()).isFalse();
      assertThat(binary.toStringUsingUTF8()).isEqualTo(value);
      assertThat(binary).asString().isEqualTo("Binary{\"" + value + "\"}");
      assertThat(binary.getBytes()).containsExactly(expected);
    }
  }

  @Test
  void malformedCharSequenceIsReportedAsAnEncodingFailure() {
    assertThatThrownBy(() -> Binary.fromCharSequence("\uD800"))
        .isInstanceOf(ParquetEncodingException.class)
        .hasMessage("Failed to encode CharSequence as UTF-8.")
        .hasCauseInstanceOf(CharacterCodingException.class);
  }

  @Test
  void arrayBackedToStringIdentifiesReuseAndExactBytes() {
    Binary constant = Binary.fromConstantByteArray(new byte[] {1, 2});
    Binary reused = Binary.fromReusedByteArray(new byte[] {(byte) 0xFF, 0});

    assertThat(constant).asString().isEqualTo("Binary{2 constant bytes, [1, 2]}");
    assertThat(reused).asString().isEqualTo("Binary{2 reused bytes, [-1, 0]}");
  }

  @Test
  void writeToOutputStreamWritesOnlyTheSelectedBytes() throws Exception {
    ByteBuffer direct = ByteBuffer.allocateDirect(5);
    direct.put(new byte[] {9, 1, 2, 3, 9}).flip();
    Binary binary = Binary.fromConstantByteBuffer(direct, 1, 3);

    ByteArrayOutputStream output = new ByteArrayOutputStream();
    binary.writeTo(output);

    assertThat(output.toByteArray()).containsExactly(1, 2, 3);
  }

  @Test
  void writeToDataOutputWritesOnlyTheSelectedBytes() throws Exception {
    Binary binary = Binary.fromConstantByteArray(new byte[] {8, 4, 5, 6, 8}, 1, 3);
    ByteArrayOutputStream bytes = new ByteArrayOutputStream();

    try (DataOutputStream output = new DataOutputStream(bytes)) {
      binary.writeTo((DataOutput) output);
    }

    assertThat(bytes.toByteArray()).containsExactly(4, 5, 6);
  }

  @Test
  void directByteBufferBinaryIsCopiedToHeapStorage() {
    ByteBuffer direct = ByteBuffer.allocateDirect(3);
    direct.put(new byte[] {11, 12, 13}).flip();
    Binary binary = Binary.fromConstantByteBuffer(direct);

    Binary copy = binary.copy();

    assertThat(copy).isNotSameAs(binary).isEqualTo(binary).hasSameHashCodeAs(binary);
    assertThat(copy.isBackingBytesReused()).isFalse();
    assertThat(copy.getBytes()).containsExactly(11, 12, 13);

    direct.put(0, (byte) 99);
    assertThat(copy.getBytes()).containsExactly(11, 12, 13);
  }

  @Test
  void constantHeapBufferBinaryReturnsItselfWhenCopied() {
    Binary binary = Binary.fromConstantByteBuffer(ByteBuffer.wrap(new byte[] {1, 2}));
    assertThat(binary.copy()).isSameAs(binary).isEqualTo(binary);
  }

  @Test
  void binaryValuesSurviveJavaSerializationAcrossRepresentations() throws Exception {
    byte[] data = "serializable".getBytes(StandardCharsets.UTF_8);
    ByteBuffer direct = ByteBuffer.allocateDirect(data.length);
    direct.put(data).flip();

    List<Binary> values = Arrays.asList(
        Binary.fromConstantByteArray(data),
        Binary.fromReusedByteArray(data),
        Binary.fromConstantByteArray(new byte[] {9, 1, 2, 3, 9}, 1, 3),
        Binary.fromString("hé"),
        Binary.fromCharSequence(new StringBuilder("hé")),
        Binary.fromConstantByteBuffer(ByteBuffer.wrap(data)),
        Binary.fromConstantByteBuffer(direct));

    for (Binary binary : values) {
      Binary restored = roundTrip(binary);
      assertThat(restored).isNotSameAs(binary).isEqualTo(binary).hasSameHashCodeAs(binary);
      assertThat(restored.getBytes()).containsExactly(binary.getBytes());
    }
  }

  private static Binary roundTrip(Binary binary) throws Exception {
    ByteArrayOutputStream bytes = new ByteArrayOutputStream();
    try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
      output.writeObject(binary);
    }
    try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
      return (Binary) input.readObject();
    }
  }

  @Test
  void twoByteLittleEndianAccessorUsesUnsignedByteShifts() {
    Binary binary = Binary.fromConstantByteBuffer(ByteBuffer.wrap(new byte[] {0x34, 0x12}));
    assertThat(binary.get2BytesLittleEndian()).isEqualTo((short) 0x1234);
    assertThat(binary.length()).isEqualTo(2);
  }
}
