package org.apache.parquet.io.api;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class RecordConsumerTest {

  @Test
  void supportsTheDocumentedNestedRecordWorkflow() {
    RecordingRecordConsumer consumer = new RecordingRecordConsumer();

    consumer.startMessage();
    consumer.startField("A", 0);
    consumer.addInteger(1);
    consumer.addInteger(2);
    consumer.endField("A", 0);
    consumer.startField("B", 1);
    consumer.startGroup();
    consumer.startField("C", 0);
    consumer.addInteger(3);
    consumer.endField("C", 0);
    consumer.endGroup();
    consumer.endField("B", 1);
    consumer.endMessage();

    assertThat(consumer.events)
        .containsExactly(
            "startMessage",
            "startField:A@0",
            "integer:1",
            "integer:2",
            "endField:A@0",
            "startField:B@1",
            "startGroup",
            "startField:C@0",
            "integer:3",
            "endField:C@0",
            "endGroup",
            "endField:B@1",
            "endMessage");
  }

  @Test
  void dispatchesEachValueTypeToItsCallback() {
    RecordingRecordConsumer consumer = new RecordingRecordConsumer();
    consumer.startField("values", 3);
    consumer.addLong(9L);
    consumer.addBoolean(true);
    consumer.addBinary(Binary.fromString("abc"));
    consumer.addFloat(1.25f);
    consumer.addDouble(2.5d);
    consumer.endField("values", 3);

    assertThat(consumer.events)
        .containsExactly(
            "startField:values@3",
            "long:9",
            "boolean:true",
            "binary:abc",
            "float:1.25",
            "double:2.5",
            "endField:values@3");
  }

  @Test
  void flushIsANoOpByDefault() {
    RecordingRecordConsumer consumer = new RecordingRecordConsumer();

    consumer.flush();

    assertThat(consumer.events).isEmpty();
  }

  private static final class RecordingRecordConsumer extends RecordConsumer {
    private final List<String> events = new ArrayList<>();

    @Override
    public void startMessage() {
      events.add("startMessage");
    }

    @Override
    public void endMessage() {
      events.add("endMessage");
    }

