import java.util.Arrays;
import java.util.stream.IntStream;
import java.util.stream.Stream;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

class IntPackerTest {

  private static final int INPUT_OFFSET = 4;
  private static final int PACKED_OFFSET = 3;
  private static final int OUTPUT_OFFSET = 5;
  private static final int SENTINEL = 0x12345678;

  static Stream<Arguments> packerAndWidth() {
    return Arrays.stream(Packer.values())
        .flatMap(packer -> IntStream.rangeClosed(0, 31).mapToObj(width -> Arguments.of(packer, width)));
  }

  @ParameterizedTest(name = "{0}, width={1}")
  @MethodSource("packerAndWidth")
  void packsAndUnpacksThirtyTwoIntsAtNonZeroOffsets(Packer mode, int width) {
    IntPacker packer = mode.newIntPacker(width);
    assertEquals(width, packer.getBitWidth());

    int[] values = values(width);
    int[] input = new int[32 + INPUT_OFFSET + 3];
    Arrays.fill(input, SENTINEL);
    System.arraycopy(values, 0, input, INPUT_OFFSET, values.length);

    int[] packed = new int[width + PACKED_OFFSET + 2];
    Arrays.fill(packed, SENTINEL);
    packer.pack32Values(input, INPUT_OFFSET, packed, PACKED_OFFSET);

    for (int i = 0; i < PACKED_OFFSET; i++) {
      assertEquals(SENTINEL, packed[i], "packed prefix at " + i);
    }
    for (int i = PACKED_OFFSET + width; i < packed.length; i++) {
      assertEquals(SENTINEL, packed[i], "packed suffix at " + i);
    }

    int[] decoded = new int[32 + OUTPUT_OFFSET + 3];
    Arrays.fill(decoded, SENTINEL);
    packer.unpack32Values(packed, PACKED_OFFSET, decoded, OUTPUT_OFFSET);

    for (int i = 0; i < OUTPUT_OFFSET; i++) {
      assertEquals(SENTINEL, decoded[i], "decoded prefix at " + i);
    }
    for (int i = 0; i < values.length; i++) {
      assertEquals(values[i], decoded[OUTPUT_OFFSET + i], "decoded value at " + i);
    }
    for (int i = OUTPUT_OFFSET + values.length; i < decoded.length; i++) {
      assertEquals(SENTINEL, decoded[i], "decoded suffix at " + i);
    }
  }

  private static int[] values(int width) {
    int mask = width == 32 ? -1 : (1 << width) - 1;
    int[] values = new int[32];
    for (int i = 0; i < values.length; i++) {
      values[i] = ((i * 0x9E3779B9) ^ (i >>> 1)) & mask;
    }
    values[0] = 0;
    values[1] = mask;
    values[2] = 1;
    values[3] = mask >>> 1;
    return values;
  }
}
