package org.apache.parquet.column.values.bitpacking;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.ByteBuffer;
import java.util.Arrays;
import java.util.stream.IntStream;
import java.util.stream.Stream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

class BytePackerTest {

  private static final byte BYTE_SENTINEL = 0x5A;
  private static final int INT_SENTINEL = 0x12345678;
  private static final int INPUT_OFFSET = 5;

  static Stream<Arguments> packerAndWidth() {
    return Arrays.stream(Packer.values())
        .flatMap(packer -> IntStream.rangeClosed(0, 32).mapToObj(width -> Arguments.of(packer, width)));
  }

  @ParameterizedTest(name = "{0}, width={1}")
  @MethodSource("packerAndWidth")
  void pack8AndUnpack8RoundTripAtNonZeroOffsets(Packer mode, int width) {
    BytePacker packer = mode.newBytePacker(width);
    assertEquals(width, packer.getBitWidth());

    int[] values = values(8, width);
    int[] input = sentinelIntInput(8, values);
    byte[] packed = new byte[width + 7];
    Arrays.fill(packed, BYTE_SENTINEL);

    packer.pack8Values(input, INPUT_OFFSET, packed, 3);
    assertByteRange(packed, 0, 3);
    assertByteRange(packed, 3 + width, packed.length);

    int[] fromBytes = sentinelIntOutput(8);
    packer.unpack8Values(packed, 3, fromBytes, 4);
    assertDecoded(fromBytes, 4, values, width);

    int[] fromBuffer = sentinelIntOutput(8);
    packer.unpack8Values(ByteBuffer.wrap(packed), 3, fromBuffer, 4);
    assertArrayEquals(fromBytes, fromBuffer);
  }

  @ParameterizedTest(name = "{0}, width={1}")
  @MethodSource("packerAndWidth")
  void pack32AndUnpack32RoundTripAtNonZeroOffsets(Packer mode, int width) {
    BytePacker packer = mode.newBytePacker(width);
    int[] values = values(32, width);
    int[] input = sentinelIntInput(32, values);
    byte[] packed = new byte[width * 4 + 9];
    Arrays.fill(packed, BYTE_SENTINEL);

    packer.pack32Values(input, INPUT_OFFSET, packed, 2);
    assertByteRange(packed, 0, 2);
    assertByteRange(packed, 2 + width * 4, packed.length);

    int[] fromBytes = sentinelIntOutput(32);
    packer.unpack32Values(packed, 2, fromBytes, 6);
    assertDecoded(fromBytes, 6, values, width);

    int[] fromBuffer = sentinelIntOutput(32);
    packer.unpack32Values(ByteBuffer.wrap(packed), 2, fromBuffer, 6);
    assertArrayEquals(fromBytes, fromBuffer);
  }

  @ParameterizedTest(name = "{0}, width={1}")
  @MethodSource("packerAndWidth")
  void pack32ProducesTheSameBytesAsFourPack8Calls(Packer mode, int width) {
    BytePacker packer = mode.newBytePacker(width);
    int[] values = values(32, width);
    int[] input = sentinelIntInput(32, values);

    byte[] byGroups = new byte[width * 4 + 4];
    Arrays.fill(byGroups, BYTE_SENTINEL);
    for (int group = 0; group < 4; group++) {
      packer.pack8Values(input, INPUT_OFFSET + group * 8, byGroups, 2 + group * width);
    }

    byte[] bulk = new byte[width * 4 + 4];
    Arrays.fill(bulk, BYTE_SENTINEL);
    packer.pack32Values(input, INPUT_OFFSET, bulk, 2);

    assertArrayEquals(byGroups, bulk);
  }

  @Test
  void oneBitPackingUsesTheConfiguredByteOrder() {
    int[] values = {1, 0, 1, 0, 1, 0, 1, 0};
    byte[] bigEndian = new byte[1];
    byte[] littleEndian = new byte[1];

    Packer.BIG_ENDIAN.newBytePacker(1).pack8Values(values, 0, bigEndian, 0);
    Packer.LITTLE_ENDIAN.newBytePacker(1).pack8Values(values, 0, littleEndian, 0);

    assertEquals((byte) 0xAA, bigEndian[0]);
    assertEquals((byte) 0x55, littleEndian[0]);

    int[] decoded = new int[8];
    Packer.LITTLE_ENDIAN.newBytePacker(1).unpack8Values(littleEndian, 0, decoded, 0);
    assertArrayEquals(values, decoded);
  }

  @Test
  void optionalVectorApisReportThatTheyAreUnsupportedByDefault() {
    BytePacker packer = Packer.BIG_ENDIAN.newBytePacker(3);
    assertThrows(RuntimeException.class, packer::getUnpackCount);
    assertThrows(
        RuntimeException.class,
        () -> packer.unpackValuesUsingVector(new byte[3], 0, new int[8], 0));
    assertThrows(
        RuntimeException.class,
        () -> packer.unpackValuesUsingVector(ByteBuffer.wrap(new byte[3]), 0, new int[8], 0));
  }

  private static int[] values(int count, int width) {
    int mask = width == 32 ? -1 : (1 << width) - 1;
    int[] values = new int[count];
    for (int i = 0; i < count; i++) {
      values[i] = ((i * 0x9E3779B9) ^ (i >>> 1)) & mask;
    }
    if (count > 0) {
      values[0] = 0;
    }
    if (count > 1) {
      values[1] = mask;
    }
    if (count > 2) {
      values[2] = 1;
    }
    if (count > 3) {
      values[3] = mask >>> 1;
    }
    return values;
  }

  private static int[] sentinelIntInput(int count, int[] values) {
    int[] input = new int[count + INPUT_OFFSET + 3];
    Arrays.fill(input, INT_SENTINEL);
    System.arraycopy(values, 0, input, INPUT_OFFSET, values.length);
    return input;
  }

  private static int[] sentinelIntOutput(int count) {
    int[] output = new int[count + 10];
    Arrays.fill(output, INT_SENTINEL);
    return output;
  }

  private static void assertDecoded(int[] actual, int offset, int[] expected, int width) {
    for (int i = 0; i < offset; i++) {
      assertEquals(INT_SENTINEL, actual[i], "decoded prefix at " + i);
    }
    for (int i = 0; i < expected.length; i++) {
      if (width == 0) {
        assertEquals(INT_SENTINEL, actual[offset + i], "width-zero unpack must not write at " + i);
      } else {
        assertEquals(expected[i], actual[offset + i], "decoded value at " + i);
      }
    }
    for (int i = offset + expected.length; i < actual.length; i++) {
      assertEquals(INT_SENTINEL, actual[i], "decoded suffix at " + i);
    }
  }

  private static void assertByteRange(byte[] bytes, int from, int to) {
    for (int i = from; i < to; i++) {
      assertEquals(BYTE_SENTINEL, bytes[i], "unexpected byte at " + i);
    }
  }
}
