class BitPackingTest {

  static Stream<Arguments> roundTripCases() {
    int[] counts = {0, 1, 2, 3, 4, 5, 7, 8, 9, 15, 16, 17, 31, 32, 33};
    return IntStream.rangeClosed(0, 8)
        .boxed()
        .flatMap(width -> IntStream.of(counts).mapToObj(count -> Arguments.of(width, count)));
  }

  @ParameterizedTest(name = "width={0}, values={1}")
  @MethodSource("roundTripCases")
  void writesAndReadsValuesAcrossAllSupportedWidths(int width, int count) throws IOException {
    int[] values = values(width, count);
    byte[] encoded = encode(width, values);

    assertEquals((width * count + 7) / 8, encoded.length, "finish must emit only padded complete bytes");

    BitPackingReader reader =
        BitPacking.createBitPackingReader(width, new ByteArrayInputStream(encoded), count);
    for (int i = 0; i < count; i++) {
      assertEquals(values[i], reader.read(), "value at index " + i);
    }
  }

  @Test
  void zeroWidthWriterEmitsNothingAndReaderAlwaysReturnsZero() throws IOException {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    BitPackingWriter writer = BitPacking.getBitPackingWriter(0, out);
    writer.write(0);
    writer.write(Integer.MAX_VALUE);
    writer.write(-1);
    writer.finish();

    assertArrayEquals(new byte[0], out.toByteArray());
    BitPackingReader reader =
        BitPacking.createBitPackingReader(0, new ByteArrayInputStream(out.toByteArray()), 5);
    for (int i = 0; i < 5; i++) {
      assertEquals(0, reader.read());
    }
  }

  @Test
  void writesOneBitValuesMsbFirstAndZeroPadsTheLastByte() throws IOException {
    assertArrayEquals(new byte[] {(byte) 0xA0}, encode(1, new int[] {1, 0, 1}));
    assertArrayEquals(new byte[] {(byte) 0xAA}, encode(1, new int[] {1, 0, 1, 0, 1, 0, 1, 0}));
  }

  @Test
  void writesPartialThreeBitGroupWithTrailingZeroBits() throws IOException {
    byte[] encoded = encode(3, new int[] {5});
    assertArrayEquals(new byte[] {(byte) 0xA0}, encoded);

    BitPackingReader reader =
        BitPacking.createBitPackingReader(3, new ByteArrayInputStream(encoded), 1);
    assertEquals(5, reader.read());
  }

  @Test
  void writesPartialFiveBitGroupWithTrailingZeroBits() throws IOException {
    byte[] encoded = encode(5, new int[] {31, 1});
    assertArrayEquals(new byte[] {(byte) 0xF8, (byte) 0x40}, encoded);

    BitPackingReader reader =
        BitPacking.createBitPackingReader(5, new ByteArrayInputStream(encoded), 2);
    assertEquals(31, reader.read());
    assertEquals(1, reader.read());
  }

  @Test
  void writesPartialSevenBitGroupWithTrailingZeroBits() throws IOException {
    byte[] encoded = encode(7, new int[] {127});
    assertArrayEquals(new byte[] {(byte) 0xFE}, encoded);

    BitPackingReader reader =
        BitPacking.createBitPackingReader(7, new ByteArrayInputStream(encoded), 1);
    assertEquals(127, reader.read());
  }

