  @ParameterizedTest(name = "{0}, width={1}")
  @MethodSource("packerAndWidth")
  void writesCompleteAndPartialGroups(Packer mode, int width) throws IOException {
    int[] counts = {0, 1, 2, 7, 8, 9, 16, 31, 32};
    for (int count : counts) {
