package org.apache.parquet.hadoop.metadata;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.EnumSet;
import java.util.HashSet;
import java.util.Set;
import org.apache.parquet.column.Encoding;
import org.apache.parquet.schema.PrimitiveType;
import org.apache.parquet.schema.PrimitiveType.PrimitiveTypeName;
import org.apache.parquet.schema.Types;
import org.junit.jupiter.api.Test;

class ColumnChunkPropertiesTest {

  private static final ColumnPath PATH = ColumnPath.fromDotString("a.b");
  private static final PrimitiveType TYPE = Types.optional(PrimitiveTypeName.INT32).named("b");
  private static final Set<Encoding> ENCODINGS = EnumSet.of(Encoding.PLAIN, Encoding.RLE);

  private static ColumnChunkProperties properties(CompressionCodecName codec) {
    return ColumnChunkProperties.get(PATH, TYPE, codec, ENCODINGS);
  }

  @Test
  void exposesAllProperties() {
    ColumnChunkProperties properties = properties(CompressionCodecName.SNAPPY);

    assertThat(properties.getCodec()).isEqualTo(CompressionCodecName.SNAPPY);
    assertThat(properties.getPath()).isEqualTo(PATH);
    assertThat(properties.getPrimitiveType()).isSameAs(TYPE);
    assertThat(properties.getEncodings()).containsExactlyInAnyOrder(Encoding.PLAIN, Encoding.RLE);
  }

  @Test
  void deprecatedTypeAccessorReturnsThePrimitiveTypeName() {
    ColumnChunkProperties properties = properties(CompressionCodecName.GZIP);

    assertThat(properties.getType()).isEqualTo(PrimitiveTypeName.INT32);
  }

  @Test
  void equalPropertiesAreCanonicalized() {
    Set<Encoding> reordered = new HashSet<>(EnumSet.of(Encoding.RLE, Encoding.PLAIN));

    ColumnChunkProperties first = ColumnChunkProperties.get(PATH, TYPE, CompressionCodecName.SNAPPY, ENCODINGS);
    ColumnChunkProperties second = ColumnChunkProperties.get(PATH, TYPE, CompressionCodecName.SNAPPY, reordered);

    assertThat(second).isSameAs(first);
    assertThat(second).isEqualTo(first);
    assertThat(second.hashCode()).isEqualTo(first.hashCode());
  }

  @Test
  void propertiesDifferingInCodecAreNotCanonicalizedTogether() {
    ColumnChunkProperties snappy = properties(CompressionCodecName.SNAPPY);
    ColumnChunkProperties gzip = properties(CompressionCodecName.GZIP);

    assertThat(gzip).isNotSameAs(snappy);
    assertThat(gzip).isNotEqualTo(snappy);
  }

  @Test
  void propertiesDifferingInPathAreNotEqual() {
    ColumnChunkProperties first = ColumnChunkProperties.get(
        ColumnPath.fromDotString("a.b"), TYPE, CompressionCodecName.SNAPPY, ENCODINGS);
    ColumnChunkProperties second = ColumnChunkProperties.get(
        ColumnPath.fromDotString("a.c"), TYPE, CompressionCodecName.SNAPPY, ENCODINGS);

    assertThat(second).isNotEqualTo(first);
  }

  @Test
  void propertiesDifferingInTypeAreNotEqual() {
    ColumnChunkProperties optional = properties(CompressionCodecName.SNAPPY);
    ColumnChunkProperties required = ColumnChunkProperties.get(
        PATH, Types.required(PrimitiveTypeName.INT32).named("b"), CompressionCodecName.SNAPPY, ENCODINGS);

    assertThat(required).isNotEqualTo(optional);
  }

  @Test
  void propertiesDifferingInEncodingsAreNotEqual() {
    ColumnChunkProperties first = properties(CompressionCodecName.SNAPPY);
    ColumnChunkProperties second =
        ColumnChunkProperties.get(PATH, TYPE, CompressionCodecName.SNAPPY, EnumSet.of(Encoding.PLAIN));

    assertThat(second).isNotEqualTo(first);
  }

  @Test
  void equalsIsFalseForOtherKindsOfObjects() {
    ColumnChunkProperties properties = properties(CompressionCodecName.SNAPPY);

    assertThat(properties).isNotEqualTo("SNAPPY");
    assertThat(properties).isNotEqualTo(null);
  }

  @Test
  void toStringIncludesTheMainProperties() {
    ColumnChunkProperties properties = properties(CompressionCodecName.UNCOMPRESSED);

    assertThat(properties.toString())
        .startsWith("UNCOMPRESSED ")
        .contains("[a, b]")
        .contains("int32 b")
        .contains("PLAIN");
  }

  @Test
  void deprecatedFactoryBuildsAnOptionalType() {
    ColumnChunkProperties properties =
        ColumnChunkProperties.get(PATH, PrimitiveTypeName.INT64, CompressionCodecName.SNAPPY, ENCODINGS);

    assertThat(properties.getType()).isEqualTo(PrimitiveTypeName.INT64);
    assertThat(properties.getPrimitiveType().getPrimitiveTypeName()).isEqualTo(PrimitiveTypeName.INT64);
    assertThat(properties.getPrimitiveType().isRepetition(PrimitiveType.Repetition.OPTIONAL))
        .isTrue();
  }

  @Test
  void deprecatedFactoryCanonicalizesEqualProperties() {
    ColumnChunkProperties first =
        ColumnChunkProperties.get(PATH, PrimitiveTypeName.INT64, CompressionCodecName.SNAPPY, ENCODINGS);
    ColumnChunkProperties second =
        ColumnChunkProperties.get(PATH, PrimitiveTypeName.INT64, CompressionCodecName.SNAPPY, ENCODINGS);

    assertThat(second).isSameAs(first);
  }
}
