import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.apache.parquet.column.Encoding;
import org.junit.jupiter.api.Test;

class EncodingListTest {

  @Test
  void equalEncodingListsAreCanonicalized() {
    EncodingList first = EncodingList.getEncodingList(Arrays.asList(Encoding.PLAIN, Encoding.RLE));
    EncodingList second = EncodingList.getEncodingList(Arrays.asList(Encoding.PLAIN, Encoding.RLE));

    assertThat(second).isSameAs(first);
  }

  @Test
  void encodingListsWithDifferentContentAreDistinct() {
    EncodingList first = EncodingList.getEncodingList(Arrays.asList(Encoding.PLAIN, Encoding.RLE));
    EncodingList second = EncodingList.getEncodingList(Arrays.asList(Encoding.RLE, Encoding.PLAIN));
    EncodingList third = EncodingList.getEncodingList(Collections.singletonList(Encoding.PLAIN));

    assertThat(first).isNotSameAs(second);
    assertThat(first).isNotEqualTo(second);
    assertThat(first).isNotEqualTo(third);
  }

  @Test
  void toListExposesTheEncodingsInOrder() {
    EncodingList list = EncodingList.getEncodingList(Arrays.asList(Encoding.PLAIN, Encoding.RLE, Encoding.BIT_PACKED));

    assertThat(list.toList()).containsExactly(Encoding.PLAIN, Encoding.RLE, Encoding.BIT_PACKED);
  }

  @Test
  void toListIsUnmodifiable() {
    EncodingList list = EncodingList.getEncodingList(Collections.singletonList(Encoding.PLAIN));
    List<Encoding> encodings = list.toList();

    assertThatThrownBy(() -> encodings.add(Encoding.RLE)).isInstanceOf(UnsupportedOperationException.class);
  }

  @Test
  void sizeAndIteratorMatchTheEncodings() {
    EncodingList list = EncodingList.getEncodingList(Arrays.asList(Encoding.PLAIN, Encoding.DELTA_BINARY_PACKED));

    assertThat(list.size()).isEqualTo(2);
    assertThat(list).toIterable().containsExactly(Encoding.PLAIN, Encoding.DELTA_BINARY_PACKED);
  }

  @Test
  void emptyEncodingListIsSupported() {
    EncodingList list = EncodingList.getEncodingList(Collections.emptyList());

    assertThat(list.size()).isZero();
    assertThat(list.toList()).isEmpty();
    assertThat(list.iterator()).isExhausted();
    assertThat(list).isEqualTo(EncodingList.getEncodingList(Collections.emptyList()));
  }

  @Test
  void equalsIsFalseForNonEncodingListValues() {
    EncodingList list = EncodingList.getEncodingList(Collections.singletonList(Encoding.PLAIN));

    assertThat(list).isNotEqualTo(Collections.singletonList(Encoding.PLAIN));
    assertThat(list).isNotEqualTo(null);
  }

