import org.junit.jupiter.api.Test;

class BlockMetaDataTest {

  private static final PrimitiveType TYPE = Types.optional(PrimitiveType.PrimitiveTypeName.INT32).named("value");

  private static ColumnChunkMetaData column(String dotPath, long firstDataPage, long dictionaryPage, long totalSize) {
    return ColumnChunkMetaData.get(
        ColumnPath.fromDotString(dotPath),
        TYPE,
        CompressionCodecName.SNAPPY,
        null,
        EnumSet.of(Encoding.PLAIN),
        Statistics.createStats(TYPE),
        firstDataPage,
        dictionaryPage,
        10L,
        totalSize,
        totalSize * 2,
        null,
        null);
  }

  @Test
  void newBlockHasNoColumnsAndDefaultValues() {
    BlockMetaData block = new BlockMetaData();

    assertThat(block.getColumns()).isEmpty();
    assertThat(block.getRowCount()).isZero();
    assertThat(block.getTotalByteSize()).isZero();
    assertThat(block.getPath()).isNull();
    assertThat(block.getRowIndexOffset()).isEqualTo(-1L);
    assertThat(block.getOrdinal()).isZero();
    assertThat(block.getCompressedSize()).isZero();
  }

  @Test
  void columnsAreExposedInInsertionOrder() {
    BlockMetaData block = new BlockMetaData();
    ColumnChunkMetaData first = column("a", 128L, 0L, 10L);
    ColumnChunkMetaData second = column("b", 256L, 0L, 20L);

    block.addColumn(first);
    block.addColumn(second);

    assertThat(block.getColumns()).containsExactly(first, second);
  }

  @Test
  void columnListCannotBeModifiedThroughTheGetter() {
    BlockMetaData block = new BlockMetaData();
    block.addColumn(column("a", 128L, 0L, 10L));
    List<ColumnChunkMetaData> columns = block.getColumns();

    assertThatThrownBy(() -> columns.add(column("b", 256L, 0L, 20L)))
        .isInstanceOf(UnsupportedOperationException.class);
  }

  @Test
  void startingPositionIsTheStartOfTheFirstColumn() {
    BlockMetaData block = new BlockMetaData();
    block.addColumn(column("a", 128L, 0L, 10L));
    block.addColumn(column("b", 1024L, 0L, 20L));

    assertThat(block.getStartingPos()).isEqualTo(128L);
  }

  @Test
  void startingPositionIncludesTheDictionaryPageOfTheFirstColumn() {
    BlockMetaData block = new BlockMetaData();
    block.addColumn(column("a", 128L, 32L, 10L));

    assertThat(block.getStartingPos()).isEqualTo(32L);
  }

  @Test
  void startingPositionOfABlockWithoutColumnsFails() {
    BlockMetaData block = new BlockMetaData();

    assertThatThrownBy(block::getStartingPos).isInstanceOf(IndexOutOfBoundsException.class);
  }

  @Test
  void compressedSizeIsTheSumOfTheColumnTotalSizes() {
    BlockMetaData block = new BlockMetaData();
    block.addColumn(column("a", 0L, 0L, 100L));
    block.addColumn(column("b", 100L, 0L, 250L));

    assertThat(block.getCompressedSize()).isEqualTo(350L);
  }

  @Test
  void settersRoundTrip() {
    BlockMetaData block = new BlockMetaData();

    block.setPath("part-00000.parquet");
    block.setRowCount(4242L);
    block.setTotalByteSize(987654321L);
    block.setRowIndexOffset(17L);
    block.setOrdinal(3);

    assertThat(block.getPath()).isEqualTo("part-00000.parquet");
    assertThat(block.getRowCount()).isEqualTo(4242L);
    assertThat(block.getTotalByteSize()).isEqualTo(987654321L);
    assertThat(block.getRowIndexOffset()).isEqualTo(17L);
    assertThat(block.getOrdinal()).isEqualTo(3);
  }

  @Test
  void rowIndexOffsetCanBeMarkedUnavailable() {
    BlockMetaData block = new BlockMetaData();
    block.setRowIndexOffset(17L);

    block.setRowIndexOffset(-1L);

    assertThat(block.getRowIndexOffset()).isEqualTo(-1L);
  }

  @Test
  void toStringDescribesTheBlockAndItsColumns() {
    BlockMetaData block = new BlockMetaData();
    block.setRowCount(4242L);
    block.setTotalByteSize(987654321L);
    block.addColumn(column("a", 128L, 0L, 100L));

    assertThat(block)
        .asString()
        .startsWith("BlockMetaData{4242, 987654321 ")
        .contains("ColumnMetaData{")
        .doesNotContain("rowIndexOffset");
  }

  @Test
  void toStringIncludesTheRowIndexOffsetWhenAvailable() {
    BlockMetaData block = new BlockMetaData();
    block.setRowCount(7L);
    block.setTotalByteSize(8L);
    block.setRowIndexOffset(99L);

    assertThat(block).asString().contains("rowIndexOffset = 99");
  }
}
