    assertThat(metadata.getEncodingStats()).isNull();
    assertThat(metadata.getEncodings()).containsExactly(Encoding.PLAIN);
    assertThat(metadata.getFirstDataPageOffset()).isEqualTo(128L);
    assertThat(metadata.getDictionaryPageOffset()).isZero();
    assertThat(metadata.getValueCount()).isEqualTo(10L);
    assertThat(metadata.getTotalSize()).isEqualTo(1000L);
    assertThat(metadata.getTotalUncompressedSize()).isEqualTo(2000L);
    assertThat(metadata.getStatistics()).isSameAs(STATISTICS);
