        .contains("[a, b]")
        .contains("PLAIN")
        .contains("128");
  }

  @Test
  void deprecatedFactoryWithoutStatisticsCreatesEmptyBooleanStatistics() {
    ColumnChunkMetaData metadata = ColumnChunkMetaData.get(
        PATH,
        PrimitiveTypeName.INT32,
        CompressionCodecName.SNAPPY,
        PLAIN,
        128L,
        0L,
