        1000L,
        2000L);

    assertThat(metadata.getStatistics()).isInstanceOf(BooleanStatistics.class);
    assertThat(metadata.getStatistics().isEmpty()).isTrue();
    assertThat(metadata.getTotalSize()).isEqualTo(1000L);
  }

  @Test
  void deprecatedFactoryWithPrimitiveTypeNameBuildsAnOptionalType() {
    ColumnChunkMetaData metadata = ColumnChunkMetaData.get(
        PATH, PrimitiveTypeName.INT64, CompressionCodecName.GZIP, PLAIN, STATISTICS, 128L, 0L, 10L, 1000L, 2000L);

    assertThat(metadata.getPrimitiveType().getPrimitiveTypeName()).isEqualTo(PrimitiveTypeName.INT64);
    assertThat(metadata.getPrimitiveType().isRepetition(PrimitiveType.Repetition.OPTIONAL))
        .isTrue();
    assertThat(metadata.getCodec()).isEqualTo(CompressionCodecName.GZIP);
    assertThat(metadata.getStatistics()).isSameAs(STATISTICS);
  }
}
