    EncodingStats withDictionaryPages = new EncodingStats.Builder()
        .addDictEncoding(Encoding.PLAIN_DICTIONARY)
        .addDataEncoding(Encoding.RLE_DICTIONARY)
        .build();
    EncodingStats dictionaryPagesOnly = new EncodingStats.Builder()
        .addDictEncoding(Encoding.PLAIN_DICTIONARY)
        .addDataEncoding(Encoding.PLAIN)
        .build();

    ColumnChunkMetaData dictionaryEncoded = metadata(PLAIN, withDictionaryPages, 128L, 64L, 10L, 100L, 200L);
