package org.apache.parquet.hadoop.metadata;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.apache.parquet.VersionParser.ParsedVersion;
import org.apache.parquet.VersionParser.VersionParseException;
import org.apache.parquet.schema.MessageType;
import org.apache.parquet.schema.PrimitiveType.PrimitiveTypeName;
import org.apache.parquet.schema.Types;
import org.junit.jupiter.api.Test;

class FileMetaDataTest {

  private static final String CREATED_BY = "parquet-mr version 1.8.0 (build abc123)";

  private static MessageType schema() {
    return Types.buildMessage()
        .required(PrimitiveTypeName.INT32)
        .named("id")
        .named("schema");
  }

  private static FileMetaData fileMetaData() {
    return new FileMetaData(schema(), Collections.singletonMap("key", "value"), CREATED_BY);
  }

  @Test
  void rejectsANullSchema() {
    assertThatThrownBy(() -> new FileMetaData(null, Collections.emptyMap(), CREATED_BY))
        .isInstanceOf(NullPointerException.class)
        .hasMessage("schema cannot be null");
  }

  @Test
  void rejectsNullKeyValueMetadata() {
    assertThatThrownBy(() -> new FileMetaData(schema(), null, CREATED_BY))
        .isInstanceOf(NullPointerException.class)
        .hasMessage("keyValueMetaData cannot be null");
  }

  @Test
  void exposesSchemaKeyValueMetadataAndCreatedBy() {
    MessageType schema = schema();
    FileMetaData fileMetaData =
        new FileMetaData(schema, Collections.singletonMap("key", "value"), CREATED_BY);

    assertThat(fileMetaData.getSchema()).isSameAs(schema);
    assertThat(fileMetaData.getKeyValueMetaData()).containsEntry("key", "value");
    assertThat(fileMetaData.getCreatedBy()).isEqualTo(CREATED_BY);
    assertThat(fileMetaData.getFileDecryptor()).isNull();
  }

  @Test
  void keyValueMetadataCannotBeModified() {
    Map<String, String> keyValueMetaData = new HashMap<>();
    keyValueMetaData.put("key", "value");
    FileMetaData fileMetaData = new FileMetaData(schema(), keyValueMetaData, CREATED_BY);
    Map<String, String> exposed = fileMetaData.getKeyValueMetaData();

    assertThatThrownBy(() -> exposed.put("other", "value")).isInstanceOf(UnsupportedOperationException.class);
    assertThat(exposed).containsOnlyKeys("key");
  }

  @Test
  void writerVersionIsParsedFromCreatedBy() throws VersionParseException {
    ParsedVersion version = fileMetaData().getWriterVersion();

    assertThat(version).isNotNull();
    assertThat(version.application).isEqualTo("parquet-mr");
    assertThat(version.version).isEqualTo("1.8.0");
    assertThat(version.appBuildHash).isEqualTo("abc123");
    assertThat(version.hasSemanticVersion()).isTrue();
    assertThat(version.getSemanticVersion().toString()).isEqualTo("1.8.0");
  }

  @Test
  void writerVersionIsCached() throws VersionParseException {
    FileMetaData fileMetaData = fileMetaData();

    assertThat(fileMetaData.getWriterVersion()).isSameAs(fileMetaData.getWriterVersion());
  }

  @Test
  void writerVersionIsNullWhenCreatedByIsMissing() throws VersionParseException {
    assertThat(new FileMetaData(schema(), Collections.emptyMap(), null).getWriterVersion())
        .isNull();
    assertThat(new FileMetaData(schema(), Collections.emptyMap(), "").getWriterVersion())
        .isNull();
  }

  @Test
  void writerVersionHasNoVersionWhenCreatedByHasNoVersionNumber() throws VersionParseException {
    ParsedVersion version =
        new FileMetaData(schema(), Collections.emptyMap(), "parquet-mr version").getWriterVersion();

    assertThat(version).isNotNull();
    assertThat(version.application).isEqualTo("parquet-mr");
    assertThat(version.version).isNull();
    assertThat(version.hasSemanticVersion()).isFalse();
  }

  @Test
  void unparsableCreatedByIsReportedOnEveryCall() {
    FileMetaData fileMetaData = new FileMetaData(schema(), Collections.emptyMap(), "unknown writer");

    assertThatThrownBy(fileMetaData::getWriterVersion)
        .isInstanceOf(VersionParseException.class)
        .hasMessageContaining("Could not parse created_by: unknown writer");
    assertThatThrownBy(fileMetaData::getWriterVersion)
        .isInstanceOf(VersionParseException.class)
        .hasMessageContaining("Could not parse created_by: unknown writer");
  }

  @Test
  void encryptionTypeIsNotSetForWriterMetadata() {
    assertThat(fileMetaData().getEncryptionType()).isNull();
  }

  @Test
  void encryptionTypeIsExposedForReaderMetadata() {
    FileMetaData fileMetaData = new FileMetaData(
        schema(),
        Collections.emptyMap(),
        CREATED_BY,
        FileMetaData.EncryptionType.PLAINTEXT_FOOTER,
        null);

    assertThat(fileMetaData.getEncryptionType()).isEqualTo(FileMetaData.EncryptionType.PLAINTEXT_FOOTER);
    assertThat(fileMetaData.getFileDecryptor()).isNull();
  }

  @Test
  void deprecatedConstructorWithoutEncryptionTypeDoesNotSetIt() {
    FileMetaData fileMetaData = new FileMetaData(schema(), Collections.emptyMap(), CREATED_BY, null);

    assertThat(fileMetaData.getEncryptionType()).isNull();
    assertThat(fileMetaData.getFileDecryptor()).isNull();
  }

  @Test
  void toStringDescribesSchemaAndMetadata() {
    assertThat(fileMetaData())
        .asString()
        .startsWith("FileMetaData{schema: message schema")
        .contains("metadata: {key=value}");
  }

  @Test
  void javaSerializationPreservesTheMetadata() throws Exception {
    FileMetaData fileMetaData = fileMetaData();

    ByteArrayOutputStream bytes = new ByteArrayOutputStream();
    try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
      out.writeObject(fileMetaData);
    }

    FileMetaData restored;
    try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
      restored = (FileMetaData) in.readObject();
    }

    assertThat(restored.getSchema()).isEqualTo(fileMetaData.getSchema());
    assertThat(restored.getKeyValueMetaData()).containsExactlyEntriesOf(fileMetaData.getKeyValueMetaData());
    assertThat(restored.getCreatedBy()).isEqualTo(CREATED_BY);
    assertThat(restored.getWriterVersion()).isEqualTo(fileMetaData.getWriterVersion());
  }
}
