import org.apache.parquet.schema.PrimitiveType.PrimitiveTypeName;
import org.apache.parquet.schema.Types;
import org.junit.jupiter.api.Test;

class GlobalMetaDataTest {

  private static MessageType schema() {
    return Types.buildMessage()
        .required(PrimitiveTypeName.INT32)
        .named("id")
        .named("schema");
  }

  private static Map<String, Set<String>> singleValuedMetadata() {
    Map<String, Set<String>> keyValueMetaData = new LinkedHashMap<>();
    keyValueMetaData.put("key", new LinkedHashSet<>(Collections.singletonList("value")));
    keyValueMetaData.put("other", new LinkedHashSet<>(Collections.singletonList("thing")));
    return keyValueMetaData;
  }

  private static GlobalMetaData globalMetaData(Map<String, Set<String>> keyValueMetaData, String... createdBy) {
    return new GlobalMetaData(schema(), keyValueMetaData, new LinkedHashSet<>(java.util.Arrays.asList(createdBy)));
  }

  @Test
  void rejectsANullSchema() {
    assertThatThrownBy(() -> new GlobalMetaData(null, Collections.emptyMap(), Collections.emptySet()))
        .isInstanceOf(NullPointerException.class)
        .hasMessage("schema cannot be null");
  }

  @Test
  void rejectsNullKeyValueMetadata() {
    assertThatThrownBy(() -> new GlobalMetaData(schema(), null, Collections.emptySet()))
        .isInstanceOf(NullPointerException.class)
        .hasMessage("keyValueMetaData cannot be null");
  }

  @Test
  void exposesSchemaKeyValueMetadataAndCreatedBy() {
    MessageType schema = schema();
    Set<String> createdBy = new LinkedHashSet<>(Collections.singletonList("parquet-mr version 1.8.0"));
    GlobalMetaData globalMetaData = new GlobalMetaData(schema, singleValuedMetadata(), createdBy);

    assertThat(globalMetaData.getSchema()).isSameAs(schema);
    assertThat(globalMetaData.getKeyValueMetaData()).containsOnlyKeys("key", "other");
    assertThat(globalMetaData.getKeyValueMetaData().get("key")).containsExactly("value");
    assertThat(globalMetaData.getCreatedBy()).isSameAs(createdBy);
  }

  @Test
  void keyValueMetadataCannotBeModified() {
    GlobalMetaData globalMetaData = globalMetaData(singleValuedMetadata(), "writer");
    Map<String, Set<String>> exposed = globalMetaData.getKeyValueMetaData();

    assertThatThrownBy(() -> exposed.put("new", Collections.emptySet()))
        .isInstanceOf(UnsupportedOperationException.class);
  }

  @Test
  void mergeProducesFileMetadataWithASingleCreatedByValue() {
    GlobalMetaData globalMetaData = globalMetaData(singleValuedMetadata(), "parquet-mr version 1.8.0");

    FileMetaData merged = globalMetaData.merge();

    assertThat(merged.getSchema()).isSameAs(globalMetaData.getSchema());
    assertThat(merged.getCreatedBy()).isEqualTo("parquet-mr version 1.8.0");
    assertThat(merged.getKeyValueMetaData()).containsExactlyInAnyOrderEntriesOf(Map.of("key", "value", "other", "thing"));
  }

  @Test
  void mergeJoinsSeveralCreatedByValues() {
    GlobalMetaData globalMetaData = globalMetaData(singleValuedMetadata(), "writer-a", "writer-b");

    FileMetaData merged = globalMetaData.merge();

    assertThat(merged.getCreatedBy()).isEqualTo("[writer-a, writer-b]");
  }

  @Test
  void mergeFailsOnConflictingValuesWithTheDefaultStrategy() {
    Map<String, Set<String>> keyValueMetaData = new HashMap<>();
    keyValueMetaData.put("key", new LinkedHashSet<>(java.util.Arrays.asList("first", "second")));
    GlobalMetaData globalMetaData = globalMetaData(keyValueMetaData, "writer");

    assertThatThrownBy(globalMetaData::merge)
        .isInstanceOf(RuntimeException.class)
        .hasMessage("could not merge metadata: key key has conflicting values: [first, second]");
  }

  @Test
  void mergeUsesTheProvidedMergeStrategy() {
    Map<String, Set<String>> keyValueMetaData = new LinkedHashMap<>();
    keyValueMetaData.put("key", new LinkedHashSet<>(java.util.Arrays.asList("first", "second")));
    keyValueMetaData.put("other", new LinkedHashSet<>(Collections.singletonList("third")));
    GlobalMetaData globalMetaData = globalMetaData(keyValueMetaData, "writer-a", "writer-b");

    FileMetaData merged = globalMetaData.merge(new ConcatenatingKeyValueMetadataMergeStrategy("|"));

    assertThat(merged.getKeyValueMetaData())
        .containsExactlyInAnyOrderEntriesOf(Map.of("key", "first|second", "other", "third"));
    assertThat(merged.getCreatedBy()).isEqualTo("[writer-a, writer-b]");
  }

  @Test
  void mergeOfEmptyMetadataProducesEmptyKeyValues() {
    GlobalMetaData globalMetaData =
        new GlobalMetaData(schema(), Collections.emptyMap(), Collections.singleton("writer"));

    FileMetaData merged = globalMetaData.merge();

    assertThat(merged.getKeyValueMetaData()).isEmpty();
    assertThat(merged.getCreatedBy()).isEqualTo("writer");
  }

  @Test
  void toStringDescribesSchemaAndMetadata() {
    GlobalMetaData globalMetaData = globalMetaData(singleValuedMetadata(), "writer");

    assertThat(globalMetaData)
        .asString()
        .startsWith("GlobalMetaData{schema: message schema")
        .contains("metadata: {");
  }
}
