import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.Set;
import org.junit.jupiter.api.Test;

class KeyValueMetadataMergeStrategyTest {

  private static Map<String, Set<String>> metadata(String... valuesPerKey) {
    Map<String, Set<String>> keyValueMetaData = new LinkedHashMap<>();
    for (int i = 0; i < valuesPerKey.length; i += 2) {
      keyValueMetaData.put(valuesPerKey[i], new LinkedHashSet<>(Arrays.asList(valuesPerKey[i + 1].split(","))));
    }
    return keyValueMetaData;
  }

  @SuppressWarnings("unchecked")
  private static <T> T serializedCopy(T value) throws Exception {
    ByteArrayOutputStream bytes = new ByteArrayOutputStream();
    try (ObjectOutputStream out = new ObjectOutputStream(bytes)) {
      out.writeObject(value);
    }
    try (ObjectInputStream in = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
      return (T) in.readObject();
    }
  }

  @Test
  void concatenatingStrategyJoinsValuesWithACommaByDefault() {
    KeyValueMetadataMergeStrategy strategy = new ConcatenatingKeyValueMetadataMergeStrategy();

    Map<String, String> merged = strategy.merge(metadata("key", "first,second", "other", "third"));

    assertThat(merged).containsExactlyInAnyOrderEntriesOf(Map.of("key", "first,second", "other", "third"));
  }

  @Test
  void concatenatingStrategyJoinsValuesWithACustomDelimiter() {
    KeyValueMetadataMergeStrategy strategy = new ConcatenatingKeyValueMetadataMergeStrategy(" | ");

    Map<String, String> merged = strategy.merge(metadata("key", "first,second,third"));

    assertThat(merged).containsExactlyInAnyOrderEntriesOf(Map.of("key", "first | second | third"));
  }

  @Test
  void concatenatingStrategyKeepsSingleValuesUnchanged() {
    KeyValueMetadataMergeStrategy strategy = new ConcatenatingKeyValueMetadataMergeStrategy();

    Map<String, String> merged = strategy.merge(metadata("key", "value"));

    assertThat(merged).containsOnlyKeys("key");
    assertThat(merged.get("key")).isEqualTo("value");
  }

  @Test
  void concatenatingStrategyReturnsAnEmptyMapForEmptyMetadata() {
    KeyValueMetadataMergeStrategy strategy = new ConcatenatingKeyValueMetadataMergeStrategy();

    assertThat(strategy.merge(Collections.emptyMap())).isEmpty();
  }

  @Test
  void concatenatingStrategyProducesAnEmptyValueForAnEmptyValueSet() {
    Map<String, Set<String>> keyValueMetaData = new HashMap<>();
    keyValueMetaData.put("key", Collections.emptySet());
    KeyValueMetadataMergeStrategy strategy = new ConcatenatingKeyValueMetadataMergeStrategy();

    Map<String, String> merged = strategy.merge(keyValueMetaData);

    assertThat(merged).containsExactlyInAnyOrderEntriesOf(Map.of("key", ""));
  }

  @Test
  void concatenatingStrategyDoesNotModifyTheInput() {
    Map<String, Set<String>> keyValueMetaData = metadata("key", "first,second");
    KeyValueMetadataMergeStrategy strategy = new ConcatenatingKeyValueMetadataMergeStrategy();

    strategy.merge(keyValueMetaData);

    assertThat(keyValueMetaData).containsOnlyKeys("key");
    assertThat(keyValueMetaData.get("key")).containsExactly("first", "second");
  }

  @Test
  void concatenatingStrategySurvivesSerialization() throws Exception {
    KeyValueMetadataMergeStrategy strategy =
        serializedCopy(new ConcatenatingKeyValueMetadataMergeStrategy(";"));
    Map<String, Set<String>> keyValueMetaData = metadata("key", "first,second");

    Map<String, String> merged = strategy.merge(keyValueMetaData);

    assertThat(merged).containsExactlyInAnyOrderEntriesOf(Map.of("key", "first;second"));
  }

  @Test
  void strictStrategyKeepsSingleValuesUnchanged() {
    KeyValueMetadataMergeStrategy strategy = new StrictKeyValueMetadataMergeStrategy();

    Map<String, String> merged = strategy.merge(metadata("key", "value", "other", "thing"));

    assertThat(merged).containsExactlyInAnyOrderEntriesOf(Map.of("key", "value", "other", "thing"));
  }

  @Test
  void strictStrategyReturnsAnEmptyMapForEmptyMetadata() {
    KeyValueMetadataMergeStrategy strategy = new StrictKeyValueMetadataMergeStrategy();

    assertThat(strategy.merge(Collections.emptyMap())).isEmpty();
  }

  @Test
  void strictStrategyRejectsConflictingValues() {
    KeyValueMetadataMergeStrategy strategy = new StrictKeyValueMetadataMergeStrategy();

    assertThatThrownBy(() -> strategy.merge(metadata("key", "first,second")))
        .isInstanceOf(RuntimeException.class)
        .hasMessage("could not merge metadata: key key has conflicting values: [first, second]");
  }

  @Test
  void strictStrategyFailsOnAnEmptyValueSet() {
    Map<String, Set<String>> keyValueMetaData = new HashMap<>();
    keyValueMetaData.put("key", Collections.emptySet());
    KeyValueMetadataMergeStrategy strategy = new StrictKeyValueMetadataMergeStrategy();

    assertThatThrownBy(() -> strategy.merge(keyValueMetaData)).isInstanceOf(NoSuchElementException.class);
  }

  @Test
  void strictStrategySurvivesSerialization() throws Exception {
    KeyValueMetadataMergeStrategy strategy = serializedCopy(new StrictKeyValueMetadataMergeStrategy());

    assertThatThrownBy(() -> strategy.merge(metadata("key", "first,second")))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("conflicting values");
  }
}
