import org.apache.parquet.schema.Types;
import org.junit.jupiter.api.Test;

class ParquetMetadataTest {

  private static final String CREATED_BY = "parquet-mr version 1.8.0 (build abc)";
  private static final PrimitiveType TYPE = Types.optional(PrimitiveTypeName.INT32).named("id");

  private static MessageType schema() {
    return Types.buildMessage()
        .optional(PrimitiveTypeName.INT32)
        .named("id")
        .named("schema");
  }

  private static FileMetaData fileMetaData(FileMetaData.EncryptionType encryptionType) {
    return new FileMetaData(schema(), Collections.singletonMap("key", "value"), CREATED_BY, encryptionType, null);
  }

  private static BlockMetaData block() {
    ColumnChunkMetaData column = ColumnChunkMetaData.get(
        ColumnPath.get("id"),
        TYPE,
        CompressionCodecName.SNAPPY,
        null,
        EnumSet.of(Encoding.PLAIN),
        Statistics.createStats(TYPE),
        10L,
        0L,
        5L,
        100L,
        200L,
        null,
        null);
    BlockMetaData block = new BlockMetaData();
    block.setRowCount(7L);
    block.setTotalByteSize(300L);
    block.addColumn(column);
    return block;
  }

  private static ParquetMetadata parquetMetadata(FileMetaData.EncryptionType encryptionType) {
    return new ParquetMetadata(fileMetaData(encryptionType), Collections.singletonList(block()));
  }

  @Test
  void exposesFileMetadataAndBlocks() {
    FileMetaData fileMetaData = fileMetaData(FileMetaData.EncryptionType.UNENCRYPTED);
    List<BlockMetaData> blocks = Collections.singletonList(block());

    ParquetMetadata parquetMetadata = new ParquetMetadata(fileMetaData, blocks);

    assertThat(parquetMetadata.getFileMetaData()).isSameAs(fileMetaData);
    assertThat(parquetMetadata.getBlocks()).isSameAs(blocks);
  }

  @Test
  void toStringDescribesFileMetadataAndBlocks() {
    ParquetMetadata parquetMetadata = parquetMetadata(FileMetaData.EncryptionType.UNENCRYPTED);

    assertThat(parquetMetadata)
        .asString()
        .startsWith("ParquetMetaData{FileMetaData{schema: message schema")
        .contains("blocks: [BlockMetaData{7, 300 ")
        .contains("ColumnMetaData{");
  }

  @Test
  void jsonContainsFileMetadataAndBlocksForUnencryptedMetadata() {
    String json = ParquetMetadata.toJSON(parquetMetadata(FileMetaData.EncryptionType.UNENCRYPTED));

    assertThat(json)
        .startsWith("{\"fileMetaData\":")
        .contains("\"createdBy\":\"" + CREATED_BY + "\"")
        .contains("\"encryptionType\":\"UNENCRYPTED\"")
        .contains("\"blocks\":[")
        .contains("\"rowCount\":7")
        .contains("\"totalByteSize\":300")
        .contains("\"valueCount\":5")
        .contains("\"codec\":\"SNAPPY\"");
  }

