    ParquetMetadata parquetMetadata = parquetMetadata(FileMetaData.EncryptionType.UNENCRYPTED);

    String pretty = ParquetMetadata.toPrettyJSON(parquetMetadata);
    String compact = ParquetMetadata.toJSON(parquetMetadata);

    assertThat(pretty).contains("\n").contains("\n  \"fileMetaData\"");
    assertThat(pretty.replaceAll("\\s+", "")).isEqualTo(compact.replaceAll("\\s+", ""));
