  private static MessageType schema() {
    return Types.buildMessage()
        .required(PrimitiveTypeName.INT32)
        .named("id")
        .named("schema");
  }

  private static Map<String, Set<String>> singleValuedMetadata() {
    Map<String, Set<String>> keyValueMetaData = new LinkedHashMap<>();
    keyValueMetaData.put("key", new LinkedHashSet<>(Collections.singletonList("value")));
    keyValueMetaData.put("other", new LinkedHashSet<>(Collections.singletonList("thing")));
    return keyValueMetaData;
  }

  private static GlobalMetaData globalMetaData(Map<String, Set<String>> keyValueMetaData, String... createdBy) {
    return new GlobalMetaData(schema(), keyValueMetaData, new LinkedHashSet<>(java.util.Arrays.asList(createdBy)));
  }

  @Test
  void rejectsANullSchema() {
    assertThatThrownBy(() -> new GlobalMetaData(null, Collections.emptyMap(), Collections.emptySet()))
        .isInstanceOf(NullPointerException.class)
        .hasMessage("schema cannot be null");
  }

  @Test
  void rejectsNullKeyValueMetadata() {
    assertThatThrownBy(() -> new GlobalMetaData(schema(), null, Collections.emptySet()))
        .isInstanceOf(NullPointerException.class)
        .hasMessage("keyValueMetaData cannot be null");
  }

  @Test
  void exposesSchemaKeyValueMetadataAndCreatedBy() {
    MessageType schema = schema();
    Set<String> createdBy = new LinkedHashSet<>(Collections.singletonList("parquet-mr version 1.8.0"));
    GlobalMetaData globalMetaData = new GlobalMetaData(schema, singleValuedMetadata(), createdBy);

    assertThat(globalMetaData.getSchema()).isSameAs(schema);
    assertThat(globalMetaData.getKeyValueMetaData()).containsOnlyKeys("key", "other");
    assertThat(globalMetaData.getKeyValueMetaData().get("key")).containsExactly("value");
    assertThat(globalMetaData.getCreatedBy()).isSameAs(createdBy);
  }

