public class Probe {
  public static void main(String[] args) throws Exception {
    for (int w=0; w<=32; w++) {
      BytePacker std = Packer.LITTLE_ENDIAN.newBytePacker(w);
      BytePacker vec = ByteBitPacking512VectorLE.factory.newBytePacker(w);
      int uc = vec.getUnpackCount();
      int n = 128;
      int[] vals = new int[n];
      Random r = new Random(1234+w);
      int max = w==32? Integer.MAX_VALUE : ((1<<w)-1);
      for (int i=0;i<n;i++) vals[i] = max==0?0:(r.nextInt() & max);
      int packedLen = w* n /8;
      byte[] packed = new byte[Math.max(packedLen, 128)];
      if (w>0) {
        for (int off=0; off+32<=n; off+=32) std.pack32Values(vals, off, packed, w*off/8);
      }
      int[] out = new int[Math.max(uc, 1)];
      try {
        if (uc>0) vec.unpackValuesUsingVector(packed, 0, out, 0);
        boolean ok = true;
        for (int i=0;i<uc;i++) if (out[i]!=vals[i]) { ok=false; break; }
        if (!ok) {
          System.out.println("MISMATCH width="+w+" uc="+uc);
          for (int i=0;i<Math.min(uc,16);i++) System.out.println(i+": got "+out[i]+" expected "+vals[i]);
        } else {
          System.out.println("ok width="+w+" uc="+uc);
        }
      } catch (Throwable t) {
        System.out.println("EXC width="+w+" uc="+uc+" "+t);
        t.printStackTrace(System.out);
      }
      // ByteBuffer heap variant
      try {
        int[] out2 = new int[Math.max(uc,1)];
        if (uc>0) vec.unpackValuesUsingVector(ByteBuffer.wrap(packed), 0, out2, 0);
        boolean ok=true;
        for (int i=0;i<uc;i++) if (out2[i]!=vals[i]) { ok=false; break; }
        if (!ok) System.out.println("BUF MISMATCH width="+w);
      } catch (Throwable t) { System.out.println("BUF EXC width="+w+" "+t); }
    }
  }
}
