  public static void main(String[] args) throws Exception {
    for (int w=1; w<=32; w++) {
      for (int count : new int[]{8,16,32,64,128,512,1024}) {
        BytePacker std = Packer.LITTLE_ENDIAN.newBytePacker(w);
        int[] vals = new int[count];
        Random r = new Random(1234+w*100000+count);
        int max = w==32? -1 : ((1<<w)-1);
        for (int i=0;i<count;i++) vals[i] = (max==0)?0:(r.nextInt() & max);
        int packedLen = w*count/8;
        byte[] packed = new byte[packedLen];
        for (int off=0; off+32<=count; off+=32) std.pack32Values(vals, off, packed, w*off/8);
        int[] out = new int[count+200];
        Arrays.fill(out, -1);
        ByteBufferInputStream in = ByteBufferInputStream.wrap(ByteBuffer.wrap(packed));
        try {
          ParquetReadRouter.readBatchUsing512Vector(w, in, count, out);
          int mism=-1;
          for(int i=0;i<count;i++) if(out[i]!=vals[i]) {mism=i;break;}
