package org.apache.parquet.column.values.bitpacking;

import java.util.Random;
import java.util.stream.IntStream;

/**
 * Shared test data and helpers for the vector bit-packing tests.
 *
 * <p>The packed bytes used as input are produced by the mature, scalar little-endian bit packer. This keeps the vector
 * implementation under test independent from the expected data.
 */
final class VectorTestData {

  private VectorTestData() {}

  static IntStream bitWidths() {
    return IntStream.rangeClosed(1, 32);
  }

  /**
   * Creates pseudo-random values that all fit in {@code bitWidth} bits.
   */
  static int[] valuesFor(int bitWidth, int count) {
    if (bitWidth < 1 || bitWidth > 32) {
      throw new IllegalArgumentException("bitWidth must be in [1, 32]");
    }
    if (count < 0 || count % 8 != 0) {
      throw new IllegalArgumentException("count must be a non-negative multiple of 8");
    }
    int mask = bitWidth == 32 ? -1 : (1 << bitWidth) - 1;
    int[] values = new int[count];
    Random random = new Random(0x5DEECE66DL * bitWidth + 0x9E3779B9L);
    for (int i = 0; i < count; i++) {
      values[i] = random.nextInt() & mask;
    }
    return values;
  }

  static byte[] packLittleEndian(int bitWidth, int[] values) {
    if (values.length % 8 != 0) {
      throw new IllegalArgumentException("values length must be a multiple of 8");
    }
    BytePacker packer = Packer.LITTLE_ENDIAN.newBytePacker(bitWidth);
    byte[] packed = new byte[bitWidth * values.length / 8];
    for (int i = 0; i < values.length; i += 8) {
      packer.pack8Values(values, i, packed, bitWidth * i / 8);
    }
    return packed;
  }
}
