 * under the License.
 */
package org.apache.parquet.column.values.bitpacking;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.junit.jupiter.api.Assumptions.assumeTrue;

import java.nio.ByteBuffer;
import java.util.Arrays;
import java.util.stream.IntStream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

class ByteBitPacking512VectorLETest {

  private static final int VALUES_PER_DECODE = 256;

  static IntStream bitWidths() {
    return VectorTestData.bitWidths();
  }

  private static void assumeVectorSupport() {
    assumeTrue(
        ParquetReadRouter.getSupportVectorFromCPUFlags() == VectorSupport.VECTOR_512,
        "AVX-512 VBMI/VBMI2 support is required for the vector decoder");
  }

  private static void assertDecoded(BytePacker packer, ByteBuffer input, int inPos, int[] expectedValues) {
    int unpackCount = packer.getUnpackCount();
    // A few implementations write one extra output vector; keep enough room so that the
    // assertions describe the documented output rather than the implementation's scratch usage.
    int[] actual = new int[Math.max(unpackCount, 32) + 8];
    packer.unpackValuesUsingVector(input, inPos, actual, 0);

    assertThat(Arrays.copyOf(actual, unpackCount))
        .as("decoded values for bit width %d", packer.getBitWidth())
        .containsExactly(Arrays.copyOf(expectedValues, unpackCount));
  }

  @Test
  void factoryProvidesOneStablePackerForEverySupportedBitWidth() {
    for (int bitWidth = 0; bitWidth <= 32; bitWidth++) {
      BytePacker packer = ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth);

      assertThat(packer).as("packer for bit width %d", bitWidth).isNotNull();
      assertThat(packer.getBitWidth()).isEqualTo(bitWidth);
      assertThat(ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth))
          .as("factory should reuse the packer for bit width %d", bitWidth)
          .isSameAs(packer);
    }
  }

  @Test
  void factoryRejectsBitWidthsOutsideTheSupportedRange() {
    assertThatThrownBy(() -> ByteBitPacking512VectorLE.factory.newBytePacker(-1))
        .isInstanceOf(IndexOutOfBoundsException.class);
    assertThatThrownBy(() -> ByteBitPacking512VectorLE.factory.newBytePacker(33))
        .isInstanceOf(IndexOutOfBoundsException.class);
  }

  @Test
  void littleEndianPackerUsesTheVectorFactory() {
    for (int bitWidth = 0; bitWidth <= 32; bitWidth++) {
      assertThat(Packer.LITTLE_ENDIAN.newBytePackerVector(bitWidth))
          .as("packer from Packer.LITTLE_ENDIAN for bit width %d", bitWidth)
          .isSameAs(ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth));
    }
  }

  @Test
  void unpackCountsArePositiveMultiplesOfEightForNonZeroWidths() {
    assertThat(ByteBitPacking512VectorLE.factory.newBytePacker(0).getUnpackCount())
        .isZero();

    for (int bitWidth = 1; bitWidth <= 32; bitWidth++) {
      assertThat(ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth).getUnpackCount())
          .as("unpack count for bit width %d", bitWidth)
          .isPositive()
          .isMultipleOf(8)
          .isBetween(8, 64);
    }
  }

  @Test
  void widthZeroPackerLeavesDataUntouched() {
    BytePacker packer = ByteBitPacking512VectorLE.factory.newBytePacker(0);
    int[] output = {11, -7, 123};
    byte[] packed = {1, 2, 3, 4};

    packer.unpackValuesUsingVector(packed, 0, output, 0);
    packer.unpackValuesUsingVector(ByteBuffer.wrap(packed), 0, output, 0);
    packer.pack8Values(new int[] {1, 2, 3, 4, 5, 6, 7, 8}, 0, new byte[2], 0);
    packer.pack32Values(new int[32], 0, new byte[4], 0);

    assertThat(output).containsExactly(11, -7, 123);
  }

  @ParameterizedTest
  @MethodSource("bitWidths")
  void unpackValuesFromByteArrayMatchesLittleEndianReference(int bitWidth) {
    assumeVectorSupport();
    int[] values = VectorTestData.valuesFor(bitWidth, VALUES_PER_DECODE);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);

    assertDecoded(ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth), ByteBuffer.wrap(packed), 0, values);
  }

  @ParameterizedTest
  @MethodSource("bitWidths")
  void unpackValuesFromWritableHeapByteBufferMatchesLittleEndianReference(int bitWidth) {
    assumeVectorSupport();
    int[] values = VectorTestData.valuesFor(bitWidth, VALUES_PER_DECODE);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);

    assertDecoded(
        ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth),
        ByteBuffer.wrap(packed).slice(),
        0,
        values);
  }

  @ParameterizedTest
  @MethodSource("bitWidths")
  void unpackValuesFromHeapByteBufferWithNonZeroArrayOffset(int bitWidth) {
    assumeVectorSupport();
    int[] values = VectorTestData.valuesFor(bitWidth, VALUES_PER_DECODE);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);
    int prefix = 13;
    byte[] backing = new byte[prefix + packed.length + 7];
    System.arraycopy(packed, 0, backing, prefix, packed.length);
    ByteBuffer buffer = ByteBuffer.wrap(backing, prefix, packed.length);

    assertDecoded(ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth), buffer, buffer.position(), values);
  }

  @ParameterizedTest
  @MethodSource("bitWidths")
  void unpackValuesFromDirectByteBufferMatchesLittleEndianReference(int bitWidth) {
    assumeVectorSupport();
    int[] values = VectorTestData.valuesFor(bitWidth, VALUES_PER_DECODE);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);
    ByteBuffer buffer = ByteBuffer.allocateDirect(packed.length);
    buffer.put(packed);
    buffer.flip();

    assertDecoded(ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth), buffer, 0, values);
  }

  @ParameterizedTest
  @MethodSource("bitWidths")
  void unpackValuesFromReadOnlyHeapByteBufferMatchesLittleEndianReference(int bitWidth) {
    assumeVectorSupport();
    int[] values = VectorTestData.valuesFor(bitWidth, VALUES_PER_DECODE);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);

    assertDecoded(
        ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth),
        ByteBuffer.wrap(packed).asReadOnlyBuffer(),
        0,
        values);
  }

  @ParameterizedTest
  @MethodSource("bitWidths")
  void unpackValuesFromReadOnlyDirectByteBufferMatchesLittleEndianReference(int bitWidth) {
    assumeVectorSupport();
    int[] values = VectorTestData.valuesFor(bitWidth, VALUES_PER_DECODE);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);
    ByteBuffer buffer = ByteBuffer.allocateDirect(packed.length);
    buffer.put(packed);
    buffer.flip();

    assertDecoded(ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth), buffer.asReadOnlyBuffer(), 0, values);
  }

  @ParameterizedTest
  @MethodSource("bitWidths")
  void unpackValuesHonorsInputAndOutputOffsets(int bitWidth) {
    assumeVectorSupport();
    int[] values = VectorTestData.valuesFor(bitWidth, VALUES_PER_DECODE);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);
    int inputPrefix = 7;
    byte[] input = new byte[inputPrefix + packed.length];
    System.arraycopy(packed, 0, input, inputPrefix, packed.length);

    BytePacker packer = ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth);
    int unpackCount = packer.getUnpackCount();
    int outputOffset = 5;
    int[] actual = new int[outputOffset + Math.max(unpackCount, 32) + 8];
   Arrays.fill(actual, -1);
    packer.unpackValuesUsingVector(input, inputPrefix, actual, outputOffset);

    assertThat(Arrays.copyOfRange(actual, outputOffset, outputOffset + unpackCount))
        .as("decoded values at an output offset for bit width %d", bitWidth)
        .containsExactly(Arrays.copyOf(values, unpackCount));
  }

  @ParameterizedTest
  @MethodSource("bitWidths")
  void unpackAllSetValuesMatchesLittleEndianReference(int bitWidth) {
    assumeVectorSupport();
    int[] values = new int[VALUES_PER_DECODE];
    Arrays.fill(values, bitWidth == 32 ? -1 : (1 << bitWidth) - 1);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);

    assertDecoded(ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth), ByteBuffer.wrap(packed), 0, values);
  }

  @ParameterizedTest
  @MethodSource("bitWidths")
  void unsupportedScalarMethodsFailFast(int bitWidth) {
    BytePacker packer = ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth);
    byte[] packed = new byte[bitWidth * 4];
    int[] output = new int[32];

    assertThatThrownBy(() -> packer.pack8Values(new int[8], 0, packed, 0))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("ByteBitPackingLE");
    assertThatThrownBy(() -> packer.pack32Values(new int[32], 0, packed, 0))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("ByteBitPackingLE");
    assertThatThrownBy(() -> packer.unpack8Values(packed, 0, output, 0))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("ByteBitPackingLE");
    assertThatThrownBy(() -> packer.unpack8Values(ByteBuffer.wrap(packed), 0, output, 0))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("ByteBitPackingLE");
    assertThatThrownBy(() -> packer.unpack32Values(packed, 0, output, 0))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("ByteBitPackingLE");
    assertThatThrownBy(() -> packer.unpack32Values(ByteBuffer.wrap(packed), 0, output, 0))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("ByteBitPackingLE");
  }
}
EOF
