import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.junit.jupiter.api.Assumptions.assumeTrue;

import java.nio.ByteBuffer;
import java.util.Arrays;
import java.util.stream.IntStream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

class ByteBitPacking512VectorLETest {

  private static final int VALUES_PER_DECODE = 256;

  static IntStream bitWidths() {
    return VectorTestData.bitWidths();
  }

  private static void assumeVectorSupport() {
    assumeTrue(
        ParquetReadRouter.getSupportVectorFromCPUFlags() == VectorSupport.VECTOR_512,
        "AVX-512 VBMI/VBMI2 support is required for the vector decoder");
  }

  private static void assertDecoded(BytePacker packer, ByteBuffer input, int inPos, int[] expectedValues) {
    int unpackCount = packer.getUnpackCount();
    // A few implementations write one extra output vector; keep enough room so that the
    // assertions describe the documented output rather than the implementation's scratch usage.
    int[] actual = new int[Math.max(unpackCount, 32) + 8];
    packer.unpackValuesUsingVector(input, inPos, actual, 0);

    assertThat(Arrays.copyOf(actual, unpackCount))
        .as("decoded values for bit width %d", packer.getBitWidth())
        .containsExactly(Arrays.copyOf(expectedValues, unpackCount));
  }

  @Test
  void factoryProvidesOneStablePackerForEverySupportedBitWidth() {
    for (int bitWidth = 0; bitWidth <= 32; bitWidth++) {
      BytePacker packer = ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth);

      assertThat(packer).as("packer for bit width %d", bitWidth).isNotNull();
      assertThat(packer.getBitWidth()).isEqualTo(bitWidth);
      assertThat(ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth))
          .as("factory should reuse the packer for bit width %d", bitWidth)
          .isSameAs(packer);
    }
  }

  @Test
  void factoryRejectsBitWidthsOutsideTheSupportedRange() {
    assertThatThrownBy(() -> ByteBitPacking512VectorLE.factory.newBytePacker(-1))
        .isInstanceOf(IndexOutOfBoundsException.class);
    assertThatThrownBy(() -> ByteBitPacking512VectorLE.factory.newBytePacker(33))
        .isInstanceOf(IndexOutOfBoundsException.class);
  }

  @Test
  void littleEndianPackerUsesTheVectorFactory() {
    for (int bitWidth = 0; bitWidth <= 32; bitWidth++) {
      assertThat(Packer.LITTLE_ENDIAN.newBytePackerVector(bitWidth))
          .as("packer from Packer.LITTLE_ENDIAN for bit width %d", bitWidth)
          .isSameAs(ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth));
    }
  }

  @Test
  void unpackCountsArePositiveMultiplesOfEightForNonZeroWidths() {
    assertThat(ByteBitPacking512VectorLE.factory.newBytePacker(0).getUnpackCount())
        .isZero();

    for (int bitWidth = 1; bitWidth <= 32; bitWidth++) {
      assertThat(ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth).getUnpackCount())
          .as("unpack count for bit width %d", bitWidth)
          .isPositive()
          .isMultipleOf(8)
          .isBetween(8, 64);
    }
  }

  @Test
  void widthZeroPackerLeavesDataUntouched() {
    BytePacker packer = ByteBitPacking512VectorLE.factory.newBytePacker(0);
    int[] output = {11, -7, 123};
    byte[] packed = {1, 2, 3, 4};

    packer.unpackValuesUsingVector(packed, 0, output, 0);
    packer.unpackValuesUsingVector(ByteBuffer.wrap(packed), 0, output, 0);
    packer.pack8Values(new int[] {1, 2, 3, 4, 5, 6, 7, 8}, 0, new byte[2], 0);
    packer.pack32Values(new int[32], 0, new byte[4], 0);

    assertThat(output).containsExactly(11, -7, 123);
  }

