    assumeVectorSupport();
    int[] values = VectorTestData.valuesFor(bitWidth, VALUES_PER_DECODE);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);
    ByteBuffer buffer = ByteBuffer.allocateDirect(packed.length);
    buffer.put(packed);
    buffer.flip();

    assertDecoded(ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth), buffer, 0, values);
  }

