    assumeVectorSupport();
    int[] values = VectorTestData.valuesFor(bitWidth, VALUES_PER_DECODE);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);
    ByteBuffer buffer = ByteBuffer.allocateDirect(packed.length);
    buffer.put(packed);
    buffer.flip();

    assertDecoded(ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth), buffer.asReadOnlyBuffer(), 0, values);
  }

  @ParameterizedTest
  @MethodSource("bitWidths")
  void unpackValuesHonorsInputAndOutputOffsets(int bitWidth) {
    assumeVectorSupport();
    int[] values = VectorTestData.valuesFor(bitWidth, VALUES_PER_DECODE);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);
    int inputPrefix = 7;
    byte[] input = new byte[inputPrefix + packed.length];
    System.arraycopy(packed, 0, input, inputPrefix, packed.length);

    BytePacker packer = ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth);
    int unpackCount = packer.getUnpackCount();
    int outputOffset = 5;
    int[] actual = new int[outputOffset + Math.max(unpackCount, 32) + 8];
   Arrays.fill(actual, -1);
    packer.unpackValuesUsingVector(input, inputPrefix, actual, outputOffset);

    assertThat(Arrays.copyOfRange(actual, outputOffset, outputOffset + unpackCount))
        .as("decoded values at an output offset for bit width %d", bitWidth)
        .containsExactly(Arrays.copyOf(values, unpackCount));
  }

  @ParameterizedTest
  @MethodSource("bitWidths")
  void unpackAllSetValuesMatchesLittleEndianReference(int bitWidth) {
    assumeVectorSupport();
    int[] values = new int[VALUES_PER_DECODE];
    Arrays.fill(values, bitWidth == 32 ? -1 : (1 << bitWidth) - 1);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);

    assertDecoded(ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth), ByteBuffer.wrap(packed), 0, values);
  }

  @ParameterizedTest
  @MethodSource("bitWidths")
  void unsupportedScalarMethodsFailFast(int bitWidth) {
    BytePacker packer = ByteBitPacking512VectorLE.factory.newBytePacker(bitWidth);
    byte[] packed = new byte[bitWidth * 4];
    int[] output = new int[32];

    assertThatThrownBy(() -> packer.pack8Values(new int[8], 0, packed, 0))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("ByteBitPackingLE");
    assertThatThrownBy(() -> packer.pack32Values(new int[32], 0, packed, 0))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("ByteBitPackingLE");
    assertThatThrownBy(() -> packer.unpack8Values(packed, 0, output, 0))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("ByteBitPackingLE");
    assertThatThrownBy(() -> packer.unpack8Values(ByteBuffer.wrap(packed), 0, output, 0))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("ByteBitPackingLE");
    assertThatThrownBy(() -> packer.unpack32Values(packed, 0, output, 0))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("ByteBitPackingLE");
    assertThatThrownBy(() -> packer.unpack32Values(ByteBuffer.wrap(packed), 0, output, 0))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("ByteBitPackingLE");
  }
}
