  private static void assumeVectorSupport() {
    assumeTrue(
        ParquetReadRouter.getSupportVectorFromCPUFlags() == VectorSupport.VECTOR_512,
        "AVX-512 VBMI/VBMI2 support is required for the vector decoder");
  }

  private static ByteBufferInputStream streamOf(byte[] bytes) {
    return ByteBufferInputStream.wrap(ByteBuffer.wrap(bytes));
  }

  private static void assertValues(int[] expected, int[] actual) {
