  @ParameterizedTest
  @MethodSource("bitWidths")
  void readBatchUsing512VectorSupportsMultiBufferStreams(int bitWidth) throws IOException {
    assumeVectorSupport();
    int[] values = VectorTestData.valuesFor(bitWidth, VALUES_PER_DECODE);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);
    int firstSplit = packed.length / 3;
    int secondSplit = 2 * packed.length / 3;
    ByteBufferInputStream in = ByteBufferInputStream.wrap(
        ByteBuffer.wrap(packed, 0, firstSplit),
        ByteBuffer.wrap(packed, firstSplit, secondSplit - firstSplit),
        ByteBuffer.wrap(packed, secondSplit, packed.length - secondSplit));
    int[] actual = new int[VALUES_PER_DECODE];

    ParquetReadRouter.readBatchUsing512Vector(bitWidth, in, VALUES_PER_DECODE, actual);

    assertValues(values, actual);
    assertThat(in.position()).isEqualTo(packed.length);
  }

  @ParameterizedTest
  @MethodSource("bitWidths")
  void readBatchUsing512VectorHonorsTheCurrentStreamPosition(int bitWidth) throws IOException {
    assumeVectorSupport();
    int[] values = VectorTestData.valuesFor(bitWidth, VALUES_PER_DECODE);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);
    int prefixLength = 19;
    byte[] withPrefix = new byte[prefixLength + packed.length];
    Arrays.fill(withPrefix, 0, prefixLength, (byte) 0x7F);
    System.arraycopy(packed, 0, withPrefix, prefixLength, packed.length);
    ByteBufferInputStream in = streamOf(withPrefix);
    in.skipFully(prefixLength);
    int[] actual = new int[VALUES_PER_DECODE];

    ParquetReadRouter.readBatchUsing512Vector(bitWidth, in, VALUES_PER_DECODE, actual);

    assertValues(values, actual);
    assertThat(in.position()).isEqualTo(prefixLength + packed.length);
  }

  @Test
  void readBatchUsing512VectorLeavesTrailingBytesUnconsumed() throws IOException {
    assumeVectorSupport();
    int bitWidth = 8;
    int valueCount = 512;
    int[] values = VectorTestData.valuesFor(bitWidth, valueCount);
    byte[] packed = VectorTestData.packLittleEndian(bitWidth, values);
    byte trailingMarker = (byte) 0xA5;
    byte[] withTrailing = Arrays.copyOf(packed, packed.length + 3);
    Arrays.fill(withTrailing, packed.length, withTrailing.length, trailingMarker);
    ByteBufferInputStream in = streamOf(withTrailing);
    int[] actual = new int[valueCount];

    ParquetReadRouter.readBatchUsing512Vector(bitWidth, in, valueCount, actual);

    assertValues(values, actual);
    assertThat(in.position()).isEqualTo(packed.length);
    assertThat(in.read()).isEqualTo(trailingMarker & 0xFF);
  }

  @Test
  void zeroCountReadsDoNotConsumeInputOrChangeOutput() throws IOException {
    byte[] packed = new byte[32];
    int[] actual = {17, -3, 42};

    ByteBufferInputStream batchIn = streamOf(packed);
    ParquetReadRouter.readBatch(8, batchIn, 0, actual);
    assertThat(batchIn.position()).isZero();
    assertThat(actual).containsExactly(17, -3, 42);

    ByteBufferInputStream vectorIn = streamOf(packed);
    ParquetReadRouter.readBatchUsing512Vector(8, vectorIn, 0, actual);
    assertThat(vectorIn.position()).isZero();
    assertThat(actual).containsExactly(17, -3, 42);

    ByteBufferInputStream routedIn = streamOf(packed);
    ParquetReadRouter.read(8, routedIn, 0, actual);
    assertThat(routedIn.position()).isZero();
    assertThat(actual).containsExactly(17, -3, 42);
  }

