  @Test
  void getSupportVectorFromCPUFlagsReturnsNoneForNonLinuxOperatingSystems() {
    String originalOsName = System.getProperty("os.name");
    try {
      System.setProperty("os.name", "Windows 11");
      assertThat(ParquetReadRouter.getSupportVectorFromCPUFlags()).isEqualTo(VectorSupport.NONE);
    } finally {
      restoreSystemProperty("os.name", originalOsName);
    }
  }

  @Test
  void getSupportVectorFromCPUFlagsReturnsNoneWhenOsNameIsUnavailable() {
    String originalOsName = System.getProperty("os.name");
    try {
      System.clearProperty("os.name");
      assertThat(ParquetReadRouter.getSupportVectorFromCPUFlags()).isEqualTo(VectorSupport.NONE);
    } finally {
      restoreSystemProperty("os.name", originalOsName);
    }
  }

  @Test
  void getSupportVectorFromCPUFlagsDetectsAvx512FlagsOnLinux() throws IOException {
    String osName = System.getProperty("os.name", "");
    assumeTrue(osName.toLowerCase().startsWith("linux"), "Linux /proc/cpuinfo is required");
    Path cpuInfo = Path.of("/proc/cpuinfo");
    assumeTrue(Files.isReadable(cpuInfo), "/proc/cpuinfo is not readable");
    boolean hasRequiredFlags = Files.readAllLines(cpuInfo, StandardCharsets.UTF_8).stream()
        .filter(line -> line.startsWith("flags"))
        .anyMatch(line -> line.contains("avx512vbmi") && line.contains("avx512_vbmi2"));
    assumeTrue(hasRequiredFlags, "CPU does not expose AVX-512 VBMI/VBMI2");

    assertThat(ParquetReadRouter.getSupportVectorFromCPUFlags()).isEqualTo(VectorSupport.VECTOR_512);
  }

  private static void restoreSystemProperty(String name, String value) {
    if (value == null) {
      System.clearProperty(name);
    } else {
      System.setProperty(name, value);
    }
  }
