import org.junit.jupiter.api.Test;

public class MaskModeTest {

  @Test
  public void exposesAllSupportedModes() {
    assertThat(MaskMode.values())
        .containsExactly(MaskMode.NULLIFY, MaskMode.HASH, MaskMode.REDACT);
  }

  @Test
  public void modeTextIsLowerCaseName() {
    assertThat(Arrays.stream(MaskMode.values()).map(MaskMode::getMode).collect(Collectors.toList()))
        .containsExactly("nullify", "hash", "redact");
  }

  @Test
  public void modeTextIsNotNull() {
    for (MaskMode mode : MaskMode.values()) {
      assertThat(mode.getMode()).isNotNull().isNotEmpty();
    }
  }

  @Test
  public void modeTextIsAccessibleThroughPublicFieldContract() {
    // getMode() is the only way to obtain the serialized name used by the rewriter
    assertThat(MaskMode.NULLIFY.getMode()).isEqualTo("nullify");
    assertThat(MaskMode.HASH.getMode()).isEqualTo("hash");
    assertThat(MaskMode.REDACT.getMode()).isEqualTo("redact");
  }

  @Test
  public void valueOfResolvesByEnumName() {
    assertThat(MaskMode.valueOf("NULLIFY")).isSameAs(MaskMode.NULLIFY);
    assertThat(MaskMode.valueOf("HASH")).isSameAs(MaskMode.HASH);
    assertThat(MaskMode.valueOf("REDACT")).isSameAs(MaskMode.REDACT);
  }

  @Test
  public void valueOfRejectsModeTextInsteadOfEnumName() {
    assertThatThrownBy(() -> MaskMode.valueOf("nullify")).isInstanceOf(IllegalArgumentException.class);
  }

  @Test
  public void valueOfRejectsUnknownName() {
    assertThatThrownBy(() -> MaskMode.valueOf("UNKNOWN")).isInstanceOf(IllegalArgumentException.class);
  }
}
