    assertThat(options.getMaskColumns()).containsEntry("name", MaskMode.NULLIFY);
    assertThat(options.getRenameColumns()).containsEntry("old", "new");
    assertThat(options.getEncryptColumns()).containsExactly("secret");
    assertThat(options.getFileEncryptionProperties()).isSameAs(encryption);
    assertThat(options.getIndexCacheStrategy()).isEqualTo(IndexCache.CacheStrategy.PREFETCH_BLOCK);
