public class ParquetRewriterTest {

  private static final byte[] KEY = "0123456789abcdef".getBytes();

  private static final MessageType SCHEMA = MessageTypeParser.parseMessageType("message test {\n"
      + "  required int32 id;\n"
      + "  optional binary name (UTF8);\n"
      + "  optional group contact {\n"
      + "    optional binary email (UTF8);\n"
      + "    optional int64 phone;\n"
      + "  }\n"
      + "}");

  private static final MessageType LEFT_SCHEMA = MessageTypeParser.parseMessageType("message left {\n"
      + "  required int32 id;\n"
      + "  optional binary name (UTF8);\n"
      + "}");

  private static final MessageType RIGHT_SCHEMA = MessageTypeParser.parseMessageType("message right {\n"
      + "  required int32 id;\n"
      + "  optional binary score (UTF8);\n"
      + "}");

  @TempDir
  java.nio.file.Path tempDir;

  private final Configuration conf = new Configuration();

  private Path path(String name) {
    return new Path(tempDir.resolve(name).toUri());
  }

  private static SimpleGroupFactory factory(MessageType schema) {
    return new SimpleGroupFactory(schema);
  }

  private static Group row(SimpleGroupFactory factory, int id, String name, String email, Long phone) {
    Group group = factory.newGroup().append("id", id);
    if (name != null) {
      group.append("name", name);
    }
    if (email != null || phone != null) {
      Group contact = group.addGroup("contact");
      if (email != null) {
        contact.append("email", email);
      }
      if (phone != null) {
        contact.append("phone", phone);
      }
    }
    return group;
  }

  private Path writeFile(String name, MessageType schema, List<Group> groups) throws IOException {
    return writeFile(name, schema, groups, Collections.emptyMap(), null, -1L);
  }

  private Path writeFile(
      String name,
      MessageType schema,
      List<Group> groups,
      Map<String, String> extraMetaData,
      CompressionCodecName codec,
      long rowGroupSize)
      throws IOException {
    Path file = path(name);
    ExampleParquetWriter.Builder builder = ExampleParquetWriter.builder(file)
        .withType(schema)
        .withConf(conf)
        .withExtraMetaData(extraMetaData);
    if (codec != null) {
      builder.withCompressionCodec(codec);
    }
    if (rowGroupSize > 0) {
      builder.withRowGroupSize(rowGroupSize);
      builder.withPageSize(ParquetProperties.DEFAULT_PAGE_SIZE);
    }
    try (org.apache.parquet.hadoop.ParquetWriter<Group> writer = builder.build()) {
      for (Group group : groups) {
        writer.write(group);
      }
    }
    return file;
  }

  private List<Group> readAll(Path file) throws IOException {
    List<Group> groups = new ArrayList<>();
    try (ParquetReader<Group> reader =
        ParquetReader.builder(new GroupReadSupport(), file).withConf(conf).build()) {
      Group group;
      while ((group = reader.read()) != null) {
        groups.add(group);
      }
    }
    return groups;
  }

  private ParquetMetadata footer(Path file) throws IOException {
    return ParquetFileReader.readFooter(conf, file, ParquetMetadataConverter.NO_FILTER);
  }

