  }

  private List<Group> rightRows(String score) {
    SimpleGroupFactory factory = factory(RIGHT_SCHEMA);
    return Arrays.asList(
        factory.newGroup().append("id", 1).append("score", score + "-1"),
        factory.newGroup().append("id", 2).append("score", score + "-2"));
  }

  @Test
  public void joinsAdditionalColumnsFromOtherFiles() throws IOException {
    Path left = writeFile("left.parquet", LEFT_SCHEMA, leftRows());
    Path right = writeFile("right.parquet", RIGHT_SCHEMA, rightRows("score"));
    Path out = path("out.parquet");

    try (ParquetRewriter rewriter = new ParquetRewriter(new RewriteOptions.Builder(
            conf, Collections.singletonList(left), Collections.singletonList(right), out)
        .build())) {
      rewriter.processBlocks();
    }

    MessageType outSchema = footer(out).getFileMetaData().getSchema();
    assertThat(outSchema.getFields()).extracting(t -> t.getName()).containsExactly("id", "name", "score");
    List<Group> rows = readAll(out);
    assertThat(rows).hasSize(2);
    assertThat(rows.get(0).getString("name", 0)).isEqualTo("alice");
    assertThat(rows.get(0).getString("score", 0)).isEqualTo("score-1");
    assertThat(rows.get(1).getString("score", 0)).isEqualTo("score-2");
  }

  @Test
  public void rejectsJoinsWithMismatchingRowCounts() throws IOException {
    Path left = writeFile("left.parquet", LEFT_SCHEMA, leftRows());
    Path right = writeFile("right.parquet", RIGHT_SCHEMA, Collections.singletonList(
        factory(RIGHT_SCHEMA).newGroup().append("id", 1).append("score", "s")));
    Path out = path("out.parquet");
    RewriteOptions options = new RewriteOptions.Builder(
            conf, Collections.singletonList(left), Collections.singletonList(right), out)
        .build();

    assertThatThrownBy(() -> new ParquetRewriter(options))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessageContaining("The number of rows in each block must match!");
  }

  @Test
  public void keepsInputColumnsWhenNotOverwritingWithJoinColumns() throws IOException {
    Path left = writeFile("left.parquet", LEFT_SCHEMA, leftRows());
    // right uses the same column names as the left file but with different values
    Path right = writeFile("right.parquet", LEFT_SCHEMA, Arrays.asList(
        factory(LEFT_SCHEMA).newGroup().append("id", 10).append("name", "from-right-1"),
        factory(LEFT_SCHEMA).newGroup().append("id", 20).append("name", "from-right-2")));
    Path out = path("out.parquet");

    try (ParquetRewriter rewriter = new ParquetRewriter(new RewriteOptions.Builder(
            conf, Collections.singletonList(left), Collections.singletonList(right), out)
        .build())) {
      rewriter.processBlocks();
    }

    List<Group> rows = readAll(out);
    assertThat(rows).extracting(g -> g.getString("name", 0)).containsExactly("alice", "bob");
    assertThat(rows).extracting(g -> g.getInteger("id", 0)).containsExactly(1, 2);
  }

  @Test
  public void overwritesInputColumnsWithJoinColumnsWhenRequested() throws IOException {
    Path left = writeFile("left.parquet", LEFT_SCHEMA, leftRows());
    Path right = writeFile("right.parquet", LEFT_SCHEMA, Arrays.asList(
        factory(LEFT_SCHEMA).newGroup().append("id", 10).append("name", "from-right-1"),
        factory(LEFT_SCHEMA).newGroup().append("id", 20).append("name", "from-right-2")));
    Path out = path("out.parquet");

    try (ParquetRewriter rewriter = new ParquetRewriter(new RewriteOptions.Builder(
            conf, Collections.singletonList(left), Collections.singletonList(right), out)
        .overwriteInputWithJoinColumns(true)
        .build())) {
      rewriter.processBlocks();
    }

    List<Group> rows = readAll(out);
    assertThat(rows).extracting(g -> g.getString("name", 0)).containsExactly("from-right-1", "from-right-2");
    assertThat(rows).extracting(g -> g.getInteger("id", 0)).containsExactly(10, 20);
  }

  @Test
  public void keepsJoinFileMetadataUnlessIgnored() throws IOException {
    Path left = writeFile("left.parquet", LEFT_SCHEMA, leftRows());
    Path right = writeFile(
        "right.parquet",
        RIGHT_SCHEMA,
        rightRows("score"),
        Collections.singletonMap("right.key", "right.value"),
        null,
        -1L);
    Path out = path("out.parquet");
    Path outIgnored = path("out-ignored.parquet");

    try (ParquetRewriter rewriter = new ParquetRewriter(new RewriteOptions.Builder(
            conf, Collections.singletonList(left), Collections.singletonList(right), out)
        .build())) {
      rewriter.processBlocks();
    }
    try (ParquetRewriter rewriter = new ParquetRewriter(new RewriteOptions.Builder(
            conf, Collections.singletonList(left), Collections.singletonList(right), outIgnored)
        .ignoreJoinFilesMetadata(true)
        .build())) {
      rewriter.processBlocks();
    }

    assertThat(footer(out).getFileMetaData().getKeyValueMetaData())
        .containsEntry("right.key", "right.value");
    assertThat(footer(outIgnored).getFileMetaData().getKeyValueMetaData())
        .doesNotContainKey("right.key");
  }

  @Test
  public void encryptsColumns() throws IOException {
    Path in = writeFile("in.parquet", SCHEMA, sampleRows());
    Path out = path("out.parquet");
    Map<ColumnPath, ColumnEncryptionProperties> encryptedColumns = new HashMap<>();
    encryptedColumns.put(ColumnPath.get("name"), ColumnEncryptionProperties.builder("name").build());
    FileEncryptionProperties encryptionProperties =
        FileEncryptionProperties.builder(KEY).withEncryptedColumns(encryptedColumns).build();

    try (ParquetRewriter rewriter = new ParquetRewriter(new RewriteOptions.Builder(conf, in, out)
        .encrypt(Collections.singletonList("name"))
        .encryptionProperties(encryptionProperties)
        .build())) {
      rewriter.processBlocks();
    }

    ParquetMetadata outFooter = footer(out);
    for (ColumnChunkMetaData column : outFooter.getBlocks().get(0).getColumns()) {
      assertThat(column.isEncrypted())
          .as("column %s encryption", column.getPath().toDotString())
          .isEqualTo(column.getPath().equals(ColumnPath.get("name")));
    }

    List<Group> rows = new ArrayList<>();
    try (ParquetReader<Group> reader = ParquetReader.builder(new GroupReadSupport(), out)
        .withConf(conf)
        .withDecryption(FileDecryptionProperties.builder()
            .withFooterKey(KEY)
            .build())
        .build()) {
      Group group;
      while ((group = reader.read()) != null) {
        rows.add(group);
      }
    }
    assertThat(rows).hasSize(3);
    assertThat(rows.get(0).getString("name", 0)).isEqualTo("alice");
  }

  @Test
  public void legacyConstructorMasksColumnsAndOverridesCreatedBy() throws IOException {
    Path in = writeFile("in.parquet", SCHEMA, sampleRows());
    Path out = path("out.parquet");
    ParquetMetadata meta = footer(in);
    MessageType schema = meta.getFileMetaData().getSchema();
    ParquetFileWriter writer = new ParquetFileWriter(conf, schema, out, ParquetFileWriter.Mode.CREATE);
    writer.start();

    try (TransParquetFileReader reader = new TransParquetFileReader(
        HadoopInputFile.fromPath(in, conf), ParquetReadOptions.builder(conf).build())) {
      ParquetRewriter rewriter = new ParquetRewriter(
          reader,
          writer,
          meta,
          schema,
          "custom-created-by",
          CompressionCodecName.UNCOMPRESSED,
          Collections.singletonList("name"),
          MaskMode.NULLIFY);
      rewriter.processBlocks();
      rewriter.close();
    }

    List<Group> rows = readAll(out);
    assertThat(rows).hasSize(3);
    assertThat(rows).allSatisfy(g -> assertThat(g.getFieldRepetitionCount("name")).isZero());
    assertThat(rows.get(0).getGroup("contact", 0).getString("email", 0)).isEqualTo("alice@example.com");
    assertThat(footer(out).getFileMetaData().getKeyValueMetaData())
        .containsEntry(ParquetRewriter.ORIGINAL_CREATED_BY_KEY, "custom-created-by");
  }
}
