public class ParquetRewriterTest {

  private static final byte[] KEY = "0123456789abcdef".getBytes();

  private static final MessageType SCHEMA = MessageTypeParser.parseMessageType("message test {\n"
      + "  required int32 id;\n"
      + "  optional binary name (UTF8);\n"
      + "  optional group contact {\n"
      + "    optional binary email (UTF8);\n"
      + "    optional int64 phone;\n"
      + "  }\n"
      + "}");

  private static final MessageType LEFT_SCHEMA = MessageTypeParser.parseMessageType("message left {\n"
      + "  required int32 id;\n"
      + "  optional binary name (UTF8);\n"
      + "}");

  private static final MessageType RIGHT_SCHEMA = MessageTypeParser.parseMessageType("message right {\n"
      + "  required int32 id;\n"
      + "  optional binary score (UTF8);\n"
      + "}");

  @TempDir
  java.nio.file.Path tempDir;

  private final Configuration conf = new Configuration();

  private Path path(String name) {
    return new Path(tempDir.resolve(name).toUri());
  }

  private static SimpleGroupFactory factory(MessageType schema) {
    return new SimpleGroupFactory(schema);
  }

  private static Group row(SimpleGroupFactory factory, int id, String name, String email, Long phone) {
    Group group = factory.newGroup().append("id", id);
    if (name != null) {
      group.append("name", name);
    }
    if (email != null || phone != null) {
      Group contact = group.addGroup("contact");
      if (email != null) {
        contact.append("email", email);
      }
      if (phone != null) {
        contact.append("phone", phone);
      }
    }
    return group;
  }

  private Path writeFile(String name, MessageType schema, List<Group> groups) throws IOException {
    return writeFile(name, schema, groups, Collections.emptyMap(), null, -1L);
  }

  private Path writeFile(
      String name,
      MessageType schema,
      List<Group> groups,
      Map<String, String> extraMetaData,
      CompressionCodecName codec,
      long rowGroupSize)
      throws IOException {
    Path file = path(name);
    ExampleParquetWriter.Builder builder = ExampleParquetWriter.builder(file)
        .withType(schema)
        .withConf(conf)
        .withExtraMetaData(extraMetaData);
    if (codec != null) {
      builder.withCompressionCodec(codec);
    }
    if (rowGroupSize > 0) {
      builder.withRowGroupSize(rowGroupSize);
      builder.withPageSize(ParquetProperties.DEFAULT_PAGE_SIZE);
    }
    try (org.apache.parquet.hadoop.ParquetWriter<Group> writer = builder.build()) {
      for (Group group : groups) {
        writer.write(group);
      }
    }
    return file;
  }

  private List<Group> readAll(Path file) throws IOException {
    List<Group> groups = new ArrayList<>();
    try (ParquetReader<Group> reader =
        ParquetReader.builder(new GroupReadSupport(), file).withConf(conf).build()) {
      Group group;
      while ((group = reader.read()) != null) {
        groups.add(group);
      }
    }
    return groups;
  }

  private ParquetMetadata footer(Path file) throws IOException {
    return ParquetFileReader.readFooter(conf, file, ParquetMetadataConverter.NO_FILTER);
  }

  private static List<Group> sampleRows() {
    SimpleGroupFactory factory = factory(SCHEMA);
    return Arrays.asList(
        row(factory, 1, "alice", "alice@example.com", 11L),
        row(factory, 2, "bob", null, null),
        row(factory, 3, null, "carol@example.com", 33L));
  }

  private static List<Group> otherSampleRows() {
    SimpleGroupFactory factory = factory(SCHEMA);
    return Arrays.asList(
        row(factory, 4, "dave", "dave@example.com", 44L), row(factory, 5, "erin", null, 55L));
  }

  @Test
  public void mergesMultipleInputFiles() throws IOException {
    Path in1 = writeFile("in1.parquet", SCHEMA, sampleRows());
    Path in2 = writeFile("in2.parquet", SCHEMA, otherSampleRows());
    Path out = path("out.parquet");

    try (ParquetRewriter rewriter = new ParquetRewriter(
        new RewriteOptions.Builder(conf, Arrays.asList(in1, in2), out).build())) {
      rewriter.processBlocks();
    }

    List<Group> rows = readAll(out);
    assertThat(rows).hasSize(5);
    assertThat(rows).extracting(g -> g.getInteger("id", 0)).containsExactly(1, 2, 3, 4, 5);
    assertThat(rows.get(0).getString("name", 0)).isEqualTo("alice");
    assertThat(rows.get(4).getString("name", 0)).isEqualTo("erin");
    assertThat(footer(out).getFileMetaData().getSchema()).isEqualTo(SCHEMA);
    assertThat(footer(out).getBlocks()).hasSize(2);
  }

  @Test
  public void keepsOneRowGroupPerInputRowGroup() throws IOException {
    SimpleGroupFactory factory = factory(SCHEMA);
    List<Group> manyRows = new ArrayList<>();
    for (int i = 0; i < 200; i++) {
      manyRows.add(row(factory, i, "name-" + i + "-padding-padding-padding", null, (long) i));
    }
    Path in = writeFile("in.parquet", SCHEMA, manyRows, Collections.emptyMap(), null, 2 * 1024L);
    assertThat(footer(in).getBlocks()).hasSizeGreaterThan(1);
    int inputBlocks = footer(in).getBlocks().size();
    Path out = path("out.parquet");

    try (ParquetRewriter rewriter =
        new ParquetRewriter(new RewriteOptions.Builder(conf, in, out).build())) {
      rewriter.processBlocks();
    }

    ParquetMetadata outFooter = footer(out);
    assertThat(outFooter.getBlocks()).hasSize(inputBlocks);
    long inputRows = footer(in).getBlocks().stream().mapToLong(BlockMetaData::getRowCount).sum();
    assertThat(outFooter.getBlocks().stream().mapToLong(BlockMetaData::getRowCount).sum())
        .isEqualTo(inputRows);
    assertThat(readAll(out)).hasSize(manyRows.size());
  }

