    MessageType outSchema = footer(out).getFileMetaData().getSchema();
    assertThat(outSchema.getFields()).extracting(t -> t.getName()).containsExactly("id", "contact");
    assertThat(outSchema.getType("contact").asGroupType().getFields())
        .extracting(t -> t.getName())
        .containsExactly("email", "phone");

    List<Group> rows = readAll(out);
    assertThat(rows).hasSize(3);
    assertThat(rows.get(0).getInteger("id", 0)).isEqualTo(1);
    assertThat(rows.get(0).getGroup("contact", 0).getString("email", 0)).isEqualTo("alice@example.com");
  }

  @Test
  public void prunesNestedColumn() throws IOException {
    Path in = writeFile("in.parquet", SCHEMA, sampleRows());
