    assertThat(rows.get(0).getGroup("contact", 0).getFieldRepetitionCount("email"))
        .isZero();
    assertThat(rows.get(0).getGroup("contact", 0).getLong("phone", 0)).isEqualTo(11L);
    assertThat(rows.get(0).getString("name", 0)).isEqualTo("alice");
  }

  @Test
  public void cannotNullifyRequiredColumn() throws IOException {
    Path in = writeFile("in.parquet", SCHEMA, sampleRows());
    Path out = path("out.parquet");
    RewriteOptions options = new RewriteOptions.Builder(conf, in, out)
        .mask(Collections.singletonMap("id", MaskMode.NULLIFY))
        .build();

    ParquetRewriter rewriter = new ParquetRewriter(options);
