  @Test
  public void onlyNullifyMaskingIsSupported() throws IOException {
    Path in = writeFile("in.parquet", SCHEMA, sampleRows());
    Path out = path("out.parquet");

    for (MaskMode mode : Arrays.asList(MaskMode.HASH, MaskMode.REDACT)) {
      RewriteOptions options = new RewriteOptions.Builder(conf, in, out)
          .mask(Collections.singletonMap("name", mode))
          .build();
      ParquetRewriter rewriter = new ParquetRewriter(options);
      assertThatThrownBy(rewriter::processBlocks)
          .as("mask mode %s", mode)
          .isInstanceOf(UnsupportedOperationException.class)
          .hasMessageContaining("Only nullify is supported for now");
    }
  }

  @Test
  public void renamesPrimitiveColumn() throws IOException {
    Path in = writeFile("in.parquet", SCHEMA, sampleRows());
    Path out = path("out.parquet");

    try (ParquetRewriter rewriter = new ParquetRewriter(new RewriteOptions.Builder(conf, in, out)
        .renameColumns(Collections.singletonMap("name", "full_name"))
        .build())) {
      rewriter.processBlocks();
    }

