  public void renamesGroupColumn() throws IOException {
    Path in = writeFile("in.parquet", SCHEMA, sampleRows());
    Path out = path("out.parquet");

    try (ParquetRewriter rewriter = new ParquetRewriter(new RewriteOptions.Builder(conf, in, out)
        .renameColumns(Collections.singletonMap("contact", "details"))
        .build())) {
      rewriter.processBlocks();
    }

    MessageType outSchema = footer(out).getFileMetaData().getSchema();
    assertThat(outSchema.getFields()).extracting(t -> t.getName()).containsExactly("id", "name", "details");
    assertThat(outSchema.getType("details").asGroupType().getFields())
        .extracting(t -> t.getName())
        .containsExactly("email", "phone");
    List<Group> rows = readAll(out);
    assertThat(rows.get(0).getGroup("details", 0).getString("email", 0)).isEqualTo("alice@example.com");
  }

  @Test
  public void rejectsRenamingUnknownColumn() throws IOException {
    Path in = writeFile("in.parquet", SCHEMA, sampleRows());
    Path out = path("out.parquet");
    RewriteOptions options = new RewriteOptions.Builder(conf, in, out)
        .renameColumns(Collections.singletonMap("unknown", "renamed"))
        .build();

    assertThatThrownBy(() -> new ParquetRewriter(options))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessageContaining("Column to rename 'unknown' is not found in input files schema");
  }

  @Test
  public void rejectsRenamingToAnExistingColumn() throws IOException {
    Path in = writeFile("in.parquet", SCHEMA, sampleRows());
    Path out = path("out.parquet");
    RewriteOptions options = new RewriteOptions.Builder(conf, in, out)
        .renameColumns(Collections.singletonMap("name", "id"))
        .build();

    assertThatThrownBy(() -> new ParquetRewriter(options))
        .isInstanceOf(IllegalArgumentException.class)
