    encryptedColumns.put(ColumnPath.get("name"), ColumnEncryptionProperties.builder("name").build());
    FileEncryptionProperties encryptionProperties =
        FileEncryptionProperties.builder(KEY).withEncryptedColumns(encryptedColumns).build();

    try (ParquetRewriter rewriter = new ParquetRewriter(new RewriteOptions.Builder(conf, in, out)
        .encrypt(Collections.singletonList("name"))
        .encryptionProperties(encryptionProperties)
