    }

    ParquetMetadata outFooter = footer(out);
    for (ColumnChunkMetaData column : outFooter.getBlocks().get(0).getColumns()) {
      assertThat(column.isEncrypted())
          .as("column %s encryption", column.getPath().toDotString())
          .isEqualTo(column.getPath().equals(ColumnPath.get("name")));
    }

    List<Group> rows = new ArrayList<>();
    try (ParquetReader<Group> reader = ParquetReader.builder(new GroupReadSupport(), out)
        .withConf(conf)
        .withDecryption(FileDecryptionProperties.builder()
            .withFooterKey(KEY)
            .build())
