public void encryptsColumns() throws IOException {
  Path in = writeFile("in.parquet", SCHEMA, sampleRows());
  Path out = path("out.parquet");
  Map<ColumnPath, ColumnEncryptionProperties> encryptedColumns = new HashMap<>();
  encryptedColumns.put(ColumnPath.get("name"), ColumnEncryptionProperties.builder("name").build());
  FileEncryptionProperties encryptionProperties = FileEncryptionProperties.builder(KEY)
      .withEncryptedColumns(encryptedColumns)
      .withPlaintextFooter()
      .build();

  try (ParquetRewriter rewriter = new ParquetRewriter(new RewriteOptions.Builder(conf, in, out)
      .encrypt(Collections.singletonList("name"))
      .encryptionProperties(encryptionProperties)
      .build())) {
    rewriter.processBlocks();
  }

  // the column chunk is marked as encrypted in the (plaintext) footer, so its metadata can only be
  // deserialized with the correct key
  assertThatThrownBy(() -> footer(out)).hasMessageContaining("No keys available");

  ParquetMetadata outFooter = encryptedFooter(out, KEY);
  assertThat(outFooter.getFileMetaData().getSchema()).isEqualTo(SCHEMA);
  assertThat(outFooter.getBlocks().get(0).getColumns())
      .extracting(c -> c.getPath().toDotString())
      .containsExactly("id", "name", "contact.email", "contact.phone");

  List<Group> rows = new ArrayList<>();
  try (ParquetReader<Group> reader = ParquetReader.builder(new GroupReadSupport(), out)
      .withConf(conf)
      .withDecryption(FileDecryptionProperties.builder()
          .withFooterKey(KEY)
          .build())
      .build()) {
    Group group;
    while ((group = reader.read()) != null) {
      rows.add(group);
    }
  }
  assertThat(rows).hasSize(3);
  assertThat(rows.get(0).getString("name", 0)).isEqualTo("alice");
}

