package org.apache.parquet.thrift.projection;

import static org.assertj.core.api.Assertions.assertThat;

import org.apache.parquet.thrift.struct.ThriftField;
import org.apache.parquet.thrift.struct.ThriftField.Requirement;
import org.apache.parquet.thrift.struct.ThriftType;
import org.junit.jupiter.api.Test;

class FieldsPathTest {

  private static ThriftField field(String name, int id, ThriftType type) {
    return new ThriftField(name, (short) id, Requirement.OPTIONAL, type);
  }

  @Test
  void emptyPathHasEmptyStringRepresentation() {
    FieldsPath path = new FieldsPath();

    assertThat(path.toString()).isEmpty();
    assertThat(path.toDelimitedString("/")).isEmpty();
  }

  @Test
  void pushesCreateIndependentImmutablePaths() {
    ThriftField first = field("first", 1, new ThriftType.I32Type());
    ThriftField second = field("second", 2, new ThriftType.StringType());

    FieldsPath empty = new FieldsPath();
    FieldsPath firstPath = empty.push(first);
    FieldsPath secondPath = firstPath.push(second);

    assertThat(empty.toString()).isEmpty();
    assertThat(firstPath.toString()).isEqualTo("first");
    assertThat(secondPath.toString()).isEqualTo("first.second");
    assertThat(firstPath.toDelimitedString("::")).isEqualTo("first");
    assertThat(secondPath.toDelimitedString("::")).isEqualTo("first::second");
  }

  @Test
  void usesKeyAndValueSegmentsForMapKeyAndValueFields() {
    ThriftField key = field("actual-key-name", 1, new ThriftType.StringType());
    ThriftField value = field("actual-value-name", 2, new ThriftType.I64Type());
    ThriftField map = field("mapping", 3, new ThriftType.MapType(key, value));

    FieldsPath mapPath = new FieldsPath().push(map);
    FieldsPath keyPath = mapPath.push(key);
    FieldsPath valuePath = mapPath.push(value);

    assertThat(keyPath.toString()).isEqualTo("mapping.key");
    assertThat(valuePath.toString()).isEqualTo("mapping.value");
    assertThat(keyPath.toDelimitedString("/")).isEqualTo("mapping/key");
    assertThat(valuePath.toDelimitedString("/")).isEqualTo("mapping/value");
  }

  @Test
  void ordinaryNestedFieldsKeepTheirNames() {
    ThriftField outer = field("outer", 1, new ThriftType.I32Type());
    ThriftField inner = field("inner", 2, new ThriftType.StringType());

    assertThat(new FieldsPath().push(outer).push(inner).toString()).isEqualTo("outer.inner");
  }
}
