package org.apache.parquet.thrift.projection;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.apache.parquet.glob.WildcardPath;
import org.apache.parquet.thrift.struct.ThriftField;
import org.apache.parquet.thrift.struct.ThriftField.Requirement;
import org.apache.parquet.thrift.struct.ThriftType;
import org.junit.jupiter.api.Test;

class StrictFieldProjectionFilterTest {

  private static FieldsPath path(String... names) {
    FieldsPath result = new FieldsPath();
    for (int i = 0; i < names.length; i++) {
      result = result.push(new ThriftField(
          names[i], (short) (i + 1), Requirement.OPTIONAL, new ThriftType.I32Type()));
    }
    return result;
  }

  @Test
  void parsesSemicolonDelimitedPatternsAndIgnoresEmptyItems() {
    assertThat(StrictFieldProjectionFilter.parseSemicolonDelimitedString("a;;b;"))
        .containsExactly("a", "b");
    assertThat(StrictFieldProjectionFilter.parseSemicolonDelimitedString("root.child"))
        .containsExactly("root.child");
  }

  @Test
  void rejectsSemicolonDelimitedStringsWithoutAnyPattern() {
    assertThatThrownBy(() -> StrictFieldProjectionFilter.fromSemicolonDelimitedString(";;"))
        .isInstanceOf(ThriftProjectionException.class)
        .hasMessageContaining("contains 0 glob strings");
  }

  @Test
  void requiresEveryBraceExpansionToMatchAColumn() {
    StrictFieldProjectionFilter filter =
        StrictFieldProjectionFilter.fromSemicolonDelimitedString("root.{kept,missing}");

    assertThat(filter.keep(path("root", "kept"))).isTrue();

    assertThatThrownBy(filter::assertNoUnmatchedPatterns)
        .isInstanceOf(ThriftProjectionException.class)
        .hasMessageContaining("did not match any columns")
        .hasMessageContaining("Pattern: 'root.{kept,missing}'")
        .hasMessageContaining("root.missing");
  }

  @Test
  void acceptsAllExpansionsAfterTheyHaveMatched() {
    StrictFieldProjectionFilter filter =
        StrictFieldProjectionFilter.fromSemicolonDelimitedString("root.{a,b}");

    assertThat(filter.keep(path("root", "a"))).isTrue();
    assertThat(filter.keep(path("root", "b"))).isTrue();
    assertThat(filter.keep(path("other", "a"))).isFalse();

    filter.assertNoUnmatchedPatterns();
  }

  @Test
  void wildcardPatternsMatchDescendantsAndTrackTheirMatch() {
    StrictFieldProjectionFilter filter =
        StrictFieldProjectionFilter.fromSemicolonDelimitedString("root.*");

    assertThat(filter.keep(path("root", "child"))).isTrue();
    assertThat(filter.keep(path("root", "child", "leaf"))).isTrue();
    assertThat(filter.keep(path("other", "child"))).isFalse();

    filter.assertNoUnmatchedPatterns();
  }

  @Test
  void reportsAnUnmatchedWildcardPattern() {
    StrictFieldProjectionFilter filter =
        new StrictFieldProjectionFilter(Collections.singletonList("root.*"));

    assertThat(filter.keep(path("other", "child"))).isFalse();

    assertThatThrownBy(filter::assertNoUnmatchedPatterns)
        .isInstanceOf(ThriftProjectionException.class)
        .hasMessageContaining("Pattern: 'root.*' (when expanded to 'root.*')");
  }

  @Test
  void emptyPatternListKeepsNoColumnsButHasNothingUnmatched() {
    StrictFieldProjectionFilter filter = new StrictFieldProjectionFilter(Collections.emptyList());

    assertThat(filter.keep(path("a"))).isFalse();
    filter.assertNoUnmatchedPatterns();
  }

  @Test
  void warnsWhenDifferentGlobPatternsBothMatchTheSameColumn() {
    List<String> warnings = new ArrayList<String>();
    StrictFieldProjectionFilter filter =
        new StrictFieldProjectionFilter(Arrays.asList("root.*", "*.child")) {
          @Override
          protected void warn(String warning) {
            warnings.add(warning);
          }
        };

    assertThat(filter.keep(path("root", "child"))).isTrue();
    filter.assertNoUnmatchedPatterns();

    assertThat(warnings).singleElement().asString().contains("matched more than one glob path pattern");
  }

  @Test
  void wildcardPathStatusRemembersAnySuccessfulMatch() {
    WildcardPath wildcardPath = new WildcardPath("root.*", "root.child", '.');
    StrictFieldProjectionFilter.WildcardPathStatus status =
        new StrictFieldProjectionFilter.WildcardPathStatus(wildcardPath);

    assertThat(status.getWildcardPath()).isSameAs(wildcardPath);
    assertThat(status.hasMatched()).isFalse();
    assertThat(status.matches("root.child.leaf")).isTrue();
    assertThat(status.hasMatched()).isTrue();
    assertThat(status.matches("other.child")).isFalse();
    assertThat(status.hasMatched()).isTrue();
  }
}
