import org.junit.jupiter.api.Test;

class ProtocolEventsAmenderTest {

  private static ThriftField field(String name, int id, Requirement requirement, ThriftType type) {
    return new ThriftField(name, (short) id, requirement, type);
  }

  private static ThriftType.StructType struct(ThriftField... fields) {
    return new ThriftType.StructType(Arrays.asList(fields), StructOrUnionType.STRUCT);
  }

  private static TProtocol structBegin() {
    return new ParquetProtocol("readStructBegin()") {
      @Override
      public TStruct readStructBegin() {
        return new TStruct("test-struct");
      }
    };
  }

  private static TProtocol structEnd() {
    return new ParquetProtocol("readStructEnd()") {
      @Override
      public void readStructEnd() {}
    };
  }

  private static TProtocol listBegin(final int size) {
    return new ParquetProtocol("readListBegin()") {
      @Override
      public TList readListBegin() {
        return new TList(TType.STRUCT, size);
      }
    };
  }

  private static TProtocol listEnd() {
    return new ParquetProtocol("readListEnd()") {
      @Override
      public void readListEnd() {}
    };
  }

  private static TProtocol setBegin(final int size) {
    return new ParquetProtocol("readSetBegin()") {
      @Override
      public TSet readSetBegin() {
        return new TSet(TType.STRUCT, size);
      }
    };
  }

  private static TProtocol setEnd() {
    return new ParquetProtocol("readSetEnd()") {
      @Override
      public void readSetEnd() {}
    };
  }

  private static TProtocol mapBegin(final int size) {
    return new ParquetProtocol("readMapBegin()") {
      @Override
      public TMap readMapBegin() {
        return new TMap(TType.STRING, TType.STRUCT, size);
      }
    };
  }

  private static TProtocol mapEnd() {
    return new ParquetProtocol("readMapEnd()") {
      @Override
      public void readMapEnd() {}
    };
  }

  private static TProtocol i32(final int value) {
    return new ParquetProtocol("readI32()") {
      @Override
      public int readI32() {
        return value;
      }
    };
