import java.util.*;
import org.apache.parquet.thrift.struct.*;
import org.apache.parquet.thrift.struct.ThriftType.*;
import org.apache.parquet.schema.LogicalTypeAnnotation;

public class S2 {
  public static void main(String[] a) throws Exception {
    UUIDType u = new UUIDType();
    u.accept(new ThriftType.StateVisitor<String,Object>() {
      public String visit(MapType m, Object s){return null;}
      public String visit(SetType s, Object o){return null;}
      public String visit(ListType l, Object o){return null;}
      public String visit(StructType s, Object o){return null;}
      public String visit(EnumType e, Object o){return null;}
      public String visit(BoolType b, Object o){return null;}
      public String visit(ByteType b, Object o){return null;}
      public String visit(DoubleType d, Object o){return null;}
      public String visit(I16Type i, Object o){return null;}
      public String visit(I32Type i, Object o){return null;}
      public String visit(I64Type i, Object o){return null;}
      public String visit(StringType s, Object o){return null;}
    }, null);
    System.out.println("hasAnn=" + u.hasLogicalTypeAnnotation() + " ann=" + u.getLogicalTypeAnnotation());
    String json = u.toJSON();
    System.out.println(json);
    try {
      ThriftType back = ThriftType.fromJSON(json);
      System.out.println("back: " + back.getClass() + " ann=" + back.getLogicalTypeAnnotation());
      System.out.println("equals: " + back.equals(u));
    } catch (Exception e) { System.out.println("failed: " + e); }

    // struct type equals with different structOrUnionType
    ThriftType s1 = new StructType(Arrays.asList(new ThriftField("a",(short)1,ThriftField.Requirement.REQUIRED,new I32Type())), StructType.StructOrUnionType.STRUCT);
    ThriftType s2 = new StructType(Arrays.asList(new ThriftField("a",(short)1,ThriftField.Requirement.REQUIRED,new I32Type())), StructType.StructOrUnionType.UNION);
    System.out.println("struct vs union equals: " + s1.equals(s2) + " hashEq=" + (s1.hashCode()==s2.hashCode()));
    // order dependence
    ThriftType s3 = new StructType(Arrays.asList(
        new ThriftField("b",(short)2,ThriftField.Requirement.REQUIRED,new I32Type()),
        new ThriftField("a",(short)1,ThriftField.Requirement.REQUIRED,new I32Type())));
    ThriftType s4 = new StructType(Arrays.asList(
        new ThriftField("a",(short)1,ThriftField.Requirement.REQUIRED,new I32Type()),
        new ThriftField("b",(short)2,ThriftField.Requirement.REQUIRED,new I32Type())));
    System.out.println("reordered equals: " + s3.equals(s4));
    // empty struct childById length
    StructType empty = new StructType(new ArrayList<ThriftField>());
    System.out.println("empty child0: " + empty.getChildById((short)0));
    try { System.out.println("empty child1: " + empty.getChildById((short)1)); } catch (Exception e){ System.out.println("empty child1 ex " + e); }
    // string binary affects equality?
    StringType b1 = new StringType(); StringType b2 = new StringType(); b2.setBinary(true);
    System.out.println("binary equals: " + b1.equals(b2));
    // ThriftTypeID gaps / bytes
    System.out.println("fromByte(16)=" + ThriftTypeID.fromByte((byte)16) + " fromByte(17)=" + ThriftTypeID.fromByte((byte)17));
    try { System.out.println("fromByte(18)=" + ThriftTypeID.fromByte((byte)18)); } catch (Exception e) { System.out.println("fromByte(18) ex " + e); }
    System.out.println("fromByte(5)=" + ThriftTypeID.fromByte((byte)5));
    System.out.println("ENUM thriftType=" + ThriftTypeID.ENUM.getThriftType() + " serialized=" + ThriftTypeID.ENUM.getSerializedThriftType() + " complex=" + ThriftTypeID.ENUM.isComplex());
    // enum lazy lookup with dup ids
    EnumType et = new EnumType(Arrays.asList(new EnumValue(1,"A"), new EnumValue(1,"B"), new EnumValue(2,"C")));
    System.out.println("dup lookup: " + et.getEnumValueById(1).getName() + " / " + et.getEnumValueById(2).getName() + " / missing=" + et.getEnumValueById(42));
  }
}
