  static ThriftField f(String n, int id, ThriftField.Requirement r, ThriftType t) {
    return new ThriftField(n, (short) id, r, t);
  }
  static StructType st(ThriftField... fs) { return new StructType(Arrays.asList(fs)); }
  static void check(String label, StructType o, StructType n) {
    CompatibilityChecker c = new CompatibilityChecker();
    // CompatibilityReport is package private; use reflection-free: not accessible from default package
    System.out.println("== " + label);
    System.out.println(new CompatibilityChecker().checkCompatibility(o, n).toString());
  }
  public static void main(String[] a) {
    StructType base = st(f("a",1,ThriftField.Requirement.REQUIRED,new I32Type()), f("b",2,ThriftField.Requirement.OPTIONAL,new StringType()));
    check("identical", base, st(f("a",1,ThriftField.Requirement.REQUIRED,new I32Type()), f("b",2,ThriftField.Requirement.OPTIONAL,new StringType())));
    check("add optional", base, st(f("a",1,ThriftField.Requirement.REQUIRED,new I32Type()), f("b",2,ThriftField.Requirement.OPTIONAL,new StringType()), f("c",3,ThriftField.Requirement.OPTIONAL,new I64Type())));
    check("add required", base, st(f("a",1,ThriftField.Requirement.REQUIRED,new I32Type()), f("b",2,ThriftField.Requirement.OPTIONAL,new StringType()), f("c",3,ThriftField.Requirement.REQUIRED,new I64Type())));
    check("remove field", base, st(f("a",1,ThriftField.Requirement.REQUIRED,new I32Type())));
    check("type change", base, st(f("a",1,ThriftField.Requirement.REQUIRED,new I64Type()), f("b",2,ThriftField.Requirement.OPTIONAL,new StringType())));
    check("rename", base, st(f("x",1,ThriftField.Requirement.REQUIRED,new I32Type()), f("b",2,ThriftField.Requirement.OPTIONAL,new StringType())));
    check("optional to required", base, st(f("a",1,ThriftField.Requirement.REQUIRED,new I32Type()), f("b",2,ThriftField.Requirement.REQUIRED,new StringType())));
    check("required to optional", base, st(f("a",1,ThriftField.Requirement.OPTIONAL,new I32Type()), f("b",2,ThriftField.Requirement.OPTIONAL,new StringType())));
    check("empty new", base, st());
    check("empty both", st(), st());
    check("nested change", st(f("outer",1,ThriftField.Requirement.REQUIRED, st(f("inner",1,ThriftField.Requirement.REQUIRED,new I32Type())))),
        st(f("outer",1,ThriftField.Requirement.REQUIRED, st(f("inner",1,ThriftField.Requirement.REQUIRED,new StringType())))));
    check("list change", st(f("l",1,ThriftField.Requirement.REQUIRED,new ListType(f("values",1,ThriftField.Requirement.DEFAULT,new I32Type())))),
        st(f("l",1,ThriftField.Requirement.REQUIRED,new ListType(f("values",1,ThriftField.Requirement.DEFAULT,new I64Type())))));
    check("set required", st(f("s",1,ThriftField.Requirement.REQUIRED,new SetType(f("values",1,ThriftField.Requirement.DEFAULT,new I32Type())))),
        st(f("s",1,ThriftField.Requirement.REQUIRED,new SetType(f("values",1,ThriftField.Requirement.REQUIRED,new I32Type())))));
    check("map key rename", st(f("m",1,ThriftField.Requirement.REQUIRED,new MapType(f("k",1,ThriftField.Requirement.REQUIRED,new StringType()), f("v",2,ThriftField.Requirement.REQUIRED,new I32Type())))),
