    check("map value nested change", st(f("m",1,ThriftField.Requirement.REQUIRED,new MapType(f("k",1,ThriftField.Requirement.REQUIRED,new StringType()), f("v",2,ThriftField.Requirement.REQUIRED, st(f("n",1,ThriftField.Requirement.REQUIRED,new I32Type())))))),
        st(f("m",1,ThriftField.Requirement.REQUIRED,new MapType(f("k",1,ThriftField.Requirement.REQUIRED,new StringType()), f("v",2,ThriftField.Requirement.REQUIRED, st(f("n",1,ThriftField.Requirement.REQUIRED,new I64Type())))))));
    check("two incompat", base, st(f("x",1,ThriftField.Requirement.REQUIRED,new I64Type()), f("y",2,ThriftField.Requirement.OPTIONAL,new StringType())));
