        st(f("e",1,ThriftField.Requirement.REQUIRED,new EnumType(Arrays.asList(new EnumValue(1,"A"), new EnumValue(2,"B"))))));
    check("enum to i32", st(f("e",1,ThriftField.Requirement.REQUIRED,new EnumType(Arrays.asList(new EnumValue(1,"A"))))),
        st(f("e",1,ThriftField.Requirement.REQUIRED,new I32Type())));
    check("list to set", st(f("l",1,ThriftField.Requirement.REQUIRED,new ListType(f("values",1,ThriftField.Requirement.DEFAULT,new I32Type())))),
        st(f("l",1,ThriftField.Requirement.REQUIRED,new SetType(f("values",1,ThriftField.Requirement.DEFAULT,new I32Type())))));
    check("new required gap id", st(f("a",1,ThriftField.Requirement.REQUIRED,new I32Type()), f("c",5,ThriftField.Requirement.REQUIRED,new I32Type())),
        st(f("a",1,ThriftField.Requirement.REQUIRED,new I32Type()), f("c",5,ThriftField.Requirement.REQUIRED,new I32Type()), f("b",3,ThriftField.Requirement.REQUIRED,new I32Type())));
