package org.apache.parquet.thrift.struct;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.apache.parquet.thrift.struct.ThriftType.BoolType;
import org.apache.parquet.thrift.struct.ThriftType.ByteType;
import org.apache.parquet.thrift.struct.ThriftType.DoubleType;
import org.apache.parquet.thrift.struct.ThriftType.EnumType;
import org.apache.parquet.thrift.struct.ThriftType.I16Type;
import org.apache.parquet.thrift.struct.ThriftType.I32Type;
import org.apache.parquet.thrift.struct.ThriftType.I64Type;
import org.apache.parquet.thrift.struct.ThriftType.ListType;
import org.apache.parquet.thrift.struct.ThriftType.MapType;
import org.apache.parquet.thrift.struct.ThriftType.SetType;
import org.apache.parquet.thrift.struct.ThriftType.StringType;
import org.apache.parquet.thrift.struct.ThriftType.StructType;
import org.apache.parquet.thrift.struct.ThriftType.UUIDType;
import org.apache.thrift.protocol.TType;
import org.junit.jupiter.api.Test;

class ThriftTypeIDTest {

  @Test
  void fromByteMapsEveryThriftProtocolByteToItsTypeId() {
    assertThat(ThriftTypeID.fromByte(TType.STOP)).isEqualTo(ThriftTypeID.STOP);
    assertThat(ThriftTypeID.fromByte(TType.VOID)).isEqualTo(ThriftTypeID.VOID);
    assertThat(ThriftTypeID.fromByte(TType.BOOL)).isEqualTo(ThriftTypeID.BOOL);
    assertThat(ThriftTypeID.fromByte(TType.BYTE)).isEqualTo(ThriftTypeID.BYTE);
    assertThat(ThriftTypeID.fromByte(TType.DOUBLE)).isEqualTo(ThriftTypeID.DOUBLE);
    assertThat(ThriftTypeID.fromByte(TType.I16)).isEqualTo(ThriftTypeID.I16);
    assertThat(ThriftTypeID.fromByte(TType.I32)).isEqualTo(ThriftTypeID.I32);
    assertThat(ThriftTypeID.fromByte(TType.I64)).isEqualTo(ThriftTypeID.I64);
    assertThat(ThriftTypeID.fromByte(TType.STRING)).isEqualTo(ThriftTypeID.STRING);
    assertThat(ThriftTypeID.fromByte(TType.STRUCT)).isEqualTo(ThriftTypeID.STRUCT);
    assertThat(ThriftTypeID.fromByte(TType.MAP)).isEqualTo(ThriftTypeID.MAP);
    assertThat(ThriftTypeID.fromByte(TType.SET)).isEqualTo(ThriftTypeID.SET);
    assertThat(ThriftTypeID.fromByte(TType.LIST)).isEqualTo(ThriftTypeID.LIST);
  }

  @Test
  void uuidIsMappedAtItsProtocolByte() {
    assertThat(ThriftTypeID.UUID.getThriftType()).isEqualTo(TType.UUID);
    assertThat(ThriftTypeID.fromByte(TType.UUID)).isEqualTo(ThriftTypeID.UUID);
  }

  @Test
  void enumIsMappedBeyondTheLastProtocolByteBecauseThriftHasNoEnumType() {
    // Thrift has no wire type for enums, so the enum type id is stored at the extra slot
    assertThat(ThriftTypeID.fromByte((byte) 17)).isEqualTo(ThriftTypeID.ENUM);
    assertThat(ThriftTypeID.ENUM.getThriftType()).isEqualTo(TType.ENUM);
    assertThat(ThriftTypeID.ENUM.getSerializedThriftType()).isEqualTo(TType.I32);
  }

  @Test
  void enumSerializesAsI32WhileAllOtherTypesSerializeAsThemselves() {
    for (ThriftTypeID id : ThriftTypeID.values()) {
      if (id == ThriftTypeID.ENUM) {
        continue;
      }
      assertThat(id.getSerializedThriftType())
          .as("serialized type of %s", id)
          .isEqualTo(id.getThriftType());
    }
  }

  @Test
  void unusedProtocolByteSlotsMapToNothing() {
    assertThat(ThriftTypeID.fromByte((byte) 5)).isNull();
    assertThat(ThriftTypeID.fromByte((byte) 7)).isNull();
    assertThat(ThriftTypeID.fromByte((byte) 9)).isNull();
  }

  @Test
  void fromByteRejectsBytesOutsideOfTheKnownRange() {
    assertThatThrownBy(() -> ThriftTypeID.fromByte((byte) 18)).isInstanceOf(IndexOutOfBoundsException.class);
    assertThatThrownBy(() -> ThriftTypeID.fromByte((byte) -1)).isInstanceOf(IndexOutOfBoundsException.class);
  }

  @Test
  void onlyContainerTypesAreComplex() {
    assertThat(ThriftTypeID.STRUCT.isComplex()).isTrue();
    assertThat(ThriftTypeID.MAP.isComplex()).isTrue();
    assertThat(ThriftTypeID.SET.isComplex()).isTrue();
    assertThat(ThriftTypeID.LIST.isComplex()).isTrue();

    assertThat(ThriftTypeID.STOP.isComplex()).isFalse();
    assertThat(ThriftTypeID.VOID.isComplex()).isFalse();
    assertThat(ThriftTypeID.BOOL.isComplex()).isFalse();
    assertThat(ThriftTypeID.BYTE.isComplex()).isFalse();
    assertThat(ThriftTypeID.DOUBLE.isComplex()).isFalse();
    assertThat(ThriftTypeID.I16.isComplex()).isFalse();
    assertThat(ThriftTypeID.I32.isComplex()).isFalse();
    assertThat(ThriftTypeID.I64.isComplex()).isFalse();
    assertThat(ThriftTypeID.STRING.isComplex()).isFalse();
    assertThat(ThriftTypeID.ENUM.isComplex()).isFalse();
    assertThat(ThriftTypeID.UUID.isComplex()).isFalse();
  }

  @Test
  void everyTypeIdExposesTheThriftTypeImplementationItDescribes() {
    assertThat(ThriftTypeID.BOOL.getType()).isEqualTo(BoolType.class);
    assertThat(ThriftTypeID.BYTE.getType()).isEqualTo(ByteType.class);
    assertThat(ThriftTypeID.DOUBLE.getType()).isEqualTo(DoubleType.class);
    assertThat(ThriftTypeID.I16.getType()).isEqualTo(I16Type.class);
    assertThat(ThriftTypeID.I32.getType()).isEqualTo(I32Type.class);
    assertThat(ThriftTypeID.I64.getType()).isEqualTo(I64Type.class);
    assertThat(ThriftTypeID.STRING.getType()).isEqualTo(StringType.class);
    assertThat(ThriftTypeID.STRUCT.getType()).isEqualTo(StructType.class);
    assertThat(ThriftTypeID.MAP.getType()).isEqualTo(MapType.class);
    assertThat(ThriftTypeID.SET.getType()).isEqualTo(SetType.class);
    assertThat(ThriftTypeID.LIST.getType()).isEqualTo(ListType.class);
    assertThat(ThriftTypeID.ENUM.getType()).isEqualTo(EnumType.class);
    assertThat(ThriftTypeID.UUID.getType()).isEqualTo(UUIDType.class);
  }

  @Test
  void stopAndVoidDoNotDescribeAThriftTypeImplementation() {
    assertThat(ThriftTypeID.STOP.getType()).isNull();
    assertThat(ThriftTypeID.VOID.getType()).isNull();
  }
}
