package org.apache.parquet.thrift.struct;

import static org.assertj.core.api.Assertions.assertThat;
import static org.apache.parquet.thrift.struct.ThriftField.Requirement.DEFAULT;
import static org.apache.parquet.thrift.struct.ThriftField.Requirement.OPTIONAL;
import static org.apache.parquet.thrift.struct.ThriftField.Requirement.REQUIRED;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.apache.parquet.schema.LogicalTypeAnnotation;
import org.apache.parquet.thrift.struct.ThriftType.BoolType;
import org.apache.parquet.thrift.struct.ThriftType.ByteType;
import org.apache.parquet.thrift.struct.ThriftType.DoubleType;
import org.apache.parquet.thrift.struct.ThriftType.EnumType;
import org.apache.parquet.thrift.struct.ThriftType.EnumValue;
import org.apache.parquet.thrift.struct.ThriftType.I16Type;
import org.apache.parquet.thrift.struct.ThriftType.I32Type;
import org.apache.parquet.thrift.struct.ThriftType.I64Type;
import org.apache.parquet.thrift.struct.ThriftType.ListType;
import org.apache.parquet.thrift.struct.ThriftType.MapType;
import org.apache.parquet.thrift.struct.ThriftType.SetType;
import org.apache.parquet.thrift.struct.ThriftType.StringType;
import org.apache.parquet.thrift.struct.ThriftType.StructType;
import org.apache.parquet.thrift.struct.ThriftType.StructType.StructOrUnionType;
import org.apache.parquet.thrift.struct.ThriftType.UUIDType;
import org.junit.jupiter.api.Test;

class ThriftTypeTest {

  private static ThriftField field(String name, int id, ThriftField.Requirement requirement, ThriftType type) {
    return new ThriftField(name, (short) id, requirement, type);
  }

  @Test
  void everySubtypeReportsItsOwnTypeId() {
    assertThat(new BoolType().getType()).isEqualTo(ThriftTypeID.BOOL);
    assertThat(new ByteType().getType()).isEqualTo(ThriftTypeID.BYTE);
    assertThat(new DoubleType().getType()).isEqualTo(ThriftTypeID.DOUBLE);
    assertThat(new I16Type().getType()).isEqualTo(ThriftTypeID.I16);
    assertThat(new I32Type().getType()).isEqualTo(ThriftTypeID.I32);
    assertThat(new I64Type().getType()).isEqualTo(ThriftTypeID.I64);
    assertThat(new StringType().getType()).isEqualTo(ThriftTypeID.STRING);
    assertThat(new UUIDType().getType()).isEqualTo(ThriftTypeID.UUID);
    assertThat(new EnumType(Collections.singletonList(new EnumValue(1, "A"))).getType())
        .isEqualTo(ThriftTypeID.ENUM);
    assertThat(new ListType(field("values", 1, DEFAULT, new I32Type())).getType())
        .isEqualTo(ThriftTypeID.LIST);
    assertThat(new SetType(field("values", 1, DEFAULT, new I32Type())).getType())
        .isEqualTo(ThriftTypeID.SET);
    assertThat(new MapType(field("key", 1, REQUIRED, new I32Type()), field("value", 2, REQUIRED, new I32Type()))
            .getType())
        .isEqualTo(ThriftTypeID.MAP);
    assertThat(new StructType(Collections.<ThriftField>emptyList()).getType())
        .isEqualTo(ThriftTypeID.STRUCT);
  }

  @Test
  void typesWithTheSameTypeIdAreEqualAndShareHashCode() {
    assertThat(new I32Type()).isEqualTo(new I32Type());
    assertThat(new I32Type().hashCode()).isEqualTo(new I32Type().hashCode());
    assertThat(new BoolType()).isEqualTo(new BoolType());
    assertThat(new UUIDType()).isEqualTo(new UUIDType());

    assertThat(new I32Type()).isNotEqualTo(new I64Type());
    assertThat(new ListType(field("values", 1, DEFAULT, new I32Type())))
        .isNotEqualTo(new SetType(field("values", 1, DEFAULT, new I32Type())));
  }

  @Test
  void equalityIsReflexiveAndRejectsForeignObjects() {
    I32Type type = new I32Type();
    assertThat(type.equals(type)).isTrue();
    assertThat(type.equals(null)).isFalse();
    assertThat(type.equals("I32")).isFalse();
  }

  @Test
  void containerEqualityTakesKeyValueAndElementTypesIntoAccount() {
    MapType map = new MapType(
        field("key", 1, REQUIRED, new StringType()), field("value", 2, REQUIRED, new I32Type()));
    MapType sameMap = new MapType(
        field("key", 1, REQUIRED, new StringType()), field("value", 2, REQUIRED, new I32Type()));
    MapType otherValueMap = new MapType(
        field("key", 1, REQUIRED, new StringType()), field("value", 2, REQUIRED, new I64Type()));

    assertThat(map).isEqualTo(sameMap);
    assertThat(map.hashCode()).isEqualTo(sameMap.hashCode());
    assertThat(map).isNotEqualTo(otherValueMap);

    ListType list = new ListType(field("values", 1, DEFAULT, new I32Type()));
    assertThat(list).isEqualTo(new ListType(field("values", 1, DEFAULT, new I32Type())));
    assertThat(list).isNotEqualTo(new ListType(field("values", 1, DEFAULT, new I64Type())));

    SetType set = new SetType(field("values", 1, DEFAULT, new I32Type()));
    assertThat(set).isEqualTo(new SetType(field("values", 1, DEFAULT, new I32Type())));
    assertThat(set).isNotEqualTo(new SetType(field("values", 1, DEFAULT, new I64Type())));
  }

  @Test
  void containerAccessorsExposeTheNestedFields() {
    ThriftField key = field("key", 1, REQUIRED, new StringType());
    ThriftField value = field("value", 2, OPTIONAL, new I32Type());
    MapType map = new MapType(key, value);
    assertThat(map.getKey()).isSameAs(key);
    assertThat(map.getValue()).isSameAs(value);

    ThriftField element = field("values", 1, DEFAULT, new I32Type());
    assertThat(new ListType(element).getValues()).isSameAs(element);
    assertThat(new SetType(element).getValues()).isSameAs(element);
  }

  @Test
  void structTypeIndexesChildrenByFieldId() {
    ThriftField first = field("first", 1, REQUIRED, new I32Type());
    ThriftField last = field("last", 5, OPTIONAL, new StringType());
    StructType struct = new StructType(Arrays.asList(first, last));

    assertThat(struct.getChildren()).containsExactly(first, last);
    assertThat(struct.getChildById((short) 1)).isSameAs(first);
    assertThat(struct.getChildById((short) 5)).isSameAs(last);
    assertThat(struct.getChildById((short) 0)).isNull();
    assertThat(struct.getChildById((short) 3)).isNull();
    assertThat(struct.getChildById((short) 6)).isNull();
  }

  @Test
  void emptyStructHasNoChildrenAndNoIndexedField() {
    StructType struct = new StructType(Collections.<ThriftField>emptyList());
    assertThat(struct.getChildren()).isEmpty();
    assertThat(struct.getChildById((short) 0)).isNull();
    assertThat(struct.getChildById((short) 42)).isNull();
  }

  @Test
  void structTypeDefaultsToARegularStruct() {
    assertThat(new StructType(Collections.<ThriftField>emptyList()).getStructOrUnionType())
        .isEqualTo(StructOrUnionType.STRUCT);
    assertThat(new StructType(null).getStructOrUnionType()).isEqualTo(StructOrUnionType.STRUCT);
    // deprecated constructor without an explicit struct/union flag
    assertThat(new StructType(Arrays.asList(field("a", 1, REQUIRED, new I32Type()))).getStructOrUnionType())
        .isEqualTo(StructOrUnionType.STRUCT);
  }

  @Test
  void structTypeKeepsExplicitStructOrUnionInformation() {
    List<ThriftField> children = Arrays.asList(field("a", 1, REQUIRED, new I32Type()));
    assertThat(new StructType(children, StructOrUnionType.UNION).getStructOrUnionType())
        .isEqualTo(StructOrUnionType.UNION);
    assertThat(new StructType(children, StructOrUnionType.UNKNOWN).getStructOrUnionType())
        .isEqualTo(StructOrUnionType.UNKNOWN);
  }

  @Test
  void structEqualityDependsOnTheIndexedChildren() {
    StructType struct = new StructType(Arrays.asList(
        field("a", 1, REQUIRED, new I32Type()), field("b", 2, OPTIONAL, new StringType())));
    StructType sameStruct = new StructType(Arrays.asList(
        field("a", 1, REQUIRED, new I32Type()), field("b", 2, OPTIONAL, new StringType())));
    StructType differentStruct = new StructType(Arrays.asList(
        field("a", 1, REQUIRED, new I32Type()), field("b", 2, OPTIONAL, new I64Type())));

    assertThat(struct).isEqualTo(sameStruct);
    assertThat(struct.hashCode()).isEqualTo(sameStruct.hashCode());
    assertThat(struct).isNotEqualTo(differentStruct);
    assertThat(struct).isNotEqualTo(new MapType(
        field("key", 1, REQUIRED, new StringType()), field("value", 2, REQUIRED, new StringType())));
  }

  @Test
  void enumValuesAreReadableById() {
    EnumValue one = new EnumValue(1, "ONE");
    EnumValue two = new EnumValue(2, "TWO");
    EnumType enumType = new EnumType(Arrays.asList(one, two));

    assertThat(enumType.getValues()).containsExactly(one, two);
    assertThat(enumType.getEnumValueById(1)).isEqualTo(one);
    assertThat(enumType.getEnumValueById(2)).isEqualTo(two);
    assertThat(enumType.getEnumValueById(3)).isNull();
    // repeated lookups must stay stable
    assertThat(enumType.getEnumValueById(1)).isEqualTo(one);
  }

  @Test
  void enumValueEqualityUsesIdAndName() {
    assertThat(new EnumValue(1, "ONE")).isEqualTo(new EnumValue(1, "ONE"));
    assertThat(new EnumValue(1, "ONE").hashCode()).isEqualTo(new EnumValue(1, "ONE").hashCode());
    assertThat(new EnumValue(1, "ONE")).isNotEqualTo(new EnumValue(2, "ONE"));
    assertThat(new EnumValue(1, "ONE")).isNotEqualTo(new EnumValue(1, "TWO"));
    assertThat(new EnumValue(1, null)).isNotEqualTo(new EnumValue(1, "ONE"));
    assertThat(new EnumValue(1, null)).isEqualTo(new EnumValue(1, null));
  }

  @Test
  void enumTypeEqualityDependsOnItsValues() {
    EnumType enumType = new EnumType(Arrays.asList(new EnumValue(1, "ONE")));
    assertThat(enumType).isEqualTo(new EnumType(Arrays.asList(new EnumValue(1, "ONE"))));
    assertThat(enumType.hashCode())
        .isEqualTo(new EnumType(Arrays.asList(new EnumValue(1, "ONE"))).hashCode());
    assertThat(enumType).isNotEqualTo(new EnumType(Arrays.asList(new EnumValue(1, "ONE"), new EnumValue(2, "TWO"))));
  }

  @Test
  void stringTypeCarriesTheBinaryFlag() {
    StringType stringType = new StringType();
    assertThat(stringType.isBinary()).isFalse();
    stringType.setBinary(true);
    assertThat(stringType.isBinary()).isTrue();
    stringType.setBinary(false);
    assertThat(stringType.isBinary()).isFalse();
  }

  @Test
  void logicalTypeAnnotationIsOptional() {
    I32Type type = new I32Type();
    assertThat(type.hasLogicalTypeAnnotation()).isFalse();
    assertThat(type.getLogicalTypeAnnotation()).isNull();

    type.setLogicalTypeAnnotation(LogicalTypeAnnotation.uuidType());
    assertThat(type.hasLogicalTypeAnnotation()).isTrue();
    assertThat(type.getLogicalTypeAnnotation()).isEqualTo(LogicalTypeAnnotation.uuidType());

    type.setLogicalTypeAnnotation(null);
    assertThat(type.hasLogicalTypeAnnotation()).isFalse();
  }

  @Test
  void toStringRendersTheJsonRepresentation() {
    ThriftField field = field("a", 1, REQUIRED, new I32Type());
    assertThat(field.getType().toString()).isEqualTo(field.getType().toJSON());
    assertThat(new I32Type().toString()).contains("\"id\" : \"I32\"");
  }
}
