package org.apache.parquet.thrift.struct;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.apache.parquet.thrift.struct.ThriftField.Requirement;
import org.apache.parquet.thrift.struct.ThriftType.I32Type;
import org.apache.parquet.thrift.struct.ThriftType.I64Type;
import org.apache.parquet.thrift.struct.ThriftType.StringType;
import org.apache.thrift.TFieldRequirementType;
import org.junit.jupiter.api.Test;

class ThriftFieldTest {

  @Test
  void accessorsExposeTheFieldDescriptor() {
    I32Type type = new I32Type();
    ThriftField field = new ThriftField("count", (short) 7, Requirement.OPTIONAL, type);

    assertThat(field.getName()).isEqualTo("count");
    assertThat(field.getFieldId()).isEqualTo((short) 7);
    assertThat(field.getRequirement()).isEqualTo(Requirement.OPTIONAL);
    assertThat(field.getType()).isSameAs(type);
  }

  @Test
  void requirementsExposeTheThriftRequirementBytes() {
    assertThat(Requirement.REQUIRED.getRequirement()).isEqualTo(TFieldRequirementType.REQUIRED);
    assertThat(Requirement.OPTIONAL.getRequirement()).isEqualTo(TFieldRequirementType.OPTIONAL);
    assertThat(Requirement.DEFAULT.getRequirement()).isEqualTo(TFieldRequirementType.DEFAULT);
  }

  @Test
  void requirementCanBeResolvedFromItsThriftByte() {
    assertThat(Requirement.fromType(TFieldRequirementType.REQUIRED)).isEqualTo(Requirement.REQUIRED);
    assertThat(Requirement.fromType(TFieldRequirementType.OPTIONAL)).isEqualTo(Requirement.OPTIONAL);
    assertThat(Requirement.fromType(TFieldRequirementType.DEFAULT)).isEqualTo(Requirement.DEFAULT);
  }

  @Test
  void unknownRequirementBytesAreRejected() {
    assertThatThrownBy(() -> Requirement.fromType((byte) 0))
        .isInstanceOf(RuntimeException.class)
        .hasMessage("Unknown requirement 0");
    assertThatThrownBy(() -> Requirement.fromType((byte) 42))
        .isInstanceOf(RuntimeException.class)
        .hasMessage("Unknown requirement 42");
  }

  @Test
  void fieldsWithTheSameDescriptorAreEqual() {
    ThriftField field = new ThriftField("count", (short) 1, Requirement.REQUIRED, new I32Type());
    ThriftField same = new ThriftField("count", (short) 1, Requirement.REQUIRED, new I32Type());

    assertThat(field).isEqualTo(same);
    assertThat(field.hashCode()).isEqualTo(same.hashCode());
    assertThat(field.equals(field)).isTrue();
    assertThat(field.equals(null)).isFalse();
    assertThat(field.equals("count")).isFalse();
  }

  @Test
  void anyDescriptorDifferenceBreaksEquality() {
    ThriftField field = new ThriftField("count", (short) 1, Requirement.REQUIRED, new I32Type());

    assertThat(field).isNotEqualTo(new ThriftField("other", (short) 1, Requirement.REQUIRED, new I32Type()));
    assertThat(field).isNotEqualTo(new ThriftField("count", (short) 2, Requirement.REQUIRED, new I32Type()));
    assertThat(field).isNotEqualTo(new ThriftField("count", (short) 1, Requirement.OPTIONAL, new I32Type()));
    assertThat(field).isNotEqualTo(new ThriftField("count", (short) 1, Requirement.REQUIRED, new I64Type()));
  }

  @Test
  void toStringRendersJsonAndCanBeParsedBack() {
    ThriftField field = new ThriftField("name", (short) 3, Requirement.OPTIONAL, new StringType());

    String json = field.toString();
    assertThat(json).contains("\"name\" : \"name\"");
    assertThat(json).contains("\"fieldId\" : 3");
    assertThat(json).contains("\"requirement\" : \"OPTIONAL\"");

    assertThat(JSON.fromJSON(json, ThriftField.class)).isEqualTo(field);
  }
}
