import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.Arrays;
import java.util.Collections;
import org.apache.parquet.thrift.struct.ThriftType.BoolType;
import org.apache.parquet.thrift.struct.ThriftType.ByteType;
import org.apache.parquet.thrift.struct.ThriftType.DoubleType;
import org.apache.parquet.thrift.struct.ThriftType.EnumType;
import org.apache.parquet.thrift.struct.ThriftType.EnumValue;
import org.apache.parquet.thrift.struct.ThriftType.I16Type;
import org.apache.parquet.thrift.struct.ThriftType.I32Type;
import org.apache.parquet.thrift.struct.ThriftType.I64Type;
import org.apache.parquet.thrift.struct.ThriftType.ListType;
import org.apache.parquet.thrift.struct.ThriftType.MapType;
import org.apache.parquet.thrift.struct.ThriftType.SetType;
import org.apache.parquet.thrift.struct.ThriftType.StringType;
import org.apache.parquet.thrift.struct.ThriftType.StructType;
import org.apache.parquet.thrift.struct.ThriftType.StructType.StructOrUnionType;
import org.apache.parquet.thrift.struct.ThriftType.UUIDType;
import org.junit.jupiter.api.Test;

class ThriftTypeJsonTest {

  private static ThriftField field(String name, int id, ThriftField.Requirement requirement, ThriftType type) {
    return new ThriftField(name, (short) id, requirement, type);
  }

  private static StructType complexStruct() {
    return new StructType(
        Arrays.asList(
            field("flag", 1, REQUIRED, new BoolType()),
            field("tiny", 2, OPTIONAL, new ByteType()),
            field("ratio", 3, OPTIONAL, new DoubleType()),
            field("small", 4, OPTIONAL, new I16Type()),
            field("count", 5, REQUIRED, new I32Type()),
            field("total", 6, OPTIONAL, new I64Type()),
            field("text", 7, OPTIONAL, new StringType()),
            field("uuid", 8, OPTIONAL, new UUIDType()),
            field("kind", 9, OPTIONAL, new EnumType(Arrays.asList(new EnumValue(1, "A"), new EnumValue(2, "B")))),
            field("items", 10, OPTIONAL, new ListType(field("values", 1, DEFAULT, new I32Type()))),
            field("tags", 11, OPTIONAL, new SetType(field("values", 1, DEFAULT, new StringType()))),
            field(
                "attributes",
                12,
                OPTIONAL,
                new MapType(
                    field("key", 1, REQUIRED, new StringType()),
                    field("value", 2, REQUIRED, new ListType(field("values", 1, DEFAULT, new I64Type()))))),
            field(
                "nested",
                13,
                OPTIONAL,
                new StructType(Collections.singletonList(field("inner", 1, REQUIRED, new I32Type()))))),
        StructOrUnionType.STRUCT);
  }

  @Test
  void structTypesSurviveAJsonRoundTrip() {
    ThriftType.StructType struct = complexStruct();

    ThriftType parsed = ThriftType.fromJSON(struct.toJSON());

    assertThat(parsed).isInstanceOf(StructType.class);
    assertThat(parsed).isEqualTo(struct);
    assertThat(((StructType) parsed).getChildren()).hasSameSizeAs(struct.getChildren());
  }

  @Test
  void structOrUnionInformationSurvivesAJsonRoundTrip() {
    StructType union = new StructType(
        Collections.singletonList(field("a", 1, OPTIONAL, new I32Type())), StructOrUnionType.UNION);
    StructType unknown = new StructType(
        Collections.singletonList(field("a", 1, OPTIONAL, new I32Type())), StructOrUnionType.UNKNOWN);

    assertThat(union.toJSON()).contains("\"structOrUnionType\" : \"UNION\"");
    assertThat(((StructType) ThriftType.fromJSON(union.toJSON())).getStructOrUnionType())
        .isEqualTo(StructOrUnionType.UNION);
    assertThat(((StructType) ThriftType.fromJSON(unknown.toJSON())).getStructOrUnionType())
        .isEqualTo(StructOrUnionType.UNKNOWN);
  }

  @Test
  void binaryStringFlagSurvivesAJsonRoundTrip() {
    StringType stringType = new StringType();
    stringType.setBinary(true);

    assertThat(stringType.toJSON()).contains("\"binary\" : true");
    assertThat(((StringType) ThriftType.fromJSON(stringType.toJSON())).isBinary()).isTrue();
    assertThat(((StringType) ThriftType.fromJSON(new StringType().toJSON())).isBinary())
        .isFalse();
  }

  @Test
  void enumValuesSurviveAJsonRoundTrip() {
    EnumType enumType = new EnumType(Arrays.asList(new EnumValue(1, "A"), new EnumValue(7, "B")));

    ThriftType parsed = ThriftType.fromJSON(enumType.toJSON());

    assertThat(parsed).isEqualTo(enumType);
    assertThat(((EnumType) parsed).getEnumValueById(7).getName()).isEqualTo("B");
  }

  @Test
  void everyTypeIsSerializedWithItsTypeId() {
    assertThat(new BoolType().toJSON()).contains("\"id\" : \"BOOL\"");
    assertThat(new ByteType().toJSON()).contains("\"id\" : \"BYTE\"");
    assertThat(new DoubleType().toJSON()).contains("\"id\" : \"DOUBLE\"");
    assertThat(new I16Type().toJSON()).contains("\"id\" : \"I16\"");
    assertThat(new I32Type().toJSON()).contains("\"id\" : \"I32\"");
    assertThat(new I64Type().toJSON()).contains("\"id\" : \"I64\"");
    assertThat(new StringType().toJSON()).contains("\"id\" : \"STRING\"");
    assertThat(new UUIDType().toJSON()).contains("\"id\" : \"UUID\"");
    assertThat(new EnumType(Collections.singletonList(new EnumValue(1, "A"))).toJSON())
        .contains("\"id\" : \"ENUM\"");
    assertThat(new ListType(field("values", 1, DEFAULT, new I32Type())).toJSON())
        .contains("\"id\" : \"LIST\"");
    assertThat(new SetType(field("values", 1, DEFAULT, new I32Type())).toJSON())
        .contains("\"id\" : \"SET\"");
    assertThat(new MapType(field("key", 1, REQUIRED, new I32Type()), field("value", 2, REQUIRED, new I32Type()))
            .toJSON())
        .contains("\"id\" : \"MAP\"");
    assertThat(new StructType(Collections.<ThriftField>emptyList()).toJSON())
        .contains("\"id\" : \"STRUCT\"");
  }

  @Test
  void unknownTypeIdsCannotBeParsed() {
    assertThatThrownBy(() -> ThriftType.fromJSON("{\"id\" : \"NOT_A_TYPE\"}"))
        .isInstanceOf(RuntimeException.class);
  }

  @Test
  void jsonWithoutATypeIdCannotBeParsed() {
    assertThatThrownBy(() -> ThriftType.fromJSON("{\"values\" : []}"))
        .isInstanceOf(RuntimeException.class);
  }

  @Test
  void malformedJsonCannotBeParsed() {
    assertThatThrownBy(() -> ThriftType.fromJSON("{"))
        .isInstanceOf(RuntimeException.class)
        .hasCauseInstanceOf(java.io.IOException.class);
  }
}
