package org.apache.parquet.thrift.struct;

import static org.apache.parquet.thrift.struct.ThriftField.Requirement.DEFAULT;
import static org.apache.parquet.thrift.struct.ThriftField.Requirement.OPTIONAL;
import static org.apache.parquet.thrift.struct.ThriftField.Requirement.REQUIRED;
import static org.assertj.core.api.Assertions.assertThat;

import java.util.Arrays;
import java.util.Collections;
import org.apache.parquet.thrift.struct.ThriftType.BoolType;
import org.apache.parquet.thrift.struct.ThriftType.EnumType;
import org.apache.parquet.thrift.struct.ThriftType.EnumValue;
import org.apache.parquet.thrift.struct.ThriftType.I32Type;
import org.apache.parquet.thrift.struct.ThriftType.I64Type;
import org.apache.parquet.thrift.struct.ThriftType.ListType;
import org.apache.parquet.thrift.struct.ThriftType.MapType;
import org.apache.parquet.thrift.struct.ThriftType.SetType;
import org.apache.parquet.thrift.struct.ThriftType.StringType;
import org.apache.parquet.thrift.struct.ThriftType.StructType;
import org.junit.jupiter.api.Test;

class CompatibilityCheckerTest {

  private final CompatibilityChecker checker = new CompatibilityChecker();

  private static ThriftField field(String name, int id, ThriftField.Requirement requirement, ThriftType type) {
    return new ThriftField(name, (short) id, requirement, type);
  }

  private static StructType struct(ThriftField... fields) {
    return new StructType(Arrays.asList(fields));
  }

  private static StructType oldSchema() {
    return struct(field("count", 1, REQUIRED, new I32Type()), field("name", 2, OPTIONAL, new StringType()));
  }

  @Test
  void identicalSchemasAreCompatible() {
    CompatibilityReport report = checker.checkCompatibility(oldSchema(), oldSchema());

    assertThat(report.isCompatible()).isTrue();
    assertThat(report.hasEmptyStruct()).isFalse();
    assertThat(report.getMessages()).isEmpty();
  }

  @Test
  void addingAnOptionalFieldIsCompatible() {
    StructType newSchema =
        struct(field("count", 1, REQUIRED, new I32Type()), field("name", 2, OPTIONAL, new StringType()),
            field("extra", 3, OPTIONAL, new I64Type()));

    CompatibilityReport report = checker.checkCompatibility(oldSchema(), newSchema);

    assertThat(report.isCompatible()).isTrue();
    assertThat(report.getMessages()).isEmpty();
  }

  @Test
  void addingADefaultFieldIsCompatible() {
    StructType newSchema =
        struct(field("count", 1, REQUIRED, new I32Type()), field("name", 2, OPTIONAL, new StringType()),
            field("extra", 3, DEFAULT, new I64Type()));

    assertThat(checker.checkCompatibility(oldSchema(), newSchema).isCompatible())
        .isTrue();
  }

  @Test
  void addingARequiredFieldIsIncompatible() {
    StructType newSchema =
        struct(field("count", 1, REQUIRED, new I32Type()), field("name", 2, OPTIONAL, new StringType()),
            field("extra", 3, REQUIRED, new I64Type()));

    CompatibilityReport report = checker.checkCompatibility(oldSchema(), newSchema);

    assertThat(report.isCompatible()).isFalse();
    assertThat(report.getMessages()).containsExactly("at :new required field extra is added");
  }

  @Test
  void addingARequiredFieldIntoAGapOfTheOldSchemaIsIncompatible() {
    StructType oldSchema = struct(field("count", 1, REQUIRED, new I32Type()), field("name", 5, OPTIONAL, new StringType()));
    StructType newSchema = struct(
        field("count", 1, REQUIRED, new I32Type()),
        field("name", 5, OPTIONAL, new StringType()),
        field("extra", 3, REQUIRED, new I64Type()));

    CompatibilityReport report = checker.checkCompatibility(oldSchema, newSchema);

    assertThat(report.isCompatible()).isFalse();
    assertThat(report.getMessages()).containsExactly("at :new required field extra is added");
  }

  @Test
  void removingAFieldIsIncompatible() {
    StructType newSchema = struct(field("count", 1, REQUIRED, new I32Type()));

    CompatibilityReport report = checker.checkCompatibility(oldSchema(), newSchema);

    assertThat(report.isCompatible()).isFalse();
    assertThat(report.getMessages()).hasSize(1);
    assertThat(report.getMessages().get(0)).contains("at :can not find index in new Struct: 2");
  }

  @Test
  void changingAFieldTypeIsIncompatible() {
    StructType newSchema =
        struct(field("count", 1, REQUIRED, new I64Type()), field("name", 2, OPTIONAL, new StringType()));

    CompatibilityReport report = checker.checkCompatibility(oldSchema(), newSchema);

    assertThat(report.isCompatible()).isFalse();
    assertThat(report.getMessages()).containsExactly("at :type is not compatible: I32 vs I64");
  }

  @Test
  void renamingAFieldIsIncompatible() {
    StructType newSchema =
        struct(field("amount", 1, REQUIRED, new I32Type()), field("name", 2, OPTIONAL, new StringType()));

    CompatibilityReport report = checker.checkCompatibility(oldSchema(), newSchema);

    assertThat(report.isCompatible()).isFalse();
    assertThat(report.getMessages()).containsExactly("at :field names are different: count vs amount");
  }

  @Test
  void makingAnOptionalFieldRequiredIsIncompatible() {
    StructType newSchema =
        struct(field("count", 1, REQUIRED, new I32Type()), field("name", 2, REQUIRED, new StringType()));

    CompatibilityReport report = checker.checkCompatibility(oldSchema(), newSchema);

    assertThat(report.isCompatible()).isFalse();
    assertThat(report.getMessages()).containsExactly("at :new field is more restrictive: name");
  }

  @Test
  void relaxingARequiredFieldIsCompatible() {
    StructType optionalSchema =
        struct(field("count", 1, OPTIONAL, new I32Type()), field("name", 2, OPTIONAL, new StringType()));
    StructType defaultSchema =
        struct(field("count", 1, DEFAULT, new I32Type()), field("name", 2, OPTIONAL, new StringType()));

    assertThat(checker.checkCompatibility(oldSchema(), optionalSchema).isCompatible())
        .isTrue();
    assertThat(checker.checkCompatibility(oldSchema(), defaultSchema).isCompatible())
        .isTrue();
  }

  @Test
  void emptyNewStructIsFlagged() {
    CompatibilityReport report = checker.checkCompatibility(oldSchema(), struct());

    assertThat(report.isCompatible()).isFalse();
    assertThat(report.hasEmptyStruct()).isTrue();
    assertThat(report.getMessages()).anyMatch(message -> message.equals("encountered an empty struct: "));
  }

  @Test
  void twoEmptyStructsAreCompatibleButStillFlagged() {
    CompatibilityReport report = checker.checkCompatibility(struct(), struct());

    assertThat(report.isCompatible()).isTrue();
    assertThat(report.hasEmptyStruct()).isTrue();
    assertThat(report.getMessages()).containsExactly("encountered an empty struct: ");
  }

  @Test
  void nestedStructTypeChangeIsReportedWithTheParentPath() {
    StructType oldSchema = struct(field(
        "outer", 1, REQUIRED, struct(field("inner", 1, REQUIRED, new I32Type()))));
    StructType newSchema = struct(field(
        "outer", 1, REQUIRED, struct(field("inner", 1, REQUIRED, new StringType()))));

    CompatibilityReport report = checker.checkCompatibility(oldSchema, newSchema);

    assertThat(report.isCompatible()).isFalse();
    assertThat(report.getMessages()).containsExactly("at outer:type is not compatible: I32 vs STRING");
  }

  @Test
  void nestedEmptyStructIsFlagged() {
    StructType oldSchema = struct(field(
        "outer", 1, REQUIRED, struct(field("inner", 1, REQUIRED, new I32Type()))));
    StructType newSchema = struct(field("outer", 1, REQUIRED, struct()));

    CompatibilityReport report = checker.checkCompatibility(oldSchema, newSchema);

    assertThat(report.hasEmptyStruct()).isTrue();
    assertThat(report.getMessages()).anyMatch(message -> message.equals("encountered an empty struct: outer"));
  }

  @Test
  void listElementTypeChangeIsIncompatible() {
    StructType oldSchema = struct(
        field("items", 1, REQUIRED, new ListType(field("values", 1, DEFAULT, new I32Type()))));
    StructType newSchema = struct(
        field("items", 1, REQUIRED, new ListType(field("values", 1, DEFAULT, new I64Type()))));

    CompatibilityReport report = checker.checkCompatibility(oldSchema, newSchema);

    assertThat(report.isCompatible()).isFalse();
    assertThat(report.getMessages()).containsExactly("at items:type is not compatible: I32 vs I64");
  }

  @Test
  void setElementRequirementChangeIsIncompatible() {
    StructType oldSchema =
        struct(field("tags", 1, REQUIRED, new SetType(field("values", 1, DEFAULT, new StringType()))));
    StructType newSchema =
        struct(field("tags", 1, REQUIRED, new SetType(field("values", 1, REQUIRED, new StringType()))));

    CompatibilityReport report = checker.checkCompatibility(oldSchema, newSchema);

    assertThat(report.isCompatible()).isFalse();
    assertThat(report.getMessages()).containsExactly("at tags:new field is more restrictive: values");
  }

  @Test
  void mapKeyRenameIsIncompatible() {
    StructType oldSchema = struct(field(
        "attributes",
        1,
        REQUIRED,
        new MapType(
            field("key", 1, REQUIRED, new StringType()), field("value", 2, REQUIRED, new I32Type()))));
    StructType newSchema = struct(field(
        "attributes",
        1,
        REQUIRED,
        new MapType(
            field("renamed", 1, REQUIRED, new StringType()), field("value", 2, REQUIRED, new I32Type()))));

    CompatibilityReport report = checker.checkCompatibility(oldSchema, newSchema);

    assertThat(report.isCompatible()).isFalse();
    assertThat(report.getMessages()).containsExactly("at attributes:field names are different: key vs renamed");
  }

  @Test
  void mapValueStructChangeIsReportedWithTheMapValuePath() {
    StructType oldSchema = struct(field(
        "attributes",
        1,
        REQUIRED,
        new MapType(
            field("key", 1, REQUIRED, new StringType()),
            field("value", 2, REQUIRED, struct(field("n", 1, REQUIRED, new I32Type()))))));
    StructType newSchema = struct(field(
        "attributes",
        1,
        REQUIRED,
        new MapType(
            field("key", 1, REQUIRED, new StringType()),
            field("value", 2, REQUIRED, struct(field("n", 1, REQUIRED, new I64Type()))))));

    CompatibilityReport report = checker.checkCompatibility(oldSchema, newSchema);

    assertThat(report.isCompatible()).isFalse();
    assertThat(report.getMessages()).containsExactly("at attributes.value:type is not compatible: I32 vs I64");
  }

  @Test
  void allIncompatibilitiesAreCollected() {
