  @Test
  void compatibleReportsHaveNoMessagesButAreStillReports() {
    CompatibilityReport report = checker.checkCompatibility(oldSchema(), oldSchema());

    assertThat(report.prettyMessages()).isEmpty();
    assertThat(report.toString()).contains("isCompatible=true").contains("hasEmptyStruct=false");
