import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import org.apache.parquet.thrift.struct.ThriftType.I32Type;
import org.apache.parquet.thrift.struct.ThriftType.StringType;
import org.apache.parquet.thrift.struct.ThriftType.StructType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class CompatibilityRunnerTest {

  private static final String TEST_PERSON = "org.apache.parquet.thrift.test.TestPerson";

  /** Whatever the commandline entry point printed while it was running. */
  private static final class Output {
    private final String out;
    private final String err;

    private Output(String out, String err) {
      this.out = out;
      this.err = err;
    }
  }

  private static ThriftField field(String name, int id, ThriftField.Requirement requirement, ThriftType type) {
    return new ThriftField(name, (short) id, requirement, type);
  }

  private static StructType struct(ThriftField... fields) {
    return new StructType(Arrays.asList(fields));
  }

  private static Path writeSchema(Path file, StructType struct) throws IOException {
    Files.write(file, struct.toJSON().getBytes(StandardCharsets.UTF_8));
    return file;
  }

  private static Output runMain(String... args) throws Exception {
    PrintStream originalOut = System.out;
    PrintStream originalErr = System.err;
    ByteArrayOutputStream outBuffer = new ByteArrayOutputStream();
    ByteArrayOutputStream errBuffer = new ByteArrayOutputStream();
    System.setOut(new PrintStream(outBuffer, true, StandardCharsets.UTF_8.name()));
    System.setErr(new PrintStream(errBuffer, true, StandardCharsets.UTF_8.name()));
    try {
      CompatibilityRunner.main(args);
    } finally {
      System.setOut(originalOut);
      System.setErr(originalErr);
    }
    return new Output(
        outBuffer.toString(StandardCharsets.UTF_8.name()), errBuffer.toString(StandardCharsets.UTF_8.name()));
  }

  @Test
  void compareJsonSucceedsForIdenticalSchemas(@TempDir Path tempDir) throws Exception {
    StructType struct =
        struct(field("count", 1, REQUIRED, new I32Type()), field("name", 2, OPTIONAL, new StringType()));
    Path oldJson = writeSchema(tempDir.resolve("old.json"), struct);
    Path newJson = writeSchema(tempDir.resolve("new.json"), struct);

    Output output = runMain("compare-json", oldJson.toString(), newJson.toString());

    assertThat(output.out).contains("[success] schema is compatible");
    assertThat(output.err).isEmpty();
  }

  @Test
  void compareJsonSucceedsWhenAFieldIsOnlyRelaxed(@TempDir Path tempDir) throws Exception {
    Path oldJson = writeSchema(tempDir.resolve("old.json"), struct(field("count", 1, REQUIRED, new I32Type())));
    Path newJson = writeSchema(tempDir.resolve("new.json"), struct(field("count", 1, OPTIONAL, new I32Type())));

    Output output = runMain("compare-json", oldJson.toString(), newJson.toString());

    assertThat(output.out).contains("[success] schema is compatible");
    assertThat(output.out).doesNotContain("schema not compatible");
  }

  @Test
  void compareJsonFailsWhenTheOldSchemaFileDoesNotExist(@TempDir Path tempDir) {
    Path missing = tempDir.resolve("missing.json");
    Path newJson = tempDir.resolve("new.json");

    assertThatThrownBy(() -> runMain("compare-json", missing.toString(), newJson.toString()))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("can not find file")
        .hasMessageContaining(missing.toString());
  }

  @Test
  void compareJsonFailsWhenTheNewSchemaFileDoesNotExist(@TempDir Path tempDir) throws Exception {
    Path oldJson = writeSchema(tempDir.resolve("old.json"), struct(field("count", 1, REQUIRED, new I32Type())));
    Path missing = tempDir.resolve("missing.json");

    assertThatThrownBy(() -> runMain("compare-json", oldJson.toString(), missing.toString()))
        .isInstanceOf(RuntimeException.class)
        .hasMessageContaining("can not find file")
        .hasMessageContaining(missing.toString());
  }

  @Test
  void compareJsonPropagatesParsingErrorsForInvalidJson(@TempDir Path tempDir) throws Exception {
    Path oldJson = writeSchema(tempDir.resolve("old.json"), struct(field("count", 1, REQUIRED, new I32Type())));
    Path invalid = tempDir.resolve("invalid.json");
    Files.write(invalid, "this is not json".getBytes(StandardCharsets.UTF_8));

    assertThatThrownBy(() -> runMain("compare-json", oldJson.toString(), invalid.toString()))
        .isInstanceOf(IOException.class);
  }

  @Test
  void unknownOperatorsAreIgnored() throws Exception {
    Output output = runMain("unknown-operator");

    assertThat(output.out).isEmpty();
    assertThat(output.err).isEmpty();
  }

  @Test
  void missingArgumentsFailInsteadOfRunningTheChecker() {
    assertThatThrownBy(() -> runMain()).isInstanceOf(RuntimeException.class);
  }

  @Test
  void generateJsonWritesAThriftSchemaFile(@TempDir Path tempDir) throws Exception {
    Output output = runMain("generate-json", "person", TEST_PERSON, tempDir.toString());

    assertThat(output.out).isEmpty();
    Path written = tempDir.resolve("person.json");
    assertThat(written).exists();

    ThriftType parsed = ThriftType.fromJSON(new String(Files.readAllBytes(written), StandardCharsets.UTF_8));
    assertThat(parsed).isInstanceOf(StructType.class);
    assertThat(((StructType) parsed).getChildren()).isNotEmpty();
  }

  @Test
  void generateJsonThenCompareJsonRoundTripsARealThriftClass(@TempDir Path tempDir) throws Exception {
    runMain("generate-json", "person", TEST_PERSON, tempDir.toString());
    Path written = tempDir.resolve("person.json");
    Path copy = tempDir.resolve("person-copy.json");
    Files.copy(written, copy);

    Output output = runMain("compare-json", written.toString(), copy.toString());

    assertThat(output.out).contains("[success] schema is compatible");
  }

  @Test
  void generateJsonFailsForUnknownClasses(@TempDir Path tempDir) {
    assertThatThrownBy(
            () -> runMain("generate-json", "unknown", "org.apache.parquet.thrift.test.DoesNotExist", tempDir.toString()))
        .isInstanceOf(ClassNotFoundException.class);
  }
}
